window.VOCAB_TERMS = window.VOCAB_TERMS || {};
window.VOCAB_TERMS["ai"] = {"ai--a2a":{"definition":"맡기려면 상대가 무엇을 할 수 있는지부터 알아야 한다. 그래서 A2A 는 에이전트마다 명함 한 장(Agent Card)을 내걸게 하고, 부르는 쪽이 그 명함을 읽어 통하는 방식 하나를 골라 말을 건다. 규격 1.0 이 나와 있고 파이썬과 자바스크립트 공식 SDK 가 그것을 구현한다.","name":"Agent :: 스스로 일하는 쪽\n2 :: to 를 숫자로 쓴 것\nAgent :: 일을 맡길 상대\nProtocol :: 약속\n= 붙여 읽으면 \"에이전트가 에이전트에게 거는 약속\". 사람이 가운데 끼지 않는 자리다","analogy":"옷을 맡기면 번호표를 주고, 그 번호로 다 됐는지 물어보고 찾아가는 세탁소 접수증.","example":"일정을 잡아 주는 비서에게 부탁했더니 그쪽이 항공권 찾는 다른 비서에게 다시 물어보고 답을 가져오는 장면이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"규격 1.0 은 오가는 방식을 셋 정해 뒀다 — JSON-RPC, HTTP+JSON/REST, 그리고 [[gRPC]]. 셋 다 같은 처리기에 물릴 수 있어서 에이전트 하나를 세 방식으로 동시에 열어 둘 수도 있고, 부르는 쪽은 명함에 적힌 목록과 자기가 선호하는 순서를 맞춰 하나를 고른다.\n\n오래 걸리는 일은 한 번에 답이 오지 않는다. 작업이 열렸다는 소식, 상태가 바뀌었다는 소식, 결과물이 나왔다는 소식이 스트림으로 차례차례 흘러온다. 스트림을 계속 열어 둘 수 없는 쪽을 위해 [[Webhook]] 방식도 있다 — 명함에 푸시 알림을 켜 두고 받을 주소를 넘기면 그 주소로 같은 소식들이 날아온다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **몇 시간 걸리는 일** — 연결을 계속 붙들고 있을 수 없으면 받을 주소를 넘겨 두고 끊는다. 진행과 결과가 그 주소로 날아온다.\n- **여러 방식 동시 공개** — 같은 에이전트 하나를 JSON-RPC · REST · gRPC 로 한꺼번에 열어 두고, 부르는 쪽이 되는 것을 고르게 한다.\n- **가짜 명함 막기** — 명함에 서명을 붙여 두면 부르는 쪽이 공개된 열쇠로 그 명함이 진짜인지 확인하고 나서 말을 건다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **에이전트를 붙일 일이면 무엇이든 A2A 다** — 한 프로그램 안에서 함수로 부르면 될 일까지 규약에 태우면 느려지기만 한다. 서로 다른 곳에서 따로 도는 에이전트끼리 쓰라고 있는 것이다.\n- **명함만 받아 오면 바로 부를 수 있다** — 명함은 무엇을 할 수 있는지를 적어둔 것이지 들어가도 좋다는 허락이 아니다. 인증은 따로 붙여 보내야 하고, 안 붙으면 거절이 돌아온다.\n- **일을 맡기면 답이 곧바로 온다** — 오래 걸리는 일은 작업 하나가 열리고 상태가 여러 번 바뀐 뒤에야 결과물이 나온다."}],"figure":"```도해\n흐름: 에이전트가 다른 에이전트에게 일을 맡기면 어떻게 되나\n부르는 쪽 :: 상대의 명함(Agent Card)을 먼저 받아 온다\n전송 고르기 :: 명함에 적힌 방식 중 통하는 것 하나를 고른다\n맡기기 :: 할 일을 메시지로 적어 보낸다\n받는 쪽 :: 작업(Task)을 열고 진행 상태를 흘려보낸다\n< 부르는 쪽 :: 다 되면 결과물(Artifact)을 받는다\n= 사람이 화면을 거치지 않고 에이전트끼리 일을 주고받는다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 에이전트마다 부르는 법이 다르면 무엇이 힘든가\n공용 규약 없이 || A2A 로\n붙이는 비용 :: 상대마다 새로 짠다 || 명함 한 장이면 된다\n긴 작업 :: 끝났는지 계속 묻는다 || 진행 상태가 흘러온다\n상대 교체 :: 코드를 다시 짠다 || 명함만 바꿔 끼운다\n= 붙이는 법이 하나면, 에이전트를 늘려도 붙이는 일은 안 늘어난다\n```\n\n에이전트가 하나뿐이면 규약이 필요 없다. 문제는 여럿을 잇기 시작할 때 생긴다. 상대마다 부르는 법이 다르면 잇는 곳이 늘어날 때마다 새로 짜야 하고, 상대를 바꾸면 그 코드를 또 버려야 한다.\n\nA2A 는 **부르는 법을 상대에게서 읽어 오게** 해서 이 자리를 없앤다. 상대가 무엇을 할 수 있고 어떤 방식으로 받는지가 명함에 적혀 있으므로, 부르는 쪽은 명함을 읽는 법 하나만 알면 된다."},"recap":"**\"에이전트끼리 일을 맡기는 그 공용 접수증\"** 이라고 읽으면 된다. 상대의 명함을 먼저 읽고 통하는 방식 하나를 골라 넘기기 때문에, 상대를 갈아 끼워도 부르는 쪽은 읽는 법을 그대로 쓴다. 오래 걸리는 일은 작업이 하나 열려 상태가 흘러오고, 다 되면 결과물이 돌아온다.","kid":"세탁소에 옷을 맡기면 번호표를 주지? 어느 가게든 번호표 모양이 똑같으면 아무 가게에나 맡기고 아무 가게에서나 찾아올 수 있어. 그러면 가게끼리도 서로 일을 넘기기가 쉬워져.","check":[{"q":"상대 에이전트를 부르기 전에 무엇을 먼저 받아 오나","at":"그림"},{"q":"몇 시간 걸리는 일을 맡겼는데 연결을 계속 열어 둘 수 없다면","at":"작동 원리"},{"q":"명함을 제대로 받아 왔는데도 거절당하는 이유는 무엇인가","at":"흔한 오해"}],"myths":[{"wrong":"에이전트를 붙일 일이면 무엇이든 A2A 다","right":"한 프로그램 안에서 함수로 부르면 될 일까지 규약에 태우면 느려지기만 한다. 서로 다른 곳에서 따로 도는 에이전트끼리 쓰라고 있는 것이다."},{"wrong":"명함만 받아 오면 바로 부를 수 있다","right":"명함은 무엇을 할 수 있는지를 적어둔 것이지 들어가도 좋다는 허락이 아니다. 인증은 따로 붙여 보내야 하고, 안 붙으면 거절이 돌아온다."},{"wrong":"일을 맡기면 답이 곧바로 온다","right":"오래 걸리는 일은 작업 하나가 열리고 상태가 여러 번 바뀐 뒤에야 결과물이 나온다."}],"cases":[{"label":"몇 시간 걸리는 일","note":"연결을 계속 붙들고 있을 수 없으면 받을 주소를 넘겨 두고 끊는다. 진행과 결과가 그 주소로 날아온다."},{"label":"여러 방식 동시 공개","note":"같은 에이전트 하나를 JSON-RPC · REST · gRPC 로 한꺼번에 열어 두고, 부르는 쪽이 되는 것을 고르게 한다."},{"label":"가짜 명함 막기","note":"명함에 서명을 붙여 두면 부르는 쪽이 공개된 열쇠로 그 명함이 진짜인지 확인하고 나서 말을 건다."}],"dia":{"shape":"흐름","title":"에이전트가 다른 에이전트에게 일을 맡기면 어떻게 되나","rows":[{"who":"부르는 쪽","what":"상대의 명함(Agent Card)을 먼저 받아 온다"},{"who":"전송 고르기","what":"명함에 적힌 방식 중 통하는 것 하나를 고른다"},{"who":"맡기기","what":"할 일을 메시지로 적어 보낸다"},{"who":"받는 쪽","what":"작업(Task)을 열고 진행 상태를 흘려보낸다"},{"who":"부르는 쪽","what":"다 되면 결과물(Artifact)을 받는다","back":true}],"sum":"사람이 화면을 거치지 않고 에이전트끼리 일을 주고받는다"}},"ai--ai-agent":{"definition":"챗봇은 물어보면 답하고 끝난다. 에이전트는 목표를 여러 단계로 쪼개고, 필요한 도구를 골라 쓰고, 그 결과를 보고 다음 행동을 정하는 일을 목표에 닿을 때까지 반복한다.","name":"AI :: 사람처럼 판단하는 것\nAgent :: 대신 일하는 사람\n= 붙여 읽으면 \"스스로 판단해 대신 일하는 사람\". 답을 아는 쪽이 아니라 다녀오는 쪽이다","analogy":"심부름을 맡긴 사람. 백과사전은 물어본 것만 답하지만, 심부름꾼은 가게에 다녀오고 문이 닫혀 있으면 다른 가게를 찾는다.","example":"여행 일정을 짜 달라고 맡겼더니 검색과 지도를 스스로 오가며 몇 번을 고쳐 일정표 한 장을 내놓는다.","tryit":"챗봇에게 \"지금 서울 날씨\" 를 물어보라. 검색을 다녀와 답하면 도구를 쥔 것이고, 모른다고 하면 못 쥔 것이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"가장 널리 쓰이는 방식이 ReAct다. 생각(Thought)으로 무엇이 필요한지 정하고, 행동(Action)으로 도구를 부르고, 관찰(Observation)로 결과를 확인한다. 목표에 닿았으면 끝내고, 아니면 관찰 결과를 들고 다시 생각으로 돌아간다.\n\n기억은 두 종류로 나뉜다. 지금 하고 있는 작업의 진행 상황이 단기 기억이고, 과거에 무엇이 통했고 무엇이 실패했는지가 장기 기억이다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **여러 도구를 거치는 조사** — 검색으로 자료를 모으고 계산기로 수치를 맞춘 다음, 정리해서 한 번에 내놓는다.\n- **파일을 다루는 작업** — 폴더를 훑고 조건에 맞는 파일만 골라낸 뒤 내용을 읽어 요약한다.\n- **실패를 딛고 가는 작업** — 파일 이름이 틀려 읽기에 실패하면 목록을 먼저 확인하고 이름을 고쳐 다시 읽는다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **에이전트는 더 똑똑한 모델이다** — 모델은 같은 것을 쓴다. 달라지는 건 도구를 쥐여주고 결과를 다시 보게 만든 바깥 구조다.\n- **목표만 주면 알아서 다 한다** — 쓸 수 있는 도구를 미리 정해줘야 한다. 도구함에 없는 일은 아무리 반복해도 못 한다.\n- **실패해도 재시도하니 결국 성공한다** — 판단 자체가 어긋나 있으면 같은 실수를 되풀이할 뿐이다. 그래서 몇 번까지 돌지 정해둔다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **반복 횟수를 정해둔다.** 목표에 닿지 못하면 끝없이 돈다. 몇 바퀴까지 돌지 정하고 그 뒤에는 멈추게 한다.\n- **도구가 할 수 있는 일의 범위를 정해둔다.** 파일을 지우거나 돈을 쓰는 도구를 쥐여주면 판단이 어긋났을 때 되돌리기 어렵다."}],"figure":"```도해\n흐름: 에이전트는 무슨 순서로 일을 하나\n사용자 :: 목표를 말한다. \"내일 날씨 알려줘\"\nLLM :: 무엇이 필요한지 판단한다. 날씨 도구다\n에이전트 :: 도구를 부른다. 도시와 날짜를 넘긴다\n도구 :: 실행하고 결과를 돌려준다\nLLM :: 결과를 보고 더 할 일이 있는지 정한다\n@ 다시 판단으로 :: 없으면 답하고 끝, 있으면 한 바퀴 더\n= 생각하고 행동하고 결과를 보는 한 바퀴를, 목표에 닿을 때까지 돈다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 여러 단계가 필요한 일을 시키면 어떻게 되나\n일반 LLM || AI Agent\n할 수 있는 일 :: 답만 돌려준다 || 도구를 직접 쓴다\n단계 :: 한 번 답하고 끝 || 목표까지 반복\n오류가 나면 :: 거기서 멈춘다 || 고쳐서 다시 한다\n= 답을 아는 것과 일을 끝내는 것은 다르다\n```\n\n\"내일 날씨를 보고 비가 오면 우산 가격을 비교해줘\"를 일반 LLM에게 시키면 답은 하나다. 날씨를 조회할 수 없고 웹을 볼 수 없다는 것. 사용자가 직접 날씨를 확인하고, 쇼핑몰을 열고, 가격을 옮겨 적어야 한다.\n\n에이전트는 그 사이를 메운다. 날씨 도구를 부르고, 결과가 \"비\"면 검색 도구로 넘어가고, 모은 가격을 정리해서 내놓는다. 중간에 도구가 실패해도 무엇이 잘못됐는지 보고 다시 시도한다."},"compose":{"label":"무엇으로 되어 있나","head":"🧱 구성","body":"```도해\n층: 어디까지가 모델이고 어디부터 붙인 것인가\nLLM :: 모델 자체. 다음 행동을 고르기만 한다\n계획·기억 :: 목표를 단계로 쪼개고 지금까지를 들고 있다\n도구 :: 웹 검색, 파일 읽기, 코드 실행. 밖에 닿는 손\n= 에이전트로 만든 건 모델이 아니라 그 위에 얹은 두 겹이다\n```"},"recap":"**\"목표만 주면 알아서 다녀오는 그 심부름꾼\"** 이라고 읽으면 된다. 모델이 달라져서가 아니라 도구와 반복이 바깥에 붙어 있어서 일을 끝까지 밀고 간다. 쓸 도구와 멈출 지점을 정하는 것은 사람의 몫으로 남는다.","kid":"두부 사 오라고 심부름을 시키면 어느 가게로 갈지, 문이 닫혔으면 어디로 갈지 네가 알아서 정하지? 이것도 똑같아. 무엇을 해 달라고만 말하면 스스로 여기저기 다녀오고, 헛걸음하면 다른 데로 가서 기어이 해 놓고 와.","check":[{"q":"같은 LLM을 쓰는데 에이전트만 여러 단계짜리 일을 끝낼 수 있는 이유는","at":"흔한 오해"},{"q":"도구를 실행했더니 오류가 났다. 에이전트는 그다음에 무엇을 하나","at":"실제 사례"},{"q":"반복 횟수에 한계를 두지 않으면 무슨 일이 생기나","at":"주의사항"}],"myths":[{"wrong":"에이전트는 더 똑똑한 모델이다","right":"모델은 같은 것을 쓴다. 달라지는 건 도구를 쥐여주고 결과를 다시 보게 만든 바깥 구조다."},{"wrong":"목표만 주면 알아서 다 한다","right":"쓸 수 있는 도구를 미리 정해줘야 한다. 도구함에 없는 일은 아무리 반복해도 못 한다."},{"wrong":"실패해도 재시도하니 결국 성공한다","right":"판단 자체가 어긋나 있으면 같은 실수를 되풀이할 뿐이다. 그래서 몇 번까지 돌지 정해둔다."}],"cases":[{"label":"여러 도구를 거치는 조사","note":"검색으로 자료를 모으고 계산기로 수치를 맞춘 다음, 정리해서 한 번에 내놓는다."},{"label":"파일을 다루는 작업","note":"폴더를 훑고 조건에 맞는 파일만 골라낸 뒤 내용을 읽어 요약한다."},{"label":"실패를 딛고 가는 작업","note":"파일 이름이 틀려 읽기에 실패하면 목록을 먼저 확인하고 이름을 고쳐 다시 읽는다."}],"dia":{"shape":"흐름","title":"에이전트는 무슨 순서로 일을 하나","rows":[{"who":"사용자","what":"목표를 말한다. \"내일 날씨 알려줘\""},{"who":"LLM","what":"무엇이 필요한지 판단한다. 날씨 도구다"},{"who":"에이전트","what":"도구를 부른다. 도시와 날짜를 넘긴다"},{"who":"도구","what":"실행하고 결과를 돌려준다"},{"who":"LLM","what":"결과를 보고 더 할 일이 있는지 정한다"}],"sum":"생각하고 행동하고 결과를 보는 한 바퀴를, 목표에 닿을 때까지 돈다","loop":{"who":"다시 판단으로","what":"없으면 답하고 끝, 있으면 한 바퀴 더"}}},"ai--agent":{"definition":"LLM은 물으면 답만 한다. 여기에 검색이나 실행 같은 도구를 쥐여주고, 한 번에 끝내지 않고 결과를 보며 다음 행동을 다시 정하게 만든 것이 Agent다.","name":"Agent :: 대신 해 주는 쪽\n= 라틴어 agere(\"하다\")에서 온 말이다. 중개인을 agent 라 부르는 그 뜻 그대로, 시킨 사람 대신 움직이는 쪽이다","analogy":"심부름. 재료를 사 오라고만 말하면 알아서 가게를 고르고, 물건이 없으면 다른 가게로 간다. 한 걸음마다 지시하는 것과 다르다.","example":"스마트폰에 대고 내일 일곱 시에 깨워 달라고 말하면 알람 앱이 열려 시각까지 맞춰져 있다.","tryit":"폰의 음성 비서에게 \"내일 아침 일곱 시에 깨워 줘\" 라고 말해 보라. 앱을 열고 시각을 넣는 중간 단계를 대신 밟는다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"Agent 를 이루는 것은 넷이다.\n\n- **LLM** — 다음에 무엇을 할지 정하는 자리\n- **도구** — 검색, 계산, 파일 읽기. 밖에 닿는 손\n- **기억** — 지금까지 무엇을 했는지 들고 있다\n- **멈춤 조건** — 횟수나 비용의 한도. 없으면 안 끝난다\n\n도구가 없으면 말만 하고, 기억이 없으면 같은 일을 반복한다.\n\n행동을 정하는 방식에는 몇 가지 틀이 있다. 생각하고 도구를 쓰고 결과를 본 뒤 다시 생각하는 것을 반복하는 ReAct, 전체 계획을 먼저 세워두고 단계별로 실행하는 Plan-and-Execute가 대표적이다.\n\n멈춤 조건은 설계에 포함해야 한다. 최대 반복 횟수를 정해두지 않으면 답을 못 찾는 상황에서 같은 자리를 맴돈다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **메일 정리** — 메일을 읽어오는 도구를 붙여주면 목록을 훑고 중요한 것만 골라 요약해 돌려준다.\n- **자료 조사** — 검색, 정리, 문서 작성을 지시 한 번으로 이어서 한다.\n- **코드 수정** — 코드를 쓰고 실행해본 뒤 오류가 나면 고쳐서 다시 실행하는 것을 반복한다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **Agent는 LLM보다 똑똑한 모델이다** — 모델은 같은 것을 쓴다. 도구를 쥐여주고 여러 번 돌리는 껍데기가 붙었을 뿐이다.\n- **한 번 시키면 알아서 끝까지 간다** — 멈출 조건을 정해두지 않으면 끝을 못 찾고 횟수만 채운 뒤 중간 상태로 돌아온다.\n- **Agent를 쓰면 답이 더 정확해진다** — 틀리게 답하던 모델은 여전히 틀린다. 달라지는 건 정확도가 아니라 할 수 있는 일의 범위다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **호출 횟수가 곧 비용이다.** 한 번의 대화가 열 번 넘는 모델 호출로 늘어난다. 반복 한도를 정해두지 않으면 비용이 예측되지 않는다.\n- **위험한 도구는 처음부터 빼둔다.** 삭제나 결제처럼 되돌릴 수 없는 도구는 목록에서 제외하거나 사람 확인을 거치게 한다."}],"figure":"```도해\n흐름: 목표 한 줄을 주면 Agent 는 무엇을 하나\n사용자 :: \"경쟁사 분석 보고서 써줘\" 한 줄만 준다\nAgent :: 무엇부터 할지 정한다. 검색이 먼저다\n도구 :: 검색을 실행하고 결과를 돌려준다\nAgent :: 결과를 보고 다음 할 일을 다시 정한다\nAgent :: 충분하다고 판단하면 멈춘다\n< 사용자 :: 완성된 보고서를 받는다\n= 지시가 아니라 목표를 주고, 중간 판단을 넘기는 것이 차이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: LLM 에게만 물으면 어디서 막히나\nAgent 없이 || Agent 로\n바깥 정보 :: 모른다고 답함 || 검색해서 가져옴\n여러 단계 :: 사람이 이어붙임 || 스스로 이어감\n중간 실패 :: 거기서 멈춤 || 다른 길을 시도\n= 답을 만드는 것과 일을 끝내는 것은 다르다\n```\n\n\"이메일 확인하고 중요한 것만 요약해줘\"라고 하면 LLM은 이메일에 닿을 수가 없어서 못 한다고 답한다. 자료를 모으고 정리하고 문서로 쓰는 일도 마찬가지다. 각 단계는 할 수 있지만 그걸 이어붙이는 건 사람 몫으로 남는다.\n\nAgent는 그 이어붙이는 자리를 가져간다. 도구를 호출해 결과를 받고, 그 결과를 보고 다음에 무엇을 할지 다시 정한다. 도중에 오류가 나도 사람을 부르지 않고 다른 방법을 먼저 시도한다."},"recap":"**\"한 걸음씩 시키지 않고 목표만 던지는 그 구조\"** 라고 읽으면 된다. 모델이 똑똑해진 것이 아니라 손발이 생긴 것이고, 그만큼 반복 한도와 권한을 정해두는 일이 따라온다.","kid":"\"저 골목으로 가서 오른쪽, 두 번째 가게\" 처럼 하나하나 시키는 대신 그냥 \"카레 재료 사 와\" 하고 보내는 거야. 그러면 어느 가게에 갈지 스스로 고르고, 물건이 없으면 다른 가게까지 들러서 사 와. 네가 옆에서 다음에 뭘 하라고 말해 줄 필요가 없어.","check":[{"q":"같은 모델을 쓰는데 Agent로 감쌌을 때만 할 수 있게 되는 일은 어떤 것인가","at":"실제 사례"},{"q":"반복 한도를 정해두지 않으면 무슨 일이 벌어지나","at":"주의사항"},{"q":"메일을 요약해달라는 요청에서 LLM 혼자로는 어디서 막히나","at":"해결하는 문제"}],"myths":[{"wrong":"Agent는 LLM보다 똑똑한 모델이다","right":"모델은 같은 것을 쓴다. 도구를 쥐여주고 여러 번 돌리는 껍데기가 붙었을 뿐이다."},{"wrong":"한 번 시키면 알아서 끝까지 간다","right":"멈출 조건을 정해두지 않으면 끝을 못 찾고 횟수만 채운 뒤 중간 상태로 돌아온다."},{"wrong":"Agent를 쓰면 답이 더 정확해진다","right":"틀리게 답하던 모델은 여전히 틀린다. 달라지는 건 정확도가 아니라 할 수 있는 일의 범위다."}],"cases":[{"label":"메일 정리","note":"메일을 읽어오는 도구를 붙여주면 목록을 훑고 중요한 것만 골라 요약해 돌려준다."},{"label":"자료 조사","note":"검색, 정리, 문서 작성을 지시 한 번으로 이어서 한다."},{"label":"코드 수정","note":"코드를 쓰고 실행해본 뒤 오류가 나면 고쳐서 다시 실행하는 것을 반복한다."}],"dia":{"shape":"흐름","title":"목표 한 줄을 주면 Agent 는 무엇을 하나","rows":[{"who":"사용자","what":"\"경쟁사 분석 보고서 써줘\" 한 줄만 준다"},{"who":"Agent","what":"무엇부터 할지 정한다. 검색이 먼저다"},{"who":"도구","what":"검색을 실행하고 결과를 돌려준다"},{"who":"Agent","what":"결과를 보고 다음 할 일을 다시 정한다"},{"who":"Agent","what":"충분하다고 판단하면 멈춘다"},{"who":"사용자","what":"완성된 보고서를 받는다","back":true}],"sum":"지시가 아니라 목표를 주고, 중간 판단을 넘기는 것이 차이다"}},"ai--agent-memory":{"definition":"모델이 한 번에 볼 수 있는 양은 [[Context Window]] 로 정해져 있고, 그 창이 닫히면 안에 있던 것은 사라진다. 2023년 MemGPT 논문이 이 문제를 운영체제의 계층적 기억 장치에 빗대었다 — 빠른 곳과 느린 곳 사이로 자료를 옮겨서 큰 기억 장치가 있는 것처럼 보이게 하는 방식을 \"가상 컨텍스트 관리\" 라 부른다. 지금 [[Agent]] 에 붙이는 기억 도구도 같은 자리에 선다 — 창 밖에 파일을 두고 필요할 때만 읽어 온다.","name":"Agent :: 대신 일하는 쪽\nMemory :: 남겨 두는 기억\n= 붙여 읽으면 \"대신 일하는 쪽이 남겨 두는 기억\". 머리가 아니라 종이에 남는다","analogy":"공사장 작업 일지. 오늘 사람이 바뀌어도 일지를 펴 보면 어제 어디까지 했는지가 그대로 적혀 있다.","example":"어제 한참 설명한 취향을 오늘 처음처럼 다시 묻는 그 순간이 이게 없을 때다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"**켜는 손잡이는 도구 한 줄이다.** Anthropic 문서 기준으로, 요청의 도구 목록에 기억 도구를 넣으면 켜진다. 그러면 모델은 파일을 보고·만들고·일부만 바꿔 쓰고·끼워 넣고·지우고·이름을 바꾸는 여섯 가지를 요청할 수 있다. 중요한 것은 **요청만 한다**는 점이다. 실제로 파일을 읽고 쓰는 것은 내 쪽 코드이고, 그 결과를 돌려주면 모델이 이어서 일한다.\n\n경로는 `/memories` 라는 앞자락 하나로 고정되어 있다. 그 앞자락을 실제 저장소의 어디에 붙일지는 내가 정한다 — 사용자마다 다른 폴더에 붙이면 사람마다 기억이 갈리고, 같은 폴더에 붙이면 지난 대화의 기록이 그대로 이어진다. **여기가 이 기능에서 가장 크게 달라지는 손잡이다.**\n\n도구를 넣으면 지시문에 한 대목이 자동으로 붙는다 — 무엇보다 먼저 기억 폴더를 보라는 것, 그리고 **언제든 창이 초기화될 수 있다고 가정하라**는 것이다. 그래서 켜는 순간 매 대화의 첫 동작이 폴더 열기가 된다. 짝이 되는 손잡이가 둘 더 있다. 오래된 도구 결과를 내 쪽에서 지우는 컨텍스트 편집, 그리고 대화가 한도에 가까워지면 서버가 알아서 요약하는 압축이다. 둘은 창을 줄이는 쪽이고, 기억은 줄여도 남길 것을 남기는 쪽이다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **여러 번에 걸쳐 만드는 프로젝트** — 첫 대화가 진행 기록과 할 일 목록을 파일로 세워 두고, 다음 대화는 그 파일부터 읽고 시작한다. 코드를 다시 훑을 필요가 없어진다.\n- **사람마다 다른 취향** — 앞자락을 사용자별 폴더에 붙여 둔다. 지난번에 말한 것을 다음에 다시 묻지 않는다.\n- **끊긴 자리에서 재개** — 창이 초기화돼도 마지막으로 적힌 줄이 다음 시작점이 된다. 그래서 한 가지를 끝낼 때마다 적어 둔다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **모델이 스스로 기억한다** — 아니다. 모델은 파일을 열고 적어 달라고 요청할 뿐이고, 실제 읽기와 쓰기는 내 쪽에서 한다. 내가 안 만들면 아무것도 안 남는다.\n- **기억을 켜면 창이 넉넉해진다** — 한 번에 볼 수 있는 양은 그대로다. 다 싣지 않고 필요할 때만 꺼내 오게 만드는 것이지, 창이 커지는 게 아니다.\n- **기억은 켜 두는 편이 항상 낫다** — 한 번에 끝나는 일에는 폴더를 여는 왕복만 늘어난다. 오래 걸리고 여러 번에 나눠 하는 일에서만 값을 한다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **폴더 밖으로 나가는 경로를 막아라.** Anthropic 문서는 `/memories/../../secrets.env` 같은 경로가 폴더 바깥에 닿는다고 경고로 따로 적어 두었다. 모든 명령의 경로를 검사해야 한다.\n- **커지는 것을 재라.** 파일 크기에 상한을 두고, 한 번에 돌려주는 글자 수도 끊는다. 오래 손대지 않은 파일은 주기적으로 지우라고 문서가 권한다.\n- **잘못 적힌 한 줄이 오래 간다.** 폴더에 한 번 적히면 다음 대화들이 그것을 그대로 사실로 삼는다. 민감한 값은 적히기 전에 걸러내는 검사를 붙이라고 문서가 권한다."}],"figure":"```도해\n흐름: 대화가 끝나도 어떻게 이어서 일하나\n새 대화 :: 일을 시작하기 전에 적어 둔 폴더부터 본다\n읽기 :: 지난번에 어디까지 했는지 꺼내 온다\n일하기 :: 처음부터 다시 하지 않고 그 자리에서 잇는다\n적기 :: 새로 알아낸 것과 남은 일을 파일에 적는다\n@ 다음 대화로 :: 창은 닫혀도 폴더는 그대로 남는다\n= 기억하는 것이 아니라 적어 두는 것이다. 다음 대화가 그 종이를 편다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 적어 두지 않으면 무슨 일이 생기나\n기록 없이 || 기록으로\n새 대화 :: 처음부터 다시 || 적은 데서 잇는다\n알아낸 것 :: 창이 닫히면 끝 || 파일에 남는다\n긴 작업 :: 끊기면 도로 원점 || 마지막 줄부터 재개\n= 창은 닫히지만 폴더는 안 닫힌다\n```\n\n한 번에 끝나는 일이 아니면 창의 한도가 곧 벽이 된다. MemGPT 논문은 긴 대화와 큰 문서 분석이 바로 이 한도 때문에 막힌다고 적는다. 대화를 새로 열면 앞의 대화에서 알아낸 것은 하나도 안 남아 있고, 같은 설명을 다시 하게 된다.\n\n기록은 그 알아낸 것을 **창 밖의 파일로 내보낸다.** 창은 이번 차례에 필요한 것만 담고, 나머지는 필요할 때 꺼내 온다. Anthropic 문서는 이것을 \"필요한 때에 맞춘 맥락 가져오기\" 라 부르고, 미리 다 싣지 않고 배운 것을 파일에 적어 두었다가 나중에 읽어 오는 방식이라고 적는다."},"compose":{"label":"무엇으로 되어 있나","head":"🧱 구성","body":"```도해\n층: 지금 아는 것이 어디에 살아 있나\n지금 창 안 :: 이번 차례에 모델이 실제로 보고 있는 것\n적어 둔 폴더 :: 필요할 때만 열어서 읽어 오는 파일들\n내 쪽 저장소 :: 그 폴더를 실제로 담고 있는 디스크나 저장 공간\n= 위로 갈수록 좁고 가깝고, 아래로 갈수록 넓고 오래 간다\n```"},"recap":"**\"창이 닫혀도 남게 밖에 적어 두는 그 폴더\"** 라고 읽으면 된다. 모델은 적어 달라고 요청할 뿐이고 실제로 남기는 것은 내 쪽 저장소이므로, 무엇을 어디에 남길지는 처음부터 내가 정하는 일이다. 켜는 순간 매 대화가 폴더 열기로 시작하니, 한 번에 끝나는 일에는 굳이 켜지 않는다.","kid":"방과후 교실에서 만들던 걸 오늘 이어서 만들려면, 어제 어디까지 했는지 적어 둔 공책이 있어야겠지? 안 적어 두면 다음에 온 사람은 처음부터 다시 시작해. 그래서 그날 알아낸 걸 끝나기 전에 공책에 꼭 적어 두는 거야.","check":[{"q":"어제 하던 일을 오늘 이어서 하려면 어제의 대화가 무엇을 해 뒀어야 하나","at":"그림"},{"q":"기억을 켰는데 한 번에 보는 양은 왜 그대로인가","at":"흔한 오해"},{"q":"앞자락을 저장소의 어디에 붙이느냐가 왜 중요한가","at":"작동 원리"}],"myths":[{"wrong":"모델이 스스로 기억한다","right":"아니다. 모델은 파일을 열고 적어 달라고 요청할 뿐이고, 실제 읽기와 쓰기는 내 쪽에서 한다. 내가 안 만들면 아무것도 안 남는다."},{"wrong":"기억을 켜면 창이 넉넉해진다","right":"한 번에 볼 수 있는 양은 그대로다. 다 싣지 않고 필요할 때만 꺼내 오게 만드는 것이지, 창이 커지는 게 아니다."},{"wrong":"기억은 켜 두는 편이 항상 낫다","right":"한 번에 끝나는 일에는 폴더를 여는 왕복만 늘어난다. 오래 걸리고 여러 번에 나눠 하는 일에서만 값을 한다."}],"cases":[{"label":"여러 번에 걸쳐 만드는 프로젝트","note":"첫 대화가 진행 기록과 할 일 목록을 파일로 세워 두고, 다음 대화는 그 파일부터 읽고 시작한다. 코드를 다시 훑을 필요가 없어진다."},{"label":"사람마다 다른 취향","note":"앞자락을 사용자별 폴더에 붙여 둔다. 지난번에 말한 것을 다음에 다시 묻지 않는다."},{"label":"끊긴 자리에서 재개","note":"창이 초기화돼도 마지막으로 적힌 줄이 다음 시작점이 된다. 그래서 한 가지를 끝낼 때마다 적어 둔다."}],"dia":{"shape":"흐름","title":"대화가 끝나도 어떻게 이어서 일하나","rows":[{"who":"새 대화","what":"일을 시작하기 전에 적어 둔 폴더부터 본다"},{"who":"읽기","what":"지난번에 어디까지 했는지 꺼내 온다"},{"who":"일하기","what":"처음부터 다시 하지 않고 그 자리에서 잇는다"},{"who":"적기","what":"새로 알아낸 것과 남은 일을 파일에 적는다"}],"sum":"기억하는 것이 아니라 적어 두는 것이다. 다음 대화가 그 종이를 편다","loop":{"who":"다음 대화로","what":"창은 닫혀도 폴더는 그대로 남는다"}}},"ai--attention":{"definition":"낱말마다 \"무엇을 찾는가\"(질문) · \"나는 이런 것\"(표) · \"내가 담은 내용\" 세 벌을 만든다. 질문과 표를 맞춰 낱말마다 점수를 내고, 그 점수를 비율로 바꿔 내용을 섞는다. 2017년 논문 「Attention Is All You Need」는 이 장치 하나만 남기고 순환과 합성곱을 걷어냈다.","name":"Attention :: 어디를 볼지 고름\n= 이름이 곧 하는 일이다. 지금 자리를 정하려고 어느 낱말에 주의를 줄지 고른다","analogy":"과일 갈아 만든 한 잔. 재료를 다 넣되 딸기는 많이 바나나는 조금 넣어서 지금 만들 한 잔의 맛이 정해진다.","example":"번역기에 \"차를 마셨다\" 와 \"차를 몰았다\" 를 넣어 보면 \"차\" 가 서로 다른 낱말로 번역된다. 옆 낱말을 봤다는 뜻이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"점수는 질문 벡터와 표 벡터의 내적으로 낸다. 그대로 쓰면 차원이 커질수록 내적 값이 커지고, 그러면 다음 단계인 softmax 가 기울기가 거의 없는 구간으로 밀려난다. 그래서 표의 차원 `d_k` 의 제곱근으로 나눠 눌러 준다. 논문이 이 방식에 \"Scaled Dot-Product Attention\" 이라는 이름을 붙였다.\n\n한 번만 하지 않고 여러 갈래로 나눠서 한다. 원 논문은 갈래 8개를 쓰고, 전체 차원 512를 갈래 수로 나눠 갈래마다 64차원만 보게 했다. 갈래를 나누면 서로 다른 종류의 관계를 동시에 볼 수 있고, 갈래마다 차원이 좁아지므로 전체 계산량은 한 갈래로 할 때와 비슷하게 유지된다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **긴 입력이 유난히 비싼 이유** — 어텐션 점수 행렬은 글 길이의 제곱으로 커진다. 모델은 들어가는데 입력이 길어 메모리가 터지는 일이 여기서 난다.\n- **뒤를 못 보게 막기** — 다음 낱말을 맞히는 모델은 아직 안 나온 자리의 점수를 음의 무한대로 만들어 지운다. 정답을 미리 훔쳐보지 못하게 하는 장치다.\n- **길이가 다른 문장을 함께 넣기** — 짧은 쪽을 빈칸으로 채운 뒤, 그 빈칸은 보지 말라는 표(어텐션 마스크)를 1과 0으로 함께 보낸다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **어텐션이 볼 낱말 하나를 골라준다** — 고르는 게 아니라 모든 낱말에 비율을 매겨 전부 섞는다. 비율이 0에 가까운 낱말이 많을 뿐이다.\n- **어텐션은 트랜스포머가 만든 장치다** — 그전부터 순환 모델에 붙여 쓰던 장치다. 트랜스포머가 한 일은 순환과 합성곱을 걷어내고 어텐션만 남긴 것이다.\n- **어텐션이 항상 낫다** — 계산이 길이의 제곱으로 는다. 논문도 글 길이가 표현 차원보다 짧을 때 순환보다 빠르다고 적었고, 아주 긴 입력에는 좁은 창만 보는 방식을 따로 쓴다."}],"figure":"```도해\n흐름: 낱말 하나를 정할 때 무엇을 보나\n지금 자리 :: \"무엇을 찾는가\" 를 질문으로 만든다\n다른 낱말 :: 저마다 \"나는 이런 것\" 이라는 표를 낸다\n견주기 :: 질문과 표를 맞춰 낱말마다 점수를 낸다\n비율로 :: 점수를 합이 1이 되는 비율로 바꾼다\n< 지금 자리 :: 그 비율대로 낱말들의 내용을 섞어 받는다\n= 어느 낱말을 얼마나 볼지 매번 새로 정하는 것이 어텐션이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 앞말을 차례로 넘겨받으면 무엇이 어려운가\n차례로 넘기면 || 서로 바로 보면\n낱말 사이 거리 :: 여러 단계 거친다 || 한 단계면 닿는다\n먼 관계 배우기 :: 길이 멀어 어렵다 || 길이 짧아 쉽다\n계산 순서 :: 앞이 끝나야 다음 || 한꺼번에 가능\n= 낱말끼리 직접 보게 만들어 사이의 거리를 없앤 것이다\n```\n\n낱말을 순서대로 한 칸씩 넘겨주는 방식에서는 멀리 떨어진 두 낱말이 서로에게 닿기까지 거친 단계가 길이만큼 늘어난다. 논문은 이 \"경로 길이\" 가 짧을수록 먼 관계를 배우기 쉽다고 적고, 표로 정리한다 — 어텐션은 한 층에서 모든 자리를 잇고 순차 연산이 상수 번인 반면, 순환 방식은 둘 다 길이 `n` 에 비례한다.\n\n값은 공짜가 아니다. 모든 낱말이 모든 낱말과 견주므로 한 층의 계산량이 길이의 제곱(`n²`)으로 는다. 입력을 두 배로 늘리면 이 부분만 네 배가 된다. Hugging Face 문서가 긴 글에서 어텐션 행렬이 계산 병목이 된다고 적는 이유가 이것이다."},"recap":"**\"어느 낱말을 얼마나 볼지 그때그때 정하는 일\"** 이라고 읽으면 된다. 하나를 고르는 게 아니라 모든 낱말에 비율을 매겨 섞는 것이고, 그 비율은 문장이 바뀌면 다시 매겨진다. 대신 낱말끼리 전부 견주므로 글이 두 배 길어지면 이 계산은 네 배가 된다.","kid":"주스를 만들 때 딸기를 많이 넣고 바나나를 조금 넣으면 딸기 맛이 세지? 다음에 올 말을 고를 때도 앞에 나온 말들을 그렇게 섞어. 어떤 말은 많이 어떤 말은 아주 조금 넣는데, 그 넣는 양을 말이 나올 때마다 새로 정해.","check":[{"q":"입력 글을 두 배로 늘리면 이 계산이 왜 네 배가 되나","at":"해결하는 문제"},{"q":"같은 낱말이 문장에 따라 다른 뜻으로 읽히는 일은 어디서 생기나","at":"그림"},{"q":"길이가 다른 두 문장을 한꺼번에 넣을 때 짧은 쪽은 어떻게 하나","at":"실제 사례"}],"myths":[{"wrong":"어텐션이 볼 낱말 하나를 골라준다","right":"고르는 게 아니라 모든 낱말에 비율을 매겨 전부 섞는다. 비율이 0에 가까운 낱말이 많을 뿐이다."},{"wrong":"어텐션은 트랜스포머가 만든 장치다","right":"그전부터 순환 모델에 붙여 쓰던 장치다. 트랜스포머가 한 일은 순환과 합성곱을 걷어내고 어텐션만 남긴 것이다."},{"wrong":"어텐션이 항상 낫다","right":"계산이 길이의 제곱으로 는다. 논문도 글 길이가 표현 차원보다 짧을 때 순환보다 빠르다고 적었고, 아주 긴 입력에는 좁은 창만 보는 방식을 따로 쓴다."}],"cases":[{"label":"긴 입력이 유난히 비싼 이유","note":"어텐션 점수 행렬은 글 길이의 제곱으로 커진다. 모델은 들어가는데 입력이 길어 메모리가 터지는 일이 여기서 난다."},{"label":"뒤를 못 보게 막기","note":"다음 낱말을 맞히는 모델은 아직 안 나온 자리의 점수를 음의 무한대로 만들어 지운다. 정답을 미리 훔쳐보지 못하게 하는 장치다."},{"label":"길이가 다른 문장을 함께 넣기","note":"짧은 쪽을 빈칸으로 채운 뒤, 그 빈칸은 보지 말라는 표(어텐션 마스크)를 1과 0으로 함께 보낸다."}],"dia":{"shape":"흐름","title":"낱말 하나를 정할 때 무엇을 보나","rows":[{"who":"지금 자리","what":"\"무엇을 찾는가\" 를 질문으로 만든다"},{"who":"다른 낱말","what":"저마다 \"나는 이런 것\" 이라는 표를 낸다"},{"who":"견주기","what":"질문과 표를 맞춰 낱말마다 점수를 낸다"},{"who":"비율로","what":"점수를 합이 1이 되는 비율로 바꾼다"},{"who":"지금 자리","what":"그 비율대로 낱말들의 내용을 섞어 받는다","back":true}],"sum":"어느 낱말을 얼마나 볼지 매번 새로 정하는 것이 어텐션이다"}},"ai--cnn":{"definition":"보통의 신경망은 픽셀을 하나씩 따로 받는다. 100×100 이미지면 입력이 1만 개고, 옆 픽셀과 붙어 있다는 사실은 사라진다. CNN은 작은 창을 이미지 위로 옮겨가며 보기 때문에 그 관계가 남는다.","name":"Convolutional :: 겹쳐 훑는\nNeural :: 신경을 본뜬\nNetwork :: 얽힌 그물\n= 붙여 읽으면 \"겹쳐 훑는 신경 그물\". 한 번에 다 보지 않고 작은 창으로 훑는 것이 이름의 앞자리다","analogy":"도장. 같은 무늬가 새겨진 도장을 사진 위 여기저기에 찍어보며 어디에서 잘 맞는지 표시하는 것과 비슷하다.","example":"휴대폰 사진첩이 사람 얼굴별로 앨범을 만들어 두는 것이 이 일을 하고 있는 자리다.","tryit":"사진첩 앱 검색창에 \"고양이\" 나 \"자동차\" 를 쳐 보라. 이름을 붙인 적 없는 사진이 걸려 나온다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"필터는 작은 숫자 격자다. 가운데를 크게 하고 둘레를 음수로 두면 밝기가 갑자기 꺾이는 자리, 곧 모서리에 큰 값이 나온다.\n\n```\n-1 -1 -1\n-1  8 -1\n-1 -1 -1\n```\n\n이 격자를 이미지 위에서 한 칸씩 옮기며 곱하고 더한 결과가 다음 층의 입력이 된다. 어떤 숫자를 넣을지는 사람이 정하지 않고 학습으로 정해진다.\n\n층 사이에는 풀링이 들어간다. 2×2 영역에서 가장 큰 값만 남기는 식으로 크기를 절반으로 줄이는데, 이 덕분에 무늬가 몇 픽셀 밀려 있어도 같은 결과가 나온다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 대표적인 CNN 구조","body":"| 모델 | 연도 | 달라진 점 |\n|---|---|---|\n| LeNet-5 | 1998 | 최초의 CNN. 손글씨 인식 |\n| AlexNet | 2012 | ImageNet 우승. ReLU 사용 |\n| VGGNet | 2014 | 층을 16~19개까지 깊게 |\n| ResNet | 2015 | 층을 건너뛰는 연결로 152층까지 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **얼굴 인식** — 사진에서 얼굴 위치를 찾고 누구인지 고르는 데 쓴다.\n- **물체 감지** — 한 장면에서 자동차 3대와 사람 5명을 각각 상자로 표시한다.\n- **학습된 모델 재사용** — 이미 학습된 모델을 가져와 마지막 층만 바꿔 쓰는 방식이 흔하다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **CNN은 이미지에만 쓴다** — 이웃끼리 뭉쳐 뜻을 이루는 데이터면 쓸 수 있다. 소리 파형이나 문장에도 같은 방식을 적용한다.\n- **필터의 숫자를 사람이 정해준다** — 어떤 무늬를 찾을지까지 학습으로 정해진다. 사람이 정하는 건 필터의 크기와 개수다.\n- **층을 깊게 쌓을수록 좋아진다** — 어느 지점을 넘으면 오히려 학습이 안 된다. 층을 건너뛰는 연결 같은 장치가 나온 이유가 그것이다."}],"figure":"```도해\n흐름: 사진 한 장이 \"고양이\" 라는 답이 되기까지 무엇을 지나나\n입력 :: 픽셀 값이 격자 그대로 들어온다\n합성곱 :: 작은 필터를 옮겨가며 무늬를 찾는다\n풀링 :: 크기를 줄인다. 위치가 조금 달라도 견딘다\n반복 :: 합성곱과 풀링을 다시. 무늬가 커진다\n완전연결 :: 모아둔 특징을 근거로 분류한다\n출력 :: 고양이 90%, 개 10%\n= 앞에서 무늬를 찾고, 뒤에서 그 무늬를 근거로 고른다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 픽셀을 하나씩 따로 보면 무엇이 안 되나\n일반 신경망 || CNN\n이웃 픽셀 :: 관계가 끊김 || 함께 본다\n가중치 :: 픽셀마다 따로 || 필터를 공유\n위치 이동 :: 다른 것으로 봄 || 같은 것으로 봄\n= 이미지는 이웃끼리 뭉쳐 뜻을 이루므로 이웃을 같이 봐야 한다\n```\n\n눈이 사진의 어디에 있든 눈은 눈이다. 픽셀을 하나씩 독립적으로 받는 신경망은 이걸 모른다. 고양이가 왼쪽에 있는 사진과 오른쪽에 있는 사진이 완전히 다른 입력으로 들어온다.\n\nCNN은 같은 필터를 이미지 전체에 옮겨가며 쓴다. 그래서 무늬가 어디에 있든 같은 무늬로 잡히고, 학습해야 할 값의 개수도 크게 줄어든다."},"compose":{"label":"무엇으로 되어 있나","head":"🧱 구성","body":"```도해\n층: 층이 깊어질수록 무엇을 알아보나\n1층 :: 밝기가 꺾이는 자리. 선과 모서리\n2층 :: 선이 모인 모양. 곡선, 꺾임\n3층 :: 눈이나 코 같은 부분\n4층 :: 부분들의 배치. 고양이인지 아닌지\n= 앞층이 찾은 것을 재료로 뒷층이 더 큰 것을 찾는다\n```"},"recap":"**\"작은 도장을 옮겨 찍어 무늬를 찾는 그 그물\"** 이라고 읽으면 된다. 앞층은 선과 모서리를 보고 뒷층은 그것이 모인 부분을 보며, 마지막에 그 특징들로 분류한다.","kid":"눈 모양이 새겨진 도장을 사진 위 여기저기에 찍어 보면 딱 맞는 자리에서만 진하게 찍히지? 그래서 눈이 왼쪽에 있든 오른쪽에 있든 똑같이 찾아내. 그렇게 찾은 눈이랑 코가 어디에 모여 있는지를 보고 고양이인지 아닌지 맞히는 거야.","check":[{"q":"픽셀을 하나씩 따로 받는 신경망이 이미지에서 약한 이유는","at":"해결하는 문제"},{"q":"층이 깊어지면 각 층이 알아보는 것은 어떻게 달라지나","at":"구성"},{"q":"필터에 넣을 숫자는 누가 정하고, 사람이 정하는 것은 무엇인가","at":"흔한 오해"}],"myths":[{"wrong":"CNN은 이미지에만 쓴다","right":"이웃끼리 뭉쳐 뜻을 이루는 데이터면 쓸 수 있다. 소리 파형이나 문장에도 같은 방식을 적용한다."},{"wrong":"필터의 숫자를 사람이 정해준다","right":"어떤 무늬를 찾을지까지 학습으로 정해진다. 사람이 정하는 건 필터의 크기와 개수다."},{"wrong":"층을 깊게 쌓을수록 좋아진다","right":"어느 지점을 넘으면 오히려 학습이 안 된다. 층을 건너뛰는 연결 같은 장치가 나온 이유가 그것이다."}],"cases":[{"label":"얼굴 인식","note":"사진에서 얼굴 위치를 찾고 누구인지 고르는 데 쓴다."},{"label":"물체 감지","note":"한 장면에서 자동차 3대와 사람 5명을 각각 상자로 표시한다."},{"label":"학습된 모델 재사용","note":"이미 학습된 모델을 가져와 마지막 층만 바꿔 쓰는 방식이 흔하다."}],"dia":{"shape":"흐름","title":"사진 한 장이 \"고양이\" 라는 답이 되기까지 무엇을 지나나","rows":[{"who":"입력","what":"픽셀 값이 격자 그대로 들어온다"},{"who":"합성곱","what":"작은 필터를 옮겨가며 무늬를 찾는다"},{"who":"풀링","what":"크기를 줄인다. 위치가 조금 달라도 견딘다"},{"who":"반복","what":"합성곱과 풀링을 다시. 무늬가 커진다"},{"who":"완전연결","what":"모아둔 특징을 근거로 분류한다"},{"who":"출력","what":"고양이 90%, 개 10%"}],"sum":"앞에서 무늬를 찾고, 뒤에서 그 무늬를 근거로 고른다"}},"ai--chunking":{"definition":"RAG에서 문서를 넣기 전에 거치는 단계다. 자르는 기준을 무엇으로 잡느냐에 따라 나중에 검색되는 조각이 달라진다.","analogy":"책. 통째로 들고 다니지 않고 장과 절로 나눠두면 필요한 쪽만 펴서 본다.","example":"긴 PDF 를 올려놓고 물었더니 답 아래 붙은 출처가 문서 전체가 아니라 한 문단을 가리킨다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"자르는 방법은 크게 셋이다. 글자 수로 끊는 고정 크기, 문단이나 문장 경계에서 끊는 의미 단위, 문서에 이미 있는 구조를 쓰는 방식이다. 법령이나 사규처럼 조항 번호가 붙은 문서는 세 번째가 가장 잘 맞는다.\n\n```python\ndef fixed_size(text, size=500, overlap=50):\n    chunks, start = [], 0\n    while start < len(text):\n        chunks.append(text[start:start + size])\n        start += size - overlap\n    return chunks\n```\n\n`overlap` 이 겹치는 구간이다. 겹침 없이 자르면 경계에 걸친 문장이 양쪽 어디에서도 온전하지 않다. 앞 조각의 끝 몇십 자를 다음 조각의 앞에 다시 넣어 그 손실을 줄인다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **사규 검색** — 조항 번호를 기준으로 잘라두고 조각마다 조항 번호를 함께 저장해 답변에 출처를 붙인다.\n- **긴 보고서** — 소제목 단위로 자르면 한 조각 안의 내용이 한 주제로 모여 검색 정확도가 올라간다.\n- **답이 자꾸 어긋날 때** — 모델을 바꾸기 전에 자르는 단위부터 바꿔보고 결과를 견준다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **청크는 작을수록 정확하다** — 너무 작으면 문장 앞뒤가 끊겨 그 조각만 봐서는 무슨 말인지 알 수 없다. 검색에는 걸려도 답이 안 나온다.\n- **겹치기는 저장 공간 낭비다** — 겹침이 없으면 경계에 걸친 문장이 어느 쪽에서도 온전하지 않다. 50자에서 200자 정도의 겹침은 그 손실을 막는 값이다.\n- **한 번 잘라두면 끝난다** — 자르는 기준이 검색 품질을 정한다. 답이 어긋나기 시작하면 자른 단위를 먼저 의심한다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **크기는 500자에서 1500자 사이가 무난하다.** 이보다 작으면 문맥이 끊기고 크면 필요 없는 내용까지 딸려 온다.\n- **한국어는 어절 경계를 조심한다.** 공백만 보고 끊으면 조사가 잘려 나가 검색이 안 걸릴 수 있다."}],"figure":"```도해\n흐름: 100쪽짜리 문서로 질문 하나에 어떻게 답하나\n원본 문서 :: 조항이나 문단 단위로 자른다\n청크 :: 조각마다 벡터(뜻의 좌표)로 바꿔 저장한다\n질문 :: 들어온 질문도 같은 방식으로 바꾼다\n검색 :: 가까운 조각 몇 개만 고른다\nLLM :: 고른 조각만 읽고 답을 만든다\n= 문서 전체가 아니라 필요한 조각만 모델 앞에 놓는다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 문서를 통째로 넣으면 무엇이 걸리나\n통째로 || 잘라서\n입력 길이 :: 한도를 넘는다 || 조각만 넣는다\n비용 :: 매번 전부 낸다 || 필요한 만큼만\n검색 결과 :: 엉뚱한 대목까지 || 해당 조항만\n= 자르는 이유는 넣기 위해서만이 아니라 찾기 위해서이기도 하다\n```\n\n100쪽짜리 취업규칙을 통째로 모델에 넣으면 입력 한도를 넘고, 넘지 않더라도 매 질문마다 100쪽 값을 낸다.\n\n더 걸리는 것은 검색 쪽이다. 문서 하나가 통으로 한 덩어리면 \"육아휴직 기간은?\" 이라고 물었을 때 그 문서 전체가 걸린다. 조항 단위로 잘라두면 해당 조항만 걸려 나온다."},"recap":"**\"찾기 좋게 미리 잘라 두는 그 손질\"** 이라고 읽으면 된다. 모델 입력 한도 때문에 자르기도 하지만, 더 큰 이유는 필요한 대목만 골라내기 위해서다. 자르는 기준과 겹침의 양이 검색 품질을 정한다.","kid":"두꺼운 책을 통째로 들고 다니면 무거운데, 장마다 쪽지를 붙여 두면 필요한 쪽만 펴 보면 되지? 긴 글도 미리 토막을 내서 토막마다 쪽지를 붙여 둬. 그래서 뭘 물으면 책 전부가 아니라 그 토막 하나만 꺼내 와.","check":[{"q":"조각을 100자로 잘게 자르면 검색은 걸리는데 답이 안 나오는 이유는","at":"흔한 오해"},{"q":"겹침을 0으로 두면 어떤 문장이 손해를 보나","at":"작동 원리"},{"q":"조항 번호가 붙은 사규는 무엇을 기준으로 자르고 무엇을 함께 저장하나","at":"실제 사례"}],"myths":[{"wrong":"청크는 작을수록 정확하다","right":"너무 작으면 문장 앞뒤가 끊겨 그 조각만 봐서는 무슨 말인지 알 수 없다. 검색에는 걸려도 답이 안 나온다."},{"wrong":"겹치기는 저장 공간 낭비다","right":"겹침이 없으면 경계에 걸친 문장이 어느 쪽에서도 온전하지 않다. 50자에서 200자 정도의 겹침은 그 손실을 막는 값이다."},{"wrong":"한 번 잘라두면 끝난다","right":"자르는 기준이 검색 품질을 정한다. 답이 어긋나기 시작하면 자른 단위를 먼저 의심한다."}],"cases":[{"label":"사규 검색","note":"조항 번호를 기준으로 잘라두고 조각마다 조항 번호를 함께 저장해 답변에 출처를 붙인다."},{"label":"긴 보고서","note":"소제목 단위로 자르면 한 조각 안의 내용이 한 주제로 모여 검색 정확도가 올라간다."},{"label":"답이 자꾸 어긋날 때","note":"모델을 바꾸기 전에 자르는 단위부터 바꿔보고 결과를 견준다."}],"dia":{"shape":"흐름","title":"100쪽짜리 문서로 질문 하나에 어떻게 답하나","rows":[{"who":"원본 문서","what":"조항이나 문단 단위로 자른다"},{"who":"청크","what":"조각마다 벡터(뜻의 좌표)로 바꿔 저장한다"},{"who":"질문","what":"들어온 질문도 같은 방식으로 바꾼다"},{"who":"검색","what":"가까운 조각 몇 개만 고른다"},{"who":"LLM","what":"고른 조각만 읽고 답을 만든다"}],"sum":"문서 전체가 아니라 필요한 조각만 모델 앞에 놓는다"}},"ai--context-window":{"definition":"길이는 글자가 아니라 토큰으로 센다. 질문과 지난 대화와 붙여 보낸 문서가 전부 이 한도를 나눠 쓰고, 모델이 내놓을 답도 같은 한도 안에 들어가야 한다.","name":"Context :: 앞뒤 사정\nWindow :: 뚫린 만큼만 보는 창\n= 붙여 읽으면 \"앞뒤 사정이 보이는 창\". 창 밖으로 밀려난 것은 없는 것과 같다","analogy":"책상. 아무리 넓어도 올려둔 것만 보면서 일한다. 책장에 꽂힌 책은 올려놓기 전까지 없는 것과 같다.","example":"긴 문서를 통째로 붙여넣었더니 길이가 넘친다며 거절당하는 그 순간이 창의 끝이다.","tryit":"챗봇과 대화를 아주 길게 이어간 뒤, 맨 처음에 알려 준 이름을 다시 물어보라. 모른다고 하면 그 대목이 창 밖으로 밀려난 것이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"토큰은 글을 자른 조각이다. 영어는 단어 하나가 대체로 한두 토큰이고 한국어는 같은 글자 수라도 토큰이 더 많이 나온다. 그래서 창 크기를 글자 수로 환산해 외우면 잘 맞지 않는다.\n\n입력과 출력이 같은 창을 나눠 쓴다는 점도 놓치기 쉽다. 창을 입력으로 거의 채우면 답이 들어설 자리가 남지 않아 중간에서 끊긴다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 창 크기의 규모","body":"| 모델 | 창 크기 | 대략 분량 |\n|---|---|---|\n| GPT-3.5 | 4K 토큰 | 짧은 글 몇 페이지 |\n| GPT-4 Turbo | 128K 토큰 | 책 한 권 |\n| Claude 3.5 Sonnet | 200K 토큰 | 책 한 권 반 |\n| Gemini 1.5 Pro | 1M 토큰 | 책 여러 권 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **긴 보고서 요약** — 창보다 긴 문서는 조각으로 나눠 각각 요약하고 그 요약을 다시 합친다.\n- **오래 이어지는 상담** — 앞부분 대화를 요약본으로 바꿔 넣어 창 안에 남긴다.\n- **문서 검색을 붙이는 이유** — 전체를 넣는 대신 질문과 관련된 조각만 찾아 넣는다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **모델이 앞에서 한 말을 기억하고 있다** — 기억하지 않는다. 프로그램이 매번 지난 대화를 통째로 다시 붙여 보내는 것이고, 그래서 대화가 길수록 같은 질문에도 비용이 오른다.\n- **창이 크면 채울수록 좋다** — 넣은 만큼 돈과 시간이 든다. 관련 없는 글까지 채우면 느려지고 답도 흐려진다.\n- **창은 입력 길이를 뜻한다** — 답변도 같은 창을 나눠 쓴다. 입력으로 창을 거의 채우면 답이 짧아지거나 잘린다."}],"figure":"```도해\n흐름: 대화가 길어지면 앞부분은 어디로 가나\n사용자 :: 새 질문 한 줄을 보낸다\n프로그램 :: 지난 대화 전체를 앞에 붙여 보낸다\n모델 :: 붙어 온 글을 토큰으로 센다\n모델 :: 창을 넘으면 거절하거나 앞부분이 잘린다\n< 사용자 :: 창 안에 남은 것만 보고 만든 답을 받는다\n@ 다음 질문 :: 지난 대화가 또 통째로 붙어 온다\n= 모델이 기억하는 게 아니라 매번 통째로 다시 읽는 것이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 창 크기를 모르고 쓰면 어떤 일이 생기나\n모르고 쓰면 || 알고 쓰면\n긴 문서 :: 통째로 넣는다 || 나눠서 넣는다\n결과 :: 길이 초과로 실패 || 필요한 데만 답\n비용 :: 안 쓸 글까지 낸다 || 넣은 만큼만\n= 창은 늘릴 수 없으니 무엇을 넣을지 고르는 문제가 된다\n```\n\n모델에게 자료를 주는 방법은 창 안에 넣는 것 하나뿐이다. 사내 문서 전체를 읽히고 싶어도 창보다 길면 들어가지 않고, 대화를 길게 이어가면 앞부분부터 밀려 나간다.\n\n그래서 창 크기를 아는 일은 곧 무엇을 넣고 무엇을 뺄지 정하는 일이 된다. 질문과 관련된 조각만 찾아 넣거나, 지난 대화를 요약해 압축하거나, 문서를 나눠 여러 번 묻는 방식이 여기서 나온다."},"recap":"**\"책상에 올려둔 만큼만 보는 그 한 뼘\"** 이라고 읽으면 된다. 붙여 보낸 지난 대화와 문서, 그리고 모델이 내놓을 답까지 그 한 뼘을 나눠 쓴다. 늘릴 수 없는 값이라 무엇을 올려둘지 고르는 일이 실제 작업이 된다.","kid":"책상 위에 올려놓은 종이만 보면서 숙제한다고 해 봐. 책장에 아무리 책이 많아도 꺼내서 올려놓기 전에는 없는 거나 마찬가지지? 새 종이를 자꾸 올리면 먼저 놓았던 게 책상 밖으로 밀려 떨어지고, 떨어진 건 못 봐.","check":[{"q":"대화가 길어질수록 같은 질문에 비용이 더 드는 이유는","at":"흔한 오해"},{"q":"창보다 긴 문서를 요약해야 할 때 무엇을 하나","at":"실제 사례"},{"q":"입력을 창 끝까지 채웠더니 답이 중간에 끊긴다면 왜인가","at":"작동 원리"}],"myths":[{"wrong":"모델이 앞에서 한 말을 기억하고 있다","right":"기억하지 않는다. 프로그램이 매번 지난 대화를 통째로 다시 붙여 보내는 것이고, 그래서 대화가 길수록 같은 질문에도 비용이 오른다."},{"wrong":"창이 크면 채울수록 좋다","right":"넣은 만큼 돈과 시간이 든다. 관련 없는 글까지 채우면 느려지고 답도 흐려진다."},{"wrong":"창은 입력 길이를 뜻한다","right":"답변도 같은 창을 나눠 쓴다. 입력으로 창을 거의 채우면 답이 짧아지거나 잘린다."}],"cases":[{"label":"긴 보고서 요약","note":"창보다 긴 문서는 조각으로 나눠 각각 요약하고 그 요약을 다시 합친다."},{"label":"오래 이어지는 상담","note":"앞부분 대화를 요약본으로 바꿔 넣어 창 안에 남긴다."},{"label":"문서 검색을 붙이는 이유","note":"전체를 넣는 대신 질문과 관련된 조각만 찾아 넣는다."}],"dia":{"shape":"흐름","title":"대화가 길어지면 앞부분은 어디로 가나","rows":[{"who":"사용자","what":"새 질문 한 줄을 보낸다"},{"who":"프로그램","what":"지난 대화 전체를 앞에 붙여 보낸다"},{"who":"모델","what":"붙어 온 글을 토큰으로 센다"},{"who":"모델","what":"창을 넘으면 거절하거나 앞부분이 잘린다"},{"who":"사용자","what":"창 안에 남은 것만 보고 만든 답을 받는다","back":true}],"sum":"모델이 기억하는 게 아니라 매번 통째로 다시 읽는 것이다","loop":{"who":"다음 질문","what":"지난 대화가 또 통째로 붙어 온다"}}},"ai--cosine-similarity":{"definition":"벡터(뜻을 담은 숫자 목록)의 크기는 버리고 방향만 견준다. 값은 -1에서 1 사이에 놓이고, 방향이 같을수록 1에 가까워진다.","name":"Cosine :: 각도에서 나온 값\nSimilarity :: 닮은 정도\n= 붙여 읽으면 \"각도로 잰 닮은 정도\". 거리가 아니라 각도라는 말이 이름에 이미 있다","analogy":"나침반. 한 사람은 1킬로미터를 갔고 다른 사람은 10킬로미터를 갔어도 둘 다 북동쪽이면 같은 방향이다.","example":"한 줄짜리 메모와 긴 보고서가 같은 주제라는 이유만으로 나란히 묶여 나오는 자리다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"값 1은 완전히 같은 방향, 0은 직각이라 무관, -1은 정반대다. 검색에서는 이 값을 그대로 쓰지 않고 어디서 자를지를 정해둔다.\n\n```도해\n층: 나온 점수를 어떻게 읽나\n0.9 이상 :: 거의 같은 내용. 근거로 그대로 쓴다\n0.7 에서 0.9 :: 비슷한 내용. 참고로 붙인다\n0.3 에서 0.7 :: 조금 걸친다. 표시를 달아 보여준다\n0.3 미만 :: 무관하다고 보고 버린다\n= 점수를 그냥 쓰지 않고 어디서 자를지 정하는 것이 검색 품질을 정한다\n```\n\n기준을 높게 잡으면 찾는 문서가 너무 적어 \"관련 정보가 없다\" 는 답이 자주 나오고, 낮게 잡으면 무관한 문서가 섞여 들어가 엉뚱한 답이 나온다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **문서 검색** — 질문 벡터와 저장된 조각들의 각도를 재서 가까운 순으로 몇 개만 모델에 넘긴다.\n- **답변 근거 제한** — 기준값 아래로 떨어진 조각은 아예 빼서 지어낸 답이 나올 여지를 줄인다.\n- **비슷한 문서 묶기** — 이미 있는 문서끼리 각도를 재면 주제가 같은 것들이 한데 모인다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **0.5면 절반쯤 맞다는 뜻이다** — 비율이 아니라 각도의 코사인 값이다. 차원이 높으면 무관한 문장들도 0.1에서 0.3 사이에 몰리기 때문에 0.5는 생각보다 가까운 축이다.\n- **점수가 높으면 답이 그 안에 있다** — 방향이 비슷하다는 뜻이지 질문에 답한다는 뜻이 아니다. 주제만 같고 답은 없는 조각도 높게 나온다.\n- **긴 문서가 짧은 문서보다 유리하다** — 크기를 지우고 방향만 보기 때문에 길이는 점수에 들어가지 않는다. 그러려고 각도를 쓰는 것이다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **음수는 반대 의미라기보다 대개 무관이다.** 검색에서는 둘 다 버리는 쪽으로 다룬다.\n- **차원이 높으면 점수가 좁은 구간에 몰린다.** 768차원쯤 되면 대부분의 벡터가 직각에 가까워서 기준값을 그대로 옮겨 쓰면 아무것도 안 걸린다."}],"figure":"```도해\n흐름: 짧은 질문으로 긴 문서를 어떻게 찾아내나\n질문 :: 문장을 벡터로 바꾼다\n문서 벡터 :: 미리 바꿔둔 조각들이 늘어서 있다\n각도 :: 질문과 각 조각 사이의 각도를 잰다\n점수 :: 각도가 좁을수록 1 에 가까워진다\n상위 몇 개 :: 점수 높은 순으로 골라 넘긴다\n= 길이가 아니라 방향을 보기 때문에 짧은 질문이 긴 문서를 찾아낸다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 같은 뜻인데 길이가 다른 두 글을 어떻게 견주나\n직선 거리로 || 각도로\n긴 문서 :: 멀다고 나온다 || 방향이 같다\n짧은 질문 :: 매칭이 안 된다 || 그대로 걸린다\n판정 기준 :: 크기에 흔들림 || 크기와 무관\n= 재는 것을 거리에서 방향으로 바꾸면 길이 차이가 사라진다\n```\n\n\"육아휴직\" 이라는 짧은 질문과 \"육아휴직 신청 방법 절차 안내\" 라는 긴 문서를 벡터로 바꾸면 방향은 비슷한데 크기가 크게 다르다. 두 점 사이의 직선 거리를 재면 멀다는 답이 나온다.\n\n각도는 크기에 흔들리지 않는다. 두 벡터를 같은 길이로 놓고 보면 남는 것은 어느 쪽을 향하느냐뿐이라, 문서가 길든 짧든 뜻만 비슷하면 걸린다."},"recap":"**\"길이는 버리고 방향만 보는 그 점수\"** 라고 읽으면 된다. 문서 길이가 점수에 들어가지 않아서 짧은 질문으로 긴 문서를 찾는 데 쓰인다. 점수 자체보다 어디서 자를지를 정하는 일이 검색 결과를 좌우한다.","kid":"둘이 같은 쪽으로 걸었으면 한 명은 열 걸음, 한 명은 백 걸음 갔어도 보고 있는 쪽은 똑같지? 여기서도 얼마나 많이 썼는지는 안 보고 어느 쪽을 보는지만 봐. 그래서 한 줄짜리 쪽지랑 두꺼운 책이 같은 얘기면 나란히 짝지어져.","check":[{"q":"한 줄짜리 질문이 열 쪽짜리 문서를 찾아낼 수 있는 이유는","at":"해결하는 문제"},{"q":"기준값을 0.9로 올려 잡으면 어떤 답이 자주 나오게 되나","at":"작동 원리"},{"q":"유사도가 0.9인데도 질문에 대한 답이 그 조각에 없을 수 있는 이유는","at":"흔한 오해"}],"myths":[{"wrong":"0.5면 절반쯤 맞다는 뜻이다","right":"비율이 아니라 각도의 코사인 값이다. 차원이 높으면 무관한 문장들도 0.1에서 0.3 사이에 몰리기 때문에 0.5는 생각보다 가까운 축이다."},{"wrong":"점수가 높으면 답이 그 안에 있다","right":"방향이 비슷하다는 뜻이지 질문에 답한다는 뜻이 아니다. 주제만 같고 답은 없는 조각도 높게 나온다."},{"wrong":"긴 문서가 짧은 문서보다 유리하다","right":"크기를 지우고 방향만 보기 때문에 길이는 점수에 들어가지 않는다. 그러려고 각도를 쓰는 것이다."}],"cases":[{"label":"문서 검색","note":"질문 벡터와 저장된 조각들의 각도를 재서 가까운 순으로 몇 개만 모델에 넘긴다."},{"label":"답변 근거 제한","note":"기준값 아래로 떨어진 조각은 아예 빼서 지어낸 답이 나올 여지를 줄인다."},{"label":"비슷한 문서 묶기","note":"이미 있는 문서끼리 각도를 재면 주제가 같은 것들이 한데 모인다."}],"dia":{"shape":"흐름","title":"짧은 질문으로 긴 문서를 어떻게 찾아내나","rows":[{"who":"질문","what":"문장을 벡터로 바꾼다"},{"who":"문서 벡터","what":"미리 바꿔둔 조각들이 늘어서 있다"},{"who":"각도","what":"질문과 각 조각 사이의 각도를 잰다"},{"who":"점수","what":"각도가 좁을수록 1 에 가까워진다"},{"who":"상위 몇 개","what":"점수 높은 순으로 골라 넘긴다"}],"sum":"길이가 아니라 방향을 보기 때문에 짧은 질문이 긴 문서를 찾아낸다"}},"ai--distillation":{"definition":"2015년 논문이 이 이름을 붙였다. 원문은 큰 쪽을 \"거추장스러운 모델\", 작은 쪽을 \"작은 모델\" 이라 부르고, 지금은 대개 선생과 학생이라고 한다. 옮기는 것은 정답이 아니라 선생이 보기마다 매긴 확률이다.","name":"De :: 아래로\nStilla :: 물방울\n= 라틴어로 \"방울져 내리다\". 김을 올려 진한 것만 방울로 받아 내는 일이 증류다","analogy":"정답에만 동그라미가 쳐진 답안지 대신, 어떤 오답이 얼마나 그럴듯했는지까지 적힌 답안지를 통째로 베끼는 일이다.","example":"답이 한참 걸려서 작은 모델로 바꿨더니 정확도가 뚝 떨어지던 그 자리에 쓰는 방법이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"선생의 확률을 그대로 가져오면 쓸 것이 적다. 잘 배운 모델일수록 정답 하나에 확률이 몰려서 나머지가 거의 0이 되고, 그러면 \"무엇을 헷갈렸나\" 가 안 보인다. 그래서 마지막 계산에 온도 T 를 끼운다. 보기마다의 점수를 T 로 나눈 다음 확률로 바꾸는 것이다. T 가 1이면 평소 그대로이고, **T 를 올릴수록 분포가 부드러워져 2등·3등 보기의 크기가 드러난다.**\n\nT 는 선생과 학생이 같은 값을 쓴다. 배우는 동안 둘 다 높은 T 로 확률을 내고, 다 배운 학생은 답할 때 T 를 1로 되돌린다. 선생을 따라가는 신호는 T 가 커질수록 T 제곱에 반비례해 작아지므로, 정답까지 함께 배우게 할 때는 그쪽에 T 제곱을 곱해 두 신호의 크기를 맞춘다.\n\n올린다고 계속 좋아지지는 않는다. 원 논문은 학생의 한 층에 계산 칸이 300개 이상일 때는 T 가 8을 넘으면 결과가 다 비슷했지만, 학생을 층당 30칸으로 줄이자 2.5에서 4 사이가 훨씬 나았다고 적는다. 학생이 작을수록 선생의 미세한 순위까지 담을 그릇이 없다는 뜻이다. 문서의 예제는 T 를 5로 두고, 선생을 따라가는 목표와 정답을 맞히는 목표를 반씩 섞는다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **작게 만들어 올리기** — 큰 모델을 그대로 못 올리는 자리에, 그 확률을 베낀 작은 모델을 대신 올린다.\n- **여러 모델을 한 벌로 접기** — 여러 모델의 평균 예측을 목표로 두면 그 이득의 상당 부분이 한 모델 안으로 들어온다.\n- **안 본 것까지 옮겨 가기** — 원 논문에서는 숫자 3을 한 번도 못 본 학생이, 치우침만 바로잡자 시험지의 3을 98.6퍼센트 맞혔다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **큰 모델을 잘라서 작게 만드는 것이다** — 자르는 게 아니다. 학생을 새로 학습시키되 목표를 정답 대신 선생의 확률로 바꾸는 것이다.\n- **증류하면 선생만큼 한다** — 선생이 낸 이득의 일부만 옮겨 간다. 원 논문의 음성 실험에서는 모델 열 개를 묶어 올린 정확도 가운데 80퍼센트 남짓이 학생에게 갔다.\n- **작게 만들 일이면 증류가 먼저다** — 자릿수를 줄이는 쪽은 학습 없이 파일만 줄인다. 증류는 학생을 처음부터 학습시켜야 하고 그동안 선생을 계속 불러야 한다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **선생이 치우쳐 있으면 그것까지 배운다.** 학생의 목표는 정답이 아니라 선생의 확률이다.\n- **작은 학생에게는 높은 온도가 독이다.** 위 실험에서 층당 30칸짜리 학생은 낮은 온도 쪽이 확실히 나았다.\n- **정답 쪽 목표를 아주 빼지는 않는다.** 원 논문은 정답을 맞히는 목표를 함께 두되 비중을 꽤 낮게 잡을 때 가장 좋았다고 적는다."}],"figure":"```도해\n흐름: 작은 모델은 큰 모델에게서 무엇을 받아 배우나\n큰 모델 :: 학습을 이미 마친 쪽. 선생이 된다\n같은 문제 :: 두 모델에게 똑같은 것을 던진다\n답 분포 :: 큰 모델이 보기마다 매긴 확률을 꺼낸다\n작은 모델 :: 자기 확률을 그 확률에 맞춰 간다\n배포 :: 다 배우면 큰 모델 없이 혼자 답한다\n= 정답 한 글자가 아니라 \"무엇을 얼마나 헷갈렸나\" 를 통째로 베끼는 학습이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 큰 모델을 그대로 못 쓸 때 어떻게 하나\n작은 모델 혼자 || 큰 모델을 보고\n배우는 신호 :: 맞다·틀리다뿐 || 헷갈린 정도까지\n오답 순위 :: 안 알려준다 || 통째로 알려준다\n같은 실험 정답률 :: 63퍼센트 || 72퍼센트\n= 모델 크기는 그대로 둔 채, 큰 모델이 매긴 확률만 옮겨 담는다\n```\n\n큰 모델은 답이 좋지만 부를 때마다 계산이 든다. 그래서 작은 모델로 갈아타면 그 작은 모델을 정답만으로 새로 학습시키게 되는데, 정답 하나는 \"이게 맞다\" 만 말해 줄 뿐 \"어느 오답이 아까웠나\" 는 말해 주지 않는다.\n\n증류는 말해 주지 않던 그 부분을 신호로 쓴다. 선생이 매긴 확률을 통째로 목표로 삼는 것이다. 문서에 실린 이미지 분류 실험에서는 같은 학생 모델을 혼자 학습시켰을 때 정답률이 63퍼센트, 선생을 보고 배우게 했을 때 72퍼센트가 나왔다. 학생의 크기는 한 글자도 바뀌지 않았다."},"recap":"**\"큰 모델이 매긴 확률을 작은 모델에 베끼는 그 학습\"** 이라고 읽으면 된다. 손으로 잡는 값은 온도 T 하나이고, 올리면 선생이 무엇을 헷갈렸는지가 드러나지만 학생이 작으면 오히려 낮은 쪽이 낫다. 크기를 줄이는 값이 아니라, 같은 크기에서 점수를 올리는 값이다.","kid":"형이 시험을 잘 보지? 형한테 정답만 물어보면 그냥 외우고 끝인데, \"이건 헷갈리는 게 둘 있고 그중에 이게 더 그럴듯해\" 까지 들으면 훨씬 빨리 늘어. 그래서 작은 네가 혼자 시험을 봐도 형이랑 비슷한 점수가 나와.","check":[{"q":"온도를 올리면 선생의 확률에서 무엇이 드러나나","at":"작동 원리"},{"q":"같은 크기의 학생인데 정답률이 63퍼센트와 72퍼센트로 갈리는 이유는 무엇인가","at":"해결하는 문제"},{"q":"숫자 3을 한 번도 못 본 학생이 3을 맞히는 일은 어떻게 가능한가","at":"실제 사례"}],"myths":[{"wrong":"큰 모델을 잘라서 작게 만드는 것이다","right":"자르는 게 아니다. 학생을 새로 학습시키되 목표를 정답 대신 선생의 확률로 바꾸는 것이다."},{"wrong":"증류하면 선생만큼 한다","right":"선생이 낸 이득의 일부만 옮겨 간다. 원 논문의 음성 실험에서는 모델 열 개를 묶어 올린 정확도 가운데 80퍼센트 남짓이 학생에게 갔다."},{"wrong":"작게 만들 일이면 증류가 먼저다","right":"자릿수를 줄이는 쪽은 학습 없이 파일만 줄인다. 증류는 학생을 처음부터 학습시켜야 하고 그동안 선생을 계속 불러야 한다."}],"cases":[{"label":"작게 만들어 올리기","note":"큰 모델을 그대로 못 올리는 자리에, 그 확률을 베낀 작은 모델을 대신 올린다."},{"label":"여러 모델을 한 벌로 접기","note":"여러 모델의 평균 예측을 목표로 두면 그 이득의 상당 부분이 한 모델 안으로 들어온다."},{"label":"안 본 것까지 옮겨 가기","note":"원 논문에서는 숫자 3을 한 번도 못 본 학생이, 치우침만 바로잡자 시험지의 3을 98.6퍼센트 맞혔다."}],"dia":{"shape":"흐름","title":"작은 모델은 큰 모델에게서 무엇을 받아 배우나","rows":[{"who":"큰 모델","what":"학습을 이미 마친 쪽. 선생이 된다"},{"who":"같은 문제","what":"두 모델에게 똑같은 것을 던진다"},{"who":"답 분포","what":"큰 모델이 보기마다 매긴 확률을 꺼낸다"},{"who":"작은 모델","what":"자기 확률을 그 확률에 맞춰 간다"},{"who":"배포","what":"다 배우면 큰 모델 없이 혼자 답한다"}],"sum":"정답 한 글자가 아니라 \"무엇을 얼마나 헷갈렸나\" 를 통째로 베끼는 학습이다"}},"ai--embedding":{"definition":"컴퓨터는 \"강아지\"와 \"개\"가 비슷한 말인지 모른다. 두 단어를 각각 수백 개의 숫자로 바꾸되, 뜻이 가까우면 숫자도 가깝게 만든다. 그러면 뜻을 계산으로 비교할 수 있다.","name":"Embed :: 속에 박아 넣다\n= 뜻을 숫자 공간 속에 박아 넣는다는 말이다. 박아 넣고 나면 뜻 사이의 거리가 계산이 된다","analogy":"지도 위의 좌표. 도시 이름만으로는 어디가 가까운지 모르지만 위도와 경도로 바꾸면 거리를 뺄셈으로 구할 수 있다. 임베딩은 뜻에 좌표를 붙이는 일이다.","example":"사진첩 검색창에 바다라고 치면 이름에 바다가 없는 사진들이 올라오는 그 일이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"임베딩이 만들어낸 숫자 목록을 벡터라고 부른다. 벡터 사이의 거리는 보통 각도로 잰다. 이걸 코사인 유사도라고 하고, 1에 가까울수록 뜻이 가깝다.\n\n넣을 수 있는 것은 글만이 아니다.\n\n- **단어** — \"강아지\" 하나\n- **문장** — \"강아지가 공을 물었다\"\n- **문단** — 문서 조각 하나\n- **이미지** — 사진도 같은 공간에 넣을 수 있다\n\n같은 공간에 넣으면 글로 이미지를 검색하는 일도 가능해진다.\n\n중요한 제약이 있다. **같은 모델로 만든 벡터끼리만 비교할 수 있다.** 문서를 A 모델로 임베딩했다면 질문도 A 모델로 해야 한다. 모델을 바꾸면 저장된 벡터를 전부 다시 만들어야 한다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **의미 검색** — 사용자가 쓴 표현과 문서의 표현이 달라도 찾아준다.\n- **추천** — 사용자가 좋아한 항목의 벡터와 가까운 것을 고른다.\n- **중복 탐지** — 표현만 바꾼 문서나 문의를 찾아낸다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **임베딩이 문장의 뜻을 이해한다** — 이해하지 않는다. 같이 등장하는 패턴에서 뽑은 통계라 반대말이 서로 가깝게 나오는 일도 흔하다.\n- **숫자가 많을수록 좋다** — 차원이 크면 정확도가 조금 오르지만 저장 공간과 검색 비용이 같이 오른다.\n- **모델을 바꿔도 기존 벡터를 쓸 수 있다** — 좌표계 자체가 달라진다. 전부 다시 만들어야 한다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **반대말이 가깝게 나온다.** \"좋다\"와 \"나쁘다\"는 같은 문맥에 등장해서 벡터가 가깝다. 감정 판단에 임베딩 거리만 쓰면 틀린다.\n- **모델 교체 비용을 미리 계산한다.** 문서 백만 건이면 백만 번 다시 임베딩해야 한다."}],"figure":"```도해\n흐름: 비슷한 문서를 찾을 때 무슨 계산을 하나\n문장 :: \"환불하고 싶어요\" 가 들어온다\n임베딩 모델 :: 숫자 1536개짜리 목록으로 바꾼다\n저장된 문서 :: 이미 같은 방식으로 바뀌어 있다\n거리 계산 :: 두 목록이 이루는 각도를 잰다\n결과 :: 각도가 가장 작은 문서가 뜻이 가장 가깝다\n= 단어가 하나도 안 겹쳐도 뜻이 가까우면 찾아낸다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: \"환불\" 로 검색하면 무엇이 나오나\n키워드 검색 || 임베딩 검색\n\"반품 절차\" 문서 :: 못 찾는다 || 찾는다\n\"환불 불가\" 문서 :: 찾는다 || 찾는다\n오타 \"환뷸\" :: 못 찾는다 || 대체로 찾는다\n= 글자가 겹치는지가 아니라 뜻이 가까운지로 찾게 만든다\n```\n\n키워드 검색은 글자가 겹쳐야 찾는다. \"환불\"로 검색하면 \"반품 절차\"라는 제목의 문서는 나오지 않는다. 같은 말을 다르게 쓰는 경우가 워낙 많아서 사용자는 원하는 문서를 찾지 못한다.\n\n임베딩은 뜻을 좌표로 만들어 이 문제를 우회한다. 글자가 하나도 겹치지 않아도 뜻이 가까우면 좌표가 가깝다."},"recap":"**\"뜻에 좌표를 붙이는 그 변환\"** 이라고 읽으면 된다. 글자가 안 겹쳐도 찾아주지만, 같은 모델로 만든 벡터끼리만 비교할 수 있다.","kid":"도시 이름만 들으면 어디가 가까운지 모르지만, 지도에 점을 콕 찍어 두면 자로 재서 알 수 있지? 말에도 그렇게 점을 하나씩 찍어 둬. 그래서 \"강아지\" 라고 쓴 글하고 \"개\" 라고 쓴 글이 글자가 하나도 안 겹쳐도 바로 옆자리에 놓여.","check":[{"q":"\"환불\"로 검색했는데 \"반품 절차\" 문서가 나오는 것이 어떻게 가능한가","at":"해결하는 문제"},{"q":"임베딩 모델을 바꾸면 무슨 작업이 따라오나","at":"작동 원리"},{"q":"리뷰의 좋고 나쁨을 임베딩 거리로만 판단하면 왜 위험한가","at":"주의사항"}],"myths":[{"wrong":"임베딩이 문장의 뜻을 이해한다","right":"이해하지 않는다. 같이 등장하는 패턴에서 뽑은 통계라 반대말이 서로 가깝게 나오는 일도 흔하다."},{"wrong":"숫자가 많을수록 좋다","right":"차원이 크면 정확도가 조금 오르지만 저장 공간과 검색 비용이 같이 오른다."},{"wrong":"모델을 바꿔도 기존 벡터를 쓸 수 있다","right":"좌표계 자체가 달라진다. 전부 다시 만들어야 한다."}],"cases":[{"label":"의미 검색","note":"사용자가 쓴 표현과 문서의 표현이 달라도 찾아준다."},{"label":"추천","note":"사용자가 좋아한 항목의 벡터와 가까운 것을 고른다."},{"label":"중복 탐지","note":"표현만 바꾼 문서나 문의를 찾아낸다."}],"dia":{"shape":"흐름","title":"비슷한 문서를 찾을 때 무슨 계산을 하나","rows":[{"who":"문장","what":"\"환불하고 싶어요\" 가 들어온다"},{"who":"임베딩 모델","what":"숫자 1536개짜리 목록으로 바꾼다"},{"who":"저장된 문서","what":"이미 같은 방식으로 바뀌어 있다"},{"who":"거리 계산","what":"두 목록이 이루는 각도를 잰다"},{"who":"결과","what":"각도가 가장 작은 문서가 뜻이 가장 가깝다"}],"sum":"단어가 하나도 안 겹쳐도 뜻이 가까우면 찾아낸다"}},"ai--escalation":{"definition":"넘길 길이 없으면 AI는 모르는 것도 답하려 든다. 확신이 낮거나 권한이 필요하거나 사용자가 이미 화가 나 있으면, 계속 붙잡고 있는 것보다 담당자에게 넘기는 편이 낫다.","name":"Escalate :: 위 단계로 올리다\n= 에스컬레이터와 뿌리가 같은 말이다. 제자리에서 더 애쓰는 게 아니라 한 층 위로 올려 보낸다","analogy":"신입 상담원이 모르는 질문을 받으면 선배를 부르는 것. 억지로 답하는 쪽이 더 큰일을 만든다.","example":"상담 챗봇 창에서 상담원 연결을 누르면 사람이 이어받는데, 그 넘어가는 자리가 여기다.","tryit":"상담 챗봇에 \"상담원 연결\" 이라고 쳐 보라. 자료를 더 뒤지지 않고 곧장 사람 쪽으로 넘어간다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"넘길지 말지는 대개 네 가지를 본다.\n\n- **확신도** 답의 확신도가 정해둔 값 아래로 떨어지면 넘긴다.\n- **반복 실패** 같은 요청을 정해둔 횟수만큼 못 풀면 넘긴다.\n- **명시적 요청** 담당자나 상담원을 찾는 말이 나오면 바로 넘긴다.\n- **부정적 감정** 화가 드러난 표현이 보이면 우선순위를 올려 넘긴다.\n\n넘길 때는 대화 내용을 담은 티켓을 만들고 담당자에게 알린다. 티켓에는 왜 넘겨졌는지를 함께 적어야 받는 사람이 처음부터 다시 묻지 않는다. 넘긴 사유에 따라 응답 목표 시간을 다르게 잡는데, 감정이 드러난 건은 시스템 장애 다음으로 급하게 다룬다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **권한이 필요한 요청** — 승인 권한이 없는 일은 티켓을 만들고 담당자가 이어받는다.\n- **자료에 없는 질문** — 근거 문서를 못 찾으면 지어내지 않고 넘긴다.\n- **불만이 드러난 대화** — 화가 난 표현이 보이면 안내를 더 하지 않고 바로 연결한다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **에스컬레이션은 AI 가 실패했다는 표시다** — 설계에 들어 있는 정상 경로다. 넘길 줄 모르고 계속 답을 지어내는 쪽이 실패한 것이다.\n- **정확도를 올리면 필요 없어진다** — 승인이나 예외 처리처럼 권한이 걸린 일은 정확도와 상관없이 사람이 정해야 한다.\n- **답을 못 찾을 때만 넘기면 된다** — 사용자가 담당자를 찾거나 화가 나 있을 때도 넘긴다. 답을 아는지와 지금 넘겨야 하는지는 다른 문제다."}],"figure":"```도해\n흐름: 답을 못 찾은 대화는 어디로 가나\n사용자 :: 규정에 관해 묻는다\nAI :: 근거를 못 찾고 확신도 낮다\n판정 :: 넘길 조건에 걸리는지 본다\n티켓 :: 대화 내용을 담아 티켓을 만든다\n< 담당자 :: 사람이 이어받아 답한다\n= 못 하는 것을 빨리 인정하는 쪽이 사용자를 덜 지치게 한다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 넘기는 길이 없으면 대화가 어떻게 되나\n넘기지 않으면 || 넘기면\n같은 질문 :: 계속 못 찾는다 || 사람이 받는다\n답의 정확도 :: 억지로 지어냄 || 모른다고 말함\n화난 사용자 :: 안내만 반복 || 바로 연결\n= 한계를 인정하는 통로가 있어야 대화가 끝날 수 있다\n```\n\nAI가 답을 못 찾았을 때 가장 나쁜 결과는 대화가 안 끝나는 것이다. 사용자는 같은 질문을 표현만 바꿔 다시 묻고, AI는 같은 자료를 다시 뒤진다. 이 반복이 길어질수록 사용자는 그 창구 자체를 안 쓰게 된다.\n\n에스컬레이션은 그 반복에 끝을 만든다. 몇 번 실패하면 사람에게 넘긴다는 규칙이 있으면, 사용자는 적어도 다음에 무슨 일이 일어날지 알게 된다."},"recap":"**\"못 하겠다 싶으면 사람에게 올려 보내는 그 통로\"** 라고 읽으면 된다. 확신도와 반복 실패와 사용자의 요청과 감정을 보고 판단하며, 넘긴 사유를 함께 전달해야 받는 쪽이 이어서 처리할 수 있다.","kid":"가게에서 아르바이트 형한테 어려운 걸 물으면 \"잠시만요\" 하고 사장님을 부르지? 아는 척 대충 대답했다간 더 큰일이 나니까 그래. 여기서도 답이 자신 없거나 네가 화가 나 있으면, 계속 붙잡고 있지 않고 바로 사람한테 넘겨.","check":[{"q":"사용자가 같은 질문을 표현만 바꿔 계속 묻는 상황에서 무엇이 빠져 있나","at":"해결하는 문제"},{"q":"답을 정확히 알고 있는데도 넘겨야 하는 경우는 어떤 때인가","at":"흔한 오해"},{"q":"티켓에 넘긴 사유를 적어야 하는 이유가 무엇인가","at":"작동 원리"}],"myths":[{"wrong":"에스컬레이션은 AI 가 실패했다는 표시다","right":"설계에 들어 있는 정상 경로다. 넘길 줄 모르고 계속 답을 지어내는 쪽이 실패한 것이다."},{"wrong":"정확도를 올리면 필요 없어진다","right":"승인이나 예외 처리처럼 권한이 걸린 일은 정확도와 상관없이 사람이 정해야 한다."},{"wrong":"답을 못 찾을 때만 넘기면 된다","right":"사용자가 담당자를 찾거나 화가 나 있을 때도 넘긴다. 답을 아는지와 지금 넘겨야 하는지는 다른 문제다."}],"cases":[{"label":"권한이 필요한 요청","note":"승인 권한이 없는 일은 티켓을 만들고 담당자가 이어받는다."},{"label":"자료에 없는 질문","note":"근거 문서를 못 찾으면 지어내지 않고 넘긴다."},{"label":"불만이 드러난 대화","note":"화가 난 표현이 보이면 안내를 더 하지 않고 바로 연결한다."}],"dia":{"shape":"흐름","title":"답을 못 찾은 대화는 어디로 가나","rows":[{"who":"사용자","what":"규정에 관해 묻는다"},{"who":"AI","what":"근거를 못 찾고 확신도 낮다"},{"who":"판정","what":"넘길 조건에 걸리는지 본다"},{"who":"티켓","what":"대화 내용을 담아 티켓을 만든다"},{"who":"담당자","what":"사람이 이어받아 답한다","back":true}],"sum":"못 하는 것을 빨리 인정하는 쪽이 사용자를 덜 지치게 한다"}},"ai--eval":{"definition":"프롬프트를 고치고 \"좋아진 것 같다\" 로 넘어가면, 무엇이 대신 나빠졌는지는 아무도 모른다. 성공 기준을 숫자로 먼저 적고 그 숫자를 재는 시험지를 만들어 두는 것이 이 자리다. OpenAI 문서가 특히 꼽는 때가 모델을 바꾸거나 새로 써 볼 때다.","name":"Evaluation :: 값을 매겨 재기\n= Eval 은 Evaluation 을 줄인 말이다. \"잘하나\" 를 느낌이 아니라 매번 같은 방식으로 잰 값으로 바꾼다","analogy":"정답지를 붙여 둔 받아쓰기 시험지. 고칠 때마다 같은 것을 다시 풀려 몇 개 맞았는지를 센다.","example":"프롬프트를 한 줄 고치고 예시 서너 개만 눈으로 확인한 뒤 넘어간 적이 있다면, 그 서너 개가 이미 아주 작은 시험지다.","tryit":"쓰는 챗봇에 같은 질문을 다섯 번 넣어 보라. 답이 얼마나 갈리는지가 그 작업의 일관성 점수다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"```도해\n층: 채점을 누구에게 맡길수록 무엇이 달라지나\n글자 맞추기 :: 정답이 하나면 여기서 끝난다. 가장 싸고 안 흔들린다\n코드 채점 :: 형식·범위·금지어처럼 규칙으로 적히는 것\n다른 모델 :: 말투나 공감처럼 규칙으로 못 적는 것을 1에서 5로 매긴다\n사람 채점 :: 가장 정확하지만 문항 수가 곧 사람 시간이다\n= 아래로 갈수록 잴 수 있는 것이 넓어지고, 값과 흔들림이 같이 커진다\n```\n\n손잡이가 셋이다. 첫째는 문항 수다. 문항을 늘리면 한 문항이 우연히 맞고 틀리는 흔들림이 묻히고, 어제 점수와 오늘 점수의 차이를 믿을 수 있게 된다. Anthropic 문서는 손으로 정성껏 채점한 적은 문항보다 신호가 조금 흐려도 자동 채점한 많은 문항이 낫다고 적는다.\n\n둘째는 채점기 종류다. 분류처럼 정답이 딱 떨어지면 글자 맞추기로 충분하고, 같은 질문을 다르게 물었을 때 답이 비슷한지는 문장을 벡터(뜻을 담은 숫자 목록)로 바꿔 각도를 재고, 말투나 공감처럼 규칙으로 못 적는 것은 다른 모델에게 1에서 5로 매기게 한다. 채점기를 아래로 내릴수록 잴 수 있는 것이 넓어지고 값과 흔들림이 함께 커진다.\n\n셋째는 어려운 문항의 비율이다. 문서가 첫 원칙으로 드는 것이 실제로 들어오는 입력을 그대로 본뜨라는 것이고, 반어법·아주 긴 입력·사람도 판단이 갈리는 것 같은 가장자리를 일부러 섞어 두라고 적는다. 쉬운 문항만 모으면 통과율은 오르는데 배포하면 그대로 깨진다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 재는 방식 세 갈래","body":"| 갈래 | 무엇을 보나 | 언제 쓰나 |\n|---|---|---|\n| **metric** | 대개 정답과 견줘 성능을 잰다 | 시험지에 정답이 붙어 있을 때 |\n| **comparison** | 두 모델 이상의 답이 갈리는지를 잰다 | 어느 쪽을 쓸지 정할 때 |\n| **measurement** | 데이터와 모델 예측 자체를 들여다본다 | 시험지가 한쪽으로 쏠렸는지 볼 때 |\n\n순위표 점수 하나만 보면 둘째와 셋째가 통째로 빠진다. 같은 점수라도 두 모델이 틀리는 문항이 다르면 고르는 이유가 달라진다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **모델 교체 전후** — 같은 시험지를 새 모델에 한 번 더 돌려 어떤 항목이 내려갔는지 본다.\n- **프롬프트 손보기** — 한 줄 고칠 때마다 통과율을 재고, 내려가면 되돌린다.\n- **여러 잣대로 한꺼번에** — 정확도만이 아니라 응답 시간·비용·위험 문구 비율을 같은 표에 놓고 본다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **점수가 높으면 잘 되고 있는 것이다** — 시험지가 실제 들어오는 입력과 다르면 점수만 오른다. 첫 원칙이 실제 분포를 그대로 본뜨라는 것인 이유다.\n- **채점은 다른 모델에게 맡기는 게 제일 낫다** — 말투처럼 규칙으로 못 적는 것에는 맞지만, 정답이 딱 떨어지는 분류에는 글자 맞추기가 더 싸고 덜 흔들린다.\n- **사람이 직접 채점해야 믿을 만하다** — 문서는 반대로 적는다. 신호가 조금 흐려도 자동 채점으로 문항 수를 늘리는 쪽을 먼저 하라는 것이다."}],"figure":"```도해\n흐름: 고친 프롬프트가 나아졌는지 어떻게 아나\n시험 문항 :: 입력과 정답을 짝지어 미리 모아 둔다\n모델 :: 문항마다 답을 만든다\n채점기 :: 정한 기준으로 답마다 점수를 매긴다\n점수 :: 전체 통과율 한 숫자로 모인다\n@ 다시 고치기 :: 오르면 남기고 내리면 되돌린다\n= 느낌 대신 같은 시험지를 매번 다시 풀려서, 고친 것이 나아졌는지를 숫자로 본다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 고친 프롬프트를 눈으로만 보면 무엇이 안 보이나\n평가 없이 || 평가로\n판단 근거 :: 예시 서너 개 || 문항 수백 개\n고친 뒤 :: 깨진 걸 모른다 || 내려간 게 뜬다\n모델 교체 :: 감으로 정한다 || 같은 시험 재실행\n= 좋아진 느낌과 실제로 좋아진 것을 가르는 자리다\n```\n\n프롬프트 한 줄을 고치면 좋아지는 항목과 나빠지는 항목이 같이 생긴다. 눈으로 보는 예시는 대개 잘 되는 쪽만 몇 개라, 나빠진 쪽은 배포한 뒤에야 사용자가 발견한다.\n\n성공 기준을 먼저 못 박으면 이 사각지대가 줄어든다. \"안전한 답\" 이 아니라 \"만 번 중 걸리는 것이 0.1% 미만\" 처럼 적어 두면, 다음에 고쳤을 때 그 숫자가 올랐는지 내렸는지가 바로 보인다. 애매한 주제도 이렇게 숫자로 옮길 수 있다는 것이 Anthropic 문서가 드는 예다."},"recap":"**\"고친 것이 나아졌는지 재는 같은 시험지\"** 라고 읽으면 된다. 성공 기준을 숫자로 먼저 적고, 실제 입력을 본뜬 문항을 모으고, 채점을 되도록 자동으로 돌린다. 모델을 바꾸거나 올릴 때 이 시험지가 없으면 나빠진 자리를 사용자가 먼저 발견한다.","kid":"공부하는 방법을 바꿨을 때 진짜 나아졌는지 어떻게 알아? 똑같은 문제지를 다시 풀어 보고 몇 개 더 맞았는지 세면 되지. 그래서 방법을 바꿀 때마다 그 문제지를 꺼내는 거야.","check":[{"q":"예시 서너 개만 눈으로 보고 넘어가면 무엇을 놓치나","at":"해결하는 문제"},{"q":"문항을 늘리는 쪽과 한 문항을 정성껏 채점하는 쪽 중 무엇을 먼저 하나","at":"작동 원리"},{"q":"정답이 딱 떨어지는 분류에 다른 모델을 채점기로 세우면 무엇이 손해인가","at":"흔한 오해"}],"myths":[{"wrong":"점수가 높으면 잘 되고 있는 것이다","right":"시험지가 실제 들어오는 입력과 다르면 점수만 오른다. 첫 원칙이 실제 분포를 그대로 본뜨라는 것인 이유다."},{"wrong":"채점은 다른 모델에게 맡기는 게 제일 낫다","right":"말투처럼 규칙으로 못 적는 것에는 맞지만, 정답이 딱 떨어지는 분류에는 글자 맞추기가 더 싸고 덜 흔들린다."},{"wrong":"사람이 직접 채점해야 믿을 만하다","right":"문서는 반대로 적는다. 신호가 조금 흐려도 자동 채점으로 문항 수를 늘리는 쪽을 먼저 하라는 것이다."}],"cases":[{"label":"모델 교체 전후","note":"같은 시험지를 새 모델에 한 번 더 돌려 어떤 항목이 내려갔는지 본다."},{"label":"프롬프트 손보기","note":"한 줄 고칠 때마다 통과율을 재고, 내려가면 되돌린다."},{"label":"여러 잣대로 한꺼번에","note":"정확도만이 아니라 응답 시간·비용·위험 문구 비율을 같은 표에 놓고 본다."}],"dia":{"shape":"흐름","title":"고친 프롬프트가 나아졌는지 어떻게 아나","rows":[{"who":"시험 문항","what":"입력과 정답을 짝지어 미리 모아 둔다"},{"who":"모델","what":"문항마다 답을 만든다"},{"who":"채점기","what":"정한 기준으로 답마다 점수를 매긴다"},{"who":"점수","what":"전체 통과율 한 숫자로 모인다"}],"sum":"느낌 대신 같은 시험지를 매번 다시 풀려서, 고친 것이 나아졌는지를 숫자로 본다","loop":{"who":"다시 고치기","what":"오르면 남기고 내리면 되돌린다"}}},"ai--fallback":{"definition":"찾던 곳에 답이 없거나 그 쪽이 응답하지 않을 때, 빈손으로 끝내는 대신 다음 순서로 정해둔 곳에 다시 물어본다. 어디까지 내려갈지와 끝까지 실패하면 무엇을 돌려줄지를 미리 정해두는 것이 폴백 설계다.","name":"Fall back :: 뒤로 물러서다\n= 앞이 막히면 뒤에 마련해 둔 자리로 물러선다는 말이다. 물러설 자리를 미리 정해 두는 것이 이 일의 전부다","analogy":"편의점에 찾던 음료가 없으면 옆 가게로 가고, 거기도 없으면 비슷한 걸 사는 것과 같다.","example":"휴대폰 지문 인식이 두어 번 실패하면 비밀번호 입력 화면이 뜨는 그 자리다.","tryit":"잠금 화면에 일부러 엉뚱한 손가락을 두어 번 대 보라. 지문을 더 붙잡지 않고 비밀번호 화면으로 내려간다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"순서를 정하는 기준은 대개 빠르고 정확한 것부터다. 미리 정리된 FAQ가 있으면 그것부터 보고, 없으면 문서 검색으로, 그것도 없으면 더 넓은 곳으로 내려간다. 아래로 갈수록 답을 찾을 확률은 올라가고 정확도는 떨어진다.\n\n여기서 까다로운 것은 \"실패\"를 무엇으로 볼지다. 오류가 난 경우는 명확하지만, 응답이 오긴 왔는데 \"찾을 수 없습니다\"인 경우도 실패로 봐야 한다. 이걸 성공으로 처리하면 체인은 첫 단계에서 멈추고 아래 순서는 영영 쓰이지 않는다.\n\n질문 종류마다 순서를 따로 두기도 한다. 사내 규정을 묻는 질문과 화면 위치를 묻는 질문은 뒤져야 할 곳이 다르기 때문이다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 폴백과 에스컬레이션","body":"| | 폴백 | 에스컬레이션 |\n|---|---|---|\n| 하는 일 | 다른 방법으로 다시 시도 | 사람에게 넘김 |\n| 사람 개입 | 없다 | 필요하다 |\n| 언제 | 한 방법이 실패했을 때 | 방법이 다 떨어졌을 때 |\n| 비용 | 낮다 | 높다 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **답변 체인** — FAQ에 없으면 사내 문서를 뒤지고, 거기에도 없으면 더 일반적인 답변으로 내려간다.\n- **응답이 늦을 때** — 정해둔 시간 안에 답이 안 오면 기다리지 않고 다음 순서로 넘긴다.\n- **최종 문구** — 전부 실패하면 \"찾지 못했다\"와 함께 다음에 어디로 가면 되는지를 같이 알려준다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **폴백은 그냥 다시 시도하는 것이다** — 같은 곳에 다시 묻는 건 재시도다. 폴백은 다른 곳에 묻는 것이고, 안 되는 곳을 계속 두드리지 않는다는 점이 다르다.\n- **폴백을 많이 걸어둘수록 좋다** — 순서가 길어지면 실패할 때마다 시간이 쌓인다. 마지막 순서까지 갔을 때 사용자가 얼마나 기다리게 되는지가 실제 상한이다.\n- **폴백이 있으면 장애가 안 보인다** — 안 보이는 게 문제다. 아래 순서로 계속 내려가고 있다는 사실을 기록해두지 않으면 1순위가 죽은 채로 오래 방치된다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **아래로 내려갈수록 답의 근거가 약해진다.** 어느 순서에서 나온 답인지 사용자에게 알려주지 않으면, 확실한 답과 대충 맞는 답이 같은 얼굴로 나간다.\n- **모든 실패를 같게 다루지 않는다.** 자료가 없어서 못 찾은 것과 서비스가 죽어서 못 받은 것은 다음 대응이 달라야 한다."}],"figure":"```도해\n흐름: 첫 번째가 답을 못 주면 무슨 일이 일어나나\n질문 :: 사용자가 규정을 물어본다\n1순위 :: FAQ 에서 찾는다. 없다\n2순위 :: 문서 검색으로 넘어간다. 찾았다\n최종 :: 여기까지도 못 찾으면 정해둔 문구\n< 사용자 :: 어느 순서에서 나왔든 답을 하나 받는다\n= 실패를 끝이 아니라 다음 순서로 넘어가는 신호로 쓴다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 첫 시도가 실패하면 어떻게 되나\n폴백 없이 || 폴백으로\n답 없음 :: 빈 화면 || 다음에 물어봄\n한 곳 장애 :: 전체 멈춤 || 그 순서만 건너뜀\n사용자 :: 그냥 떠남 || 어떻게든 받음\n= 한 곳의 실패를 전체의 실패로 만들지 않는 장치다\n```\n\n정보를 한 곳에서만 찾으면 그 한 곳의 사정이 그대로 결과가 된다. 자료가 아직 안 들어갔거나, 그 서비스가 잠깐 멈췄거나, 응답이 늦으면 사용자에게는 전부 똑같이 \"답이 없다\"로 보인다.\n\n폴백은 그 실패를 신호로 바꾼다. 찾지 못했다는 응답이 오면 다음 순서로 넘어가고, 마지막까지 못 찾으면 그때는 무엇을 돌려줄지 정해둔 문구가 나간다. 실패하더라도 무엇을 받을지가 정해져 있다."},"recap":"**\"막히면 물러설 자리를 미리 정해 둔 그 차례\"** 라고 읽으면 된다. 순서를 정하는 일보다 무엇을 실패로 볼지, 끝까지 실패하면 무엇을 돌려줄지를 정하는 일이 실제 설계다. 내려가고 있다는 사실을 남기지 않으면 장애가 조용히 묻힌다.","kid":"음료수 사러 갔는데 그게 없으면 옆 가게로 가고, 거기도 없으면 비슷한 걸 사 오지? 어디로 갈지를 집에서 나오기 전에 미리 정해 두는 거야. 그래야 한 군데가 문을 닫아도 빈손으로 돌아오지 않아.","check":[{"q":"1순위가 \"찾을 수 없습니다\"라고 답했을 때 이걸 성공으로 처리하면 무슨 일이 벌어지나","at":"작동 원리"},{"q":"재시도만 걸어두는 것과 폴백을 두는 것은 무엇이 다른가","at":"흔한 오해"},{"q":"폴백 순서를 아래까지 내려가서 받은 답은 무엇이 약한가","at":"주의사항"}],"myths":[{"wrong":"폴백은 그냥 다시 시도하는 것이다","right":"같은 곳에 다시 묻는 건 재시도다. 폴백은 다른 곳에 묻는 것이고, 안 되는 곳을 계속 두드리지 않는다는 점이 다르다."},{"wrong":"폴백을 많이 걸어둘수록 좋다","right":"순서가 길어지면 실패할 때마다 시간이 쌓인다. 마지막 순서까지 갔을 때 사용자가 얼마나 기다리게 되는지가 실제 상한이다."},{"wrong":"폴백이 있으면 장애가 안 보인다","right":"안 보이는 게 문제다. 아래 순서로 계속 내려가고 있다는 사실을 기록해두지 않으면 1순위가 죽은 채로 오래 방치된다."}],"cases":[{"label":"답변 체인","note":"FAQ에 없으면 사내 문서를 뒤지고, 거기에도 없으면 더 일반적인 답변으로 내려간다."},{"label":"응답이 늦을 때","note":"정해둔 시간 안에 답이 안 오면 기다리지 않고 다음 순서로 넘긴다."},{"label":"최종 문구","note":"전부 실패하면 \"찾지 못했다\"와 함께 다음에 어디로 가면 되는지를 같이 알려준다."}],"dia":{"shape":"흐름","title":"첫 번째가 답을 못 주면 무슨 일이 일어나나","rows":[{"who":"질문","what":"사용자가 규정을 물어본다"},{"who":"1순위","what":"FAQ 에서 찾는다. 없다"},{"who":"2순위","what":"문서 검색으로 넘어간다. 찾았다"},{"who":"최종","what":"여기까지도 못 찾으면 정해둔 문구"},{"who":"사용자","what":"어느 순서에서 나왔든 답을 하나 받는다","back":true}],"sum":"실패를 끝이 아니라 다음 순서로 넘어가는 신호로 쓴다"}},"ai--few-shot-zero-shot-learning":{"definition":"모델을 다시 학습시키지 않고 프롬프트만으로 새 작업을 시킨다. 예시가 없으면 Zero-shot, 두어 개면 Few-shot, 수십 개를 넘어가면 Many-shot이라 부른다.","name":"Zero-shot :: 보기 0장으로 시킴\nFew-shot :: 보기 두어 장 보임\n= shot 은 \"보여 주는 한 컷\" 이다. 앞의 숫자가 그 컷을 몇 장 붙였는지를 가리킨다","analogy":"새로 온 사람에게 일을 넘길 때, 말로만 설명하는 것과 처리해둔 서류 두어 장을 같이 건네는 것의 차이다.","example":"엑셀에서 두어 칸을 직접 채우고 아래로 끌면 나머지가 같은 모양으로 채워진다. 채워둔 두 칸이 형식을 정한 것이다.","tryit":"챗봇에 같은 것을 두 번 시켜 보라. 한 번은 그냥, 한 번은 원하는 모양의 보기 두 개를 붙여서. 답의 꼴이 달라진다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"예시는 모델 안에 남지 않는다. 그 요청에 붙어 간 글일 뿐이고, 다음 요청에는 다시 붙여야 한다. 모델은 예시에서 두 가지를 읽는다. 답을 어떤 형식으로 쓸지, 그리고 경계에 걸치는 입력을 어느 쪽으로 볼지.\n\n```\n다음 예시처럼 분류하세요.\n\n문장: \"정말 최고예요!\"   감정: 긍정\n문장: \"실망스럽네요\"     감정: 부정\n문장: \"보통이에요\"       감정: 중립\n\n이제 분류하세요.\n문장: {입력}\n감정:\n```\n\n개수를 늘릴수록 정확해지지만 토큰과 비용도 같이 늘어난다. 보통 서너 개 근처에서 더 넣어도 나아지는 폭이 크게 줄어든다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교","body":"| | 예시 개수 | 토큰 | 잘 맞는 곳 |\n|---|---|---|---|\n| Zero-shot | 0개 | 적다 | 감정 분류, 요약, 번역처럼 흔한 작업 |\n| Few-shot | 2~10개 | 많다 | 정해진 형식이나 특정 분야의 답 |\n| Many-shot | 수십~수백 개 | 아주 많다 | 규칙이 복잡해 말로 설명하기 어려운 것 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **답변 형식 맞추기** — 근거 조항을 앞에 붙인 답변을 예시로 두면 이후 답도 같은 모양으로 나온다.\n- **애매한 경계 정하기** — 어중간한 문장을 예시에 넣어 어디까지가 긍정이고 어디부터 중립인지 정해준다.\n- **풀이 과정 보이기** — 단계별로 계산한 예시를 넣으면 답만 던지지 않고 과정을 따라 쓴다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **Few-shot은 모델을 학습시키는 것이다** — 모델은 그대로다. 예시는 그 요청 한 번에만 붙어 있는 글이라 다음 요청에는 다시 붙여야 한다.\n- **예시가 많을수록 좋다** — 토큰과 비용이 따라 늘고 컨텍스트 창을 밀어낸다. 서너 개를 넘어가면 늘린 만큼 나아지지 않는다.\n- **Zero-shot은 예시를 못 넣어서 쓰는 것이다** — 흔한 작업에서는 예시 없이도 답이 나오고 그만큼 싸고 빠르다. 예시는 형식이나 기준이 특이할 때 붙인다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **예시가 서로 비슷하면 낭비다.** 같은 유형을 세 번 보여주는 대신 수량을 묻는 것, 절차를 묻는 것, 자격을 묻는 것처럼 다른 유형을 섞는다.\n- **예시끼리 형식이 어긋나면 답도 어긋난다.** 어떤 예시는 근거를 쓰고 어떤 예시는 안 쓰면 모델은 둘 중 아무거나 고른다.\n- **예시도 컨텍스트 창을 먹는다.** 예시를 백 개까지 늘리면 정작 넣어야 할 문서가 들어갈 자리가 없어진다."}],"figure":"```도해\n흐름: 예시를 붙이면 답이 왜 달라지나\n프롬프트 :: \"이 문장의 감정을 분류해줘\"\n예시 :: \"최고예요 → 긍정\" 을 두어 개 붙인다\n모델 :: 예시에서 답의 형태와 기준을 읽는다\n답 :: 예시와 같은 모양으로 돌려준다\n@ 다음 요청 :: 예시를 또 붙여야 한다. 토큰도 매번\n= 예시는 새로 배우게 하는 게 아니라 답의 틀을 정해주는 것이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 새 작업을 시키려면 무엇이 필요한가\n따로 학습시켜서 || 예시를 붙여서\n준비물 :: 데이터 수천 건 || 예시 두세 개\n착수 :: 학습을 돌린다 || 바로 쓴다\n바꾸려면 :: 다시 학습 || 예시만 고침\n= 모델을 건드리지 않고 프롬프트 안에서 끝내는 것이 요점이다\n```\n\n전통적인 기계학습은 새 작업마다 수천에서 수만 건의 학습 데이터를 모아야 했다. Fine-tuning으로 줄여도 최소 50~100개 예시가 들고, 기준이 바뀌면 다시 학습을 돌려야 한다.\n\n프롬프트에 예시를 붙이는 방식은 그 준비를 건너뛴다. 기준이 바뀌면 예시 문장을 고치면 되고, 반영은 다음 요청부터 곧바로 된다."},"recap":"**\"보기를 몇 장 붙여 주느냐 하는 그 차이\"** 라고 읽으면 된다. 예시는 모델을 가르치는 장치가 아니라 그 요청 안에서 답의 형식과 기준을 정해주는 장치다. 형식이 특이하거나 경계가 애매할 때만 붙이고, 개수는 서너 개에서 멈추는 편이 낫다.","kid":"새로 온 형한테 일을 맡길 때 말로만 \"이렇게 해\" 하는 거랑, 이미 해 놓은 것 두 장을 같이 보여 주는 거랑 다르지? 두 장을 보여 주면 어떤 모양으로 써야 하는지 바로 따라 해. 대신 다음에 부탁할 때도 그 두 장을 또 보여 줘야 해, 돌아서면 잊어버리거든.","check":[{"q":"Few-shot으로 잘 나오던 형식이 다음 요청에서 흐트러졌다. 예시를 다시 안 붙였다면 왜 그런가","at":"작동 원리"},{"q":"예시를 3개에서 30개로 늘렸는데 비용만 늘고 답은 그대로다. 무엇을 잘못 본 건가","at":"흔한 오해"},{"q":"감정 분류처럼 흔한 작업에 굳이 예시를 안 붙여도 되는 이유는","at":"비교"}],"myths":[{"wrong":"Few-shot은 모델을 학습시키는 것이다","right":"모델은 그대로다. 예시는 그 요청 한 번에만 붙어 있는 글이라 다음 요청에는 다시 붙여야 한다."},{"wrong":"예시가 많을수록 좋다","right":"토큰과 비용이 따라 늘고 컨텍스트 창을 밀어낸다. 서너 개를 넘어가면 늘린 만큼 나아지지 않는다."},{"wrong":"Zero-shot은 예시를 못 넣어서 쓰는 것이다","right":"흔한 작업에서는 예시 없이도 답이 나오고 그만큼 싸고 빠르다. 예시는 형식이나 기준이 특이할 때 붙인다."}],"cases":[{"label":"답변 형식 맞추기","note":"근거 조항을 앞에 붙인 답변을 예시로 두면 이후 답도 같은 모양으로 나온다."},{"label":"애매한 경계 정하기","note":"어중간한 문장을 예시에 넣어 어디까지가 긍정이고 어디부터 중립인지 정해준다."},{"label":"풀이 과정 보이기","note":"단계별로 계산한 예시를 넣으면 답만 던지지 않고 과정을 따라 쓴다."}],"dia":{"shape":"흐름","title":"예시를 붙이면 답이 왜 달라지나","rows":[{"who":"프롬프트","what":"\"이 문장의 감정을 분류해줘\""},{"who":"예시","what":"\"최고예요 → 긍정\" 을 두어 개 붙인다"},{"who":"모델","what":"예시에서 답의 형태와 기준을 읽는다"},{"who":"답","what":"예시와 같은 모양으로 돌려준다"}],"sum":"예시는 새로 배우게 하는 게 아니라 답의 틀을 정해주는 것이다","loop":{"who":"다음 요청","what":"예시를 또 붙여야 한다. 토큰도 매번"}}},"ai--fine-tuning":{"definition":"모델을 처음부터 만드는 데는 막대한 데이터와 계산이 든다. 파인튜닝은 이미 언어를 아는 모델에 우리 예시 수백 개를 더 보여줘서 답하는 방식만 바꾼다.","name":"Fine :: 아주 미세한\nTuning :: 음을 맞추는 일\n= 붙여 읽으면 \"미세하게 음 맞추기\". 악기를 새로 만드는 게 아니라 줄을 조금 조이는 일이다","analogy":"이미 의사 면허가 있는 사람에게 한 분야만 더 수련시키는 것이다. 의학을 처음부터 가르치지 않는다.","example":"몇 달 쓴 휴대폰 자판이 내가 자주 쓰는 말투부터 먼저 띄워주게 되는 그 변화와 결이 같다.","tryit":"폰 자판 설정에서 \"학습한 단어 삭제\" 를 찾아보라. 자판이 나에게 맞춰 옮겨간 값을 처음으로 되돌리는 단추다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"```도해\n흐름: 예시 한 짝이 모델의 숫자를 어떻게 옮기나\n질문 넣기 :: 예시의 질문만 넣고 모델이 답하게 둔다\n견주기 :: 나온 답과 우리가 적어둔 답의 차이를 잰다\n되짚기 :: 그 차이에 어느 숫자가 얼마나 거들었는지 거슬러 센다\n밀기 :: 차이가 줄어드는 쪽으로 그 숫자들을 조금 옮긴다\n@ 다음 예시 :: 같은 네 칸을 예시마다, 그리고 여러 바퀴 되풀이한다\n= 예시를 외우는 게 아니라 예시 쪽으로 숫자를 조금씩 끌어당기는 일이다\n```\n\n\"조금씩\" 이 이 일의 전부다. 한 번에 크게 밀면 우리 예시에는 잘 맞지만 원래 알던 것이 뭉개진다 — 회사 말투를 익히다 일반 상식이 흐려지는 식이다. 그래서 한 걸음의 크기를 작게 잡고 여러 바퀴에 나눠 옮긴다.\n\n본체 숫자를 통째로 미는 대신, 그것은 얼려 두고 옆에 작은 숫자 판을 덧대 그것만 미는 방식도 많이 쓴다. 옮길 숫자가 적으니 학습이 싸게 끝나고, 원래 알던 것을 건드릴 여지도 그만큼 줄어든다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교","body":"| | 프롬프트 | RAG | 파인튜닝 |\n|---|---|---|---|\n| 준비 | 바로 | 문서를 넣어두면 됨 | 예시 수백 개 |\n| 반영 시점 | 즉시 | 즉시 | 재학습 후 |\n| 잘 맞는 것 | 일반 작업 | 자주 바뀌는 정보 | 고정된 형식과 말투 |\n| 바뀌면 | 문장만 고친다 | 문서만 갈아 끼운다 | 처음부터 다시 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **정해진 답변 형식** — 상담 답변을 늘 같은 구조로 뽑아야 할 때 그 형식의 예시로 학습시킨다.\n- **전문 분야 번역** — 법률이나 의료 용어 번역 쌍을 학습시켜 용어 선택을 일정하게 만든다.\n- **회사 코드 스타일** — 사내 코드 리뷰 기록을 학습시켜 제안하는 코드의 모양을 맞춘다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **파인튜닝하면 모델이 우리 문서를 기억한다** — 기억하지 못한다. 옮겨지는 건 답하는 방식이고, 사실을 정확히 인용하게 하려면 문서를 그때그때 찾아 넣어주는 방식이 맞다.\n- **데이터가 많을수록 무조건 좋다** — 양보다 일관성이다. 같은 질문에 서로 다른 형식의 답이 섞여 있으면 모델은 어느 쪽도 제대로 배우지 않는다.\n- **한 번 학습시키면 계속 최신 상태다** — 학습한 시점에서 멈춘다. 규정이 바뀌면 예시를 고쳐 다시 학습시켜야 하고 그때마다 비용이 다시 든다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **예시가 적으면 흉내만 낸다.** 수가 부족하면 학습 예시에만 잘 맞고 조금 다른 질문에는 오히려 나빠진다.\n- **바뀌는 정보에는 쓰지 않는다.** 규정이나 가격처럼 자주 고쳐지는 내용은 학습이 아니라 문서 조회로 다뤄야 한다."}],"figure":"```도해\n흐름: 우리 회사 말투로 답하게 만들려면 무슨 순서로 하나\n예시 모으기 :: 질문과 원하는 답을 짝지어 수백 개 만든다\n형식 맞추기 :: 정해진 형식의 파일로 정리한다\n추가 학습 :: 기존 모델의 값을 그 예시 쪽으로 조금씩 옮긴다\n새 모델 :: 우리 예시를 닮은 모델이 하나 나온다\n사용 :: 긴 지시문 없이 질문만 보내도 그 말투로 답한다\n@ 내용이 바뀌면 :: 예시를 고쳐 처음부터 다시 돌린다\n= 지식을 넣는다기보다 답하는 방식을 옮기는 작업이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 매번 긴 지시문을 붙여 쓰면 어떻게 되나\n지시문으로 || 파인튜닝으로\n요청 길이 :: 매번 길어진다 || 질문만 보낸다\n말투 :: 들쭉날쭉하다 || 일정하다\n비용 구조 :: 요청마다 낸다 || 학습에 한 번\n= 매 요청에 붙이던 것을 모델 안으로 옮기는 것이다\n```\n\n같은 지시문을 매 요청마다 앞에 붙이면 그만큼 토큰을 쓴다. 요청이 많아지면 이 비용이 계속 쌓이고, 지시문이 길어도 모델이 매번 똑같이 따르지는 않는다.\n\n파인튜닝은 그 지시를 예시로 바꿔 모델에 새겨 넣는다. 그다음부터는 짧은 질문만 보내도 학습시킨 형식대로 답한다. 대신 내용이 바뀌면 다시 학습시켜야 한다."},"recap":"**\"다 배운 모델에 우리 예시만 더 먹이는 그 수련\"** 이라고 읽으면 된다. 형식과 말투를 고정하는 데는 잘 듣지만, 자주 바뀌는 사실을 넣는 용도로는 맞지 않는다.","kid":"글을 이미 다 뗀 형한테 우리 집에서만 쓰는 말투를 며칠 더 가르치는 거야. 글자를 처음부터 다시 가르치는 게 아니라 말하는 버릇만 바꾸는 거지. 그래서 오늘 새로 생긴 소식을 알려 주는 데는 소용이 없어, 버릇이 바뀐 거지 새 이야기를 들은 게 아니거든.","check":[{"q":"자주 바뀌는 사내 규정을 파인튜닝으로 넣으면 왜 곤란해지나","at":"주의사항"},{"q":"매 요청에 붙이던 긴 지시문이 사라지면 무엇이 줄어드나","at":"해결하는 문제"},{"q":"예시를 수백 개 모았는데 답 형식이 제각각이면 어떤 결과가 나오나","at":"흔한 오해"}],"myths":[{"wrong":"파인튜닝하면 모델이 우리 문서를 기억한다","right":"기억하지 못한다. 옮겨지는 건 답하는 방식이고, 사실을 정확히 인용하게 하려면 문서를 그때그때 찾아 넣어주는 방식이 맞다."},{"wrong":"데이터가 많을수록 무조건 좋다","right":"양보다 일관성이다. 같은 질문에 서로 다른 형식의 답이 섞여 있으면 모델은 어느 쪽도 제대로 배우지 않는다."},{"wrong":"한 번 학습시키면 계속 최신 상태다","right":"학습한 시점에서 멈춘다. 규정이 바뀌면 예시를 고쳐 다시 학습시켜야 하고 그때마다 비용이 다시 든다."}],"cases":[{"label":"정해진 답변 형식","note":"상담 답변을 늘 같은 구조로 뽑아야 할 때 그 형식의 예시로 학습시킨다."},{"label":"전문 분야 번역","note":"법률이나 의료 용어 번역 쌍을 학습시켜 용어 선택을 일정하게 만든다."},{"label":"회사 코드 스타일","note":"사내 코드 리뷰 기록을 학습시켜 제안하는 코드의 모양을 맞춘다."}],"dia":{"shape":"흐름","title":"우리 회사 말투로 답하게 만들려면 무슨 순서로 하나","rows":[{"who":"예시 모으기","what":"질문과 원하는 답을 짝지어 수백 개 만든다"},{"who":"형식 맞추기","what":"정해진 형식의 파일로 정리한다"},{"who":"추가 학습","what":"기존 모델의 값을 그 예시 쪽으로 조금씩 옮긴다"},{"who":"새 모델","what":"우리 예시를 닮은 모델이 하나 나온다"},{"who":"사용","what":"긴 지시문 없이 질문만 보내도 그 말투로 답한다"}],"sum":"지식을 넣는다기보다 답하는 방식을 옮기는 작업이다","loop":{"who":"내용이 바뀌면","what":"예시를 고쳐 처음부터 다시 돌린다"}}},"ai--guardrail":{"definition":"모델은 시키는 대로 답하려 하기 때문에 위험한 요청도 그대로 처리한다. 그래서 모델 밖에 검사를 따로 세워 들어오는 말과 나가는 말과 하려는 동작을 각각 본다.","name":"Guard :: 지켜 막다\nRail :: 길가에 세운 난간\n= 붙여 읽으면 \"지켜 주는 난간\". 운전을 대신해 주는 게 아니라 길 밖으로 나가는 것만 막는다","analogy":"도로 가드레일. 운전자가 잘못 꺾어도 차가 낭떠러지로 가지 않게 옆을 막아둔다.","example":"AI가 답을 쓰다 말고 그 줄이 통째로 지워지며 도울 수 없다는 문구로 바뀌는 것을 본 적이 있다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"| 자리 | 언제 보나 | 무엇을 막나 |\n|---|---|---|\n| 입력 | 요청을 받을 때 | 개인정보 입력, 공격 문자열 |\n| 행동 | 도구를 부르기 전 | 권한 없는 조회와 삭제 |\n| 출력 | 답을 내보내기 전 | 비밀 값과 민감 정보 노출 |\n| 실행 | 작업이 도는 중 | 같은 호출 반복, 끝나지 않는 작업 |\n\n막는 것만으로는 절반이다. 왜 막혔는지 알려주지 않으면 사용자는 시스템이 고장 났다고 여기고 같은 요청을 되풀이한다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **개인정보 입력 차단** — 채팅창에 주민번호 형태의 숫자가 들어오면 처리하지 않고 입력하지 말라고 안내한다.\n- **응답 가리기** — 답에 전화번호나 비밀 값이 섞이면 그 부분을 가린 뒤 내보낸다.\n- **권한 확인** — 급여 데이터를 읽는 동작 앞에서 그 계정에 권한이 있는지 먼저 보고 없으면 실행하지 않는다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **프롬프트에 하지 말라고 써두면 그게 Guardrail이다** — 프롬프트는 부탁이고 Guardrail은 코드로 된 검사다. 모델이 지시를 어기는 경우가 있어서 바깥에 따로 세운다.\n- **입력만 막으면 된다** — 정상적인 질문에도 민감한 값이 답에 섞여 나올 수 있다. 나가는 쪽 검사가 따로 필요하다.\n- **엄격할수록 안전하다** — 정상적인 요청까지 막히면 사람들은 우회로를 찾는다. 명확한 위험은 즉시 막고 애매한 것은 되묻는 편이 낫다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **막힌 시도를 기록으로 남긴다.** 무엇이 얼마나 막혔는지 봐야 규칙이 센지 느슨한지 판단할 수 있다.\n- **차단 이유를 사용자에게 알린다.** 이유 없이 막히면 같은 요청이 반복되고 문의가 늘어난다."}],"figure":"```도해\n흐름: 사용자 말 한 마디가 어디를 거쳐 답이 되나\n입력 검사 :: 개인정보나 공격 문자열이 있나\n모델 :: 통과한 것만 받아 답을 만든다\n행동 검사 :: 조회나 삭제를 할 권한이 있나\n출력 검사 :: 답에 비밀 값이 섞여 있나\n< 사용자 :: 네 자리를 다 통과한 답만 보인다\n= 막는 자리가 여럿이고 자리마다 보는 것이 다르다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 검사 없이 모델 답을 그대로 내보내면 어떻게 되나\nGuardrail 없이 || Guardrail 로\n주민번호 :: 그대로 나감 || 가려서 나감\n권한 밖 조회 :: 그냥 실행됨 || 앞에서 막힘\n공격 문자열 :: 질의로 전달됨 || 입력에서 차단\n= 모델은 요청을 의심하지 않는다. 의심하는 자리를 밖에 둔다\n```\n\n모델은 요청이 정당한지 따지지 않는다. 주민번호를 넣어 조회해 달라고 하면 그대로 조회하고, 전체 급여 목록을 달라고 하면 갖고 있는 만큼 답한다. 답을 잘 만드는 능력과 하면 안 되는 일을 가려내는 능력은 별개다.\n\nGuardrail은 그 판단을 모델 밖에 둔다. 들어오는 말을 먼저 보고, 실행하려는 동작에 권한이 있는지 보고, 나가는 답에 남으면 안 될 것이 섞였는지 본다."},"recap":"**\"길 밖으로 나가는 것만 막아 세운 그 난간\"** 이라고 읽으면 된다. 입력, 행동, 출력, 실행 네 자리에서 보는 것이 각각 다르다. 막는 일과 왜 막혔는지 알리는 일이 함께 가야 한다.","kid":"산길 옆에 쇠막대가 쭉 세워져 있는 거 봤지? 그게 차를 대신 몰아 주지는 않지만, 잘못 꺾어도 낭떠러지 쪽으로는 못 가게 딱 막아 줘. 여기서도 하면 안 되는 말이 들어오거나 나가려고 하면 그 자리에서 붙잡아.","check":[{"q":"프롬프트에 하지 말라고 써두는 것과 Guardrail 은 무엇이 다른가","at":"흔한 오해"},{"q":"입력 검사를 통과한 질문인데도 출력 검사가 필요한 경우는 어떤 것인가","at":"실제 사례"},{"q":"규칙에 걸려 막혔는데 이유를 안 알려주면 사용자는 무엇을 하나","at":"작동 원리"}],"myths":[{"wrong":"프롬프트에 하지 말라고 써두면 그게 Guardrail이다","right":"프롬프트는 부탁이고 Guardrail은 코드로 된 검사다. 모델이 지시를 어기는 경우가 있어서 바깥에 따로 세운다."},{"wrong":"입력만 막으면 된다","right":"정상적인 질문에도 민감한 값이 답에 섞여 나올 수 있다. 나가는 쪽 검사가 따로 필요하다."},{"wrong":"엄격할수록 안전하다","right":"정상적인 요청까지 막히면 사람들은 우회로를 찾는다. 명확한 위험은 즉시 막고 애매한 것은 되묻는 편이 낫다."}],"cases":[{"label":"개인정보 입력 차단","note":"채팅창에 주민번호 형태의 숫자가 들어오면 처리하지 않고 입력하지 말라고 안내한다."},{"label":"응답 가리기","note":"답에 전화번호나 비밀 값이 섞이면 그 부분을 가린 뒤 내보낸다."},{"label":"권한 확인","note":"급여 데이터를 읽는 동작 앞에서 그 계정에 권한이 있는지 먼저 보고 없으면 실행하지 않는다."}],"dia":{"shape":"흐름","title":"사용자 말 한 마디가 어디를 거쳐 답이 되나","rows":[{"who":"입력 검사","what":"개인정보나 공격 문자열이 있나"},{"who":"모델","what":"통과한 것만 받아 답을 만든다"},{"who":"행동 검사","what":"조회나 삭제를 할 권한이 있나"},{"who":"출력 검사","what":"답에 비밀 값이 섞여 있나"},{"who":"사용자","what":"네 자리를 다 통과한 답만 보인다","back":true}],"sum":"막는 자리가 여럿이고 자리마다 보는 것이 다르다"}},"ai--hallucination":{"definition":"없는 논문 제목, 없는 함수 이름, 없는 조항을 자신 있는 말투로 만들어낸다. 거짓말을 하려는 게 아니라, 그럴듯한 다음 단어를 고르는 일을 정직하게 수행한 결과다.","name":"Hallucinate :: 헛것을 보다\n= 라틴어 hallucinari(\"마음이 헤매다\")에서 온 말이다. 거짓말과 달리 말하는 쪽은 그것을 진짜로 여긴다","analogy":"시험에서 모르는 문제를 만난 학생이 빈칸을 두는 대신 그럴듯하게 채우는 것. 채워야 한다는 압박만 있고 모른다고 말할 선택지가 없으면 누구나 그렇게 된다.","example":"알려준 책 제목을 그대로 검색창에 넣었는데 그런 책이 없다고 나오는 순간이다.","tryit":"챗봇에 어떤 주제의 책 세 권을 추천받고 그 제목을 그대로 검색해 보라. 그중 한둘은 없는 책일 때가 있다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"어디서 잘 나오는지에 규칙성이 있다.\n\n```도해\n층: 어떤 질문에서 환각이 잘 나오나\n최신 정보 :: 학습 이후의 일. 아예 모른다\n좁은 사실 :: 특정 논문, 조항, 사내 규정\n숫자와 인용 :: 형식은 알지만 값은 모른다\n일반 상식 :: 여기서는 잘 안 나온다\n= 아래로 갈수록 안전하다. 위쪽을 물을 때 근거를 붙여야 한다\n```"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **없는 라이브러리 함수** — 그럴듯한 이름의 함수를 쓴 코드를 준다. 실행해야 없다는 걸 안다.\n- **법 조항 인용** — 조문 번호와 문구를 만들어낸다. 형식이 정확해서 더 위험하다.\n- **인용 출처** — 제목, 저자, 연도가 모두 갖춰진 존재하지 않는 문헌을 만든다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **환각은 고칠 수 있는 버그다** — 다음 토큰을 확률로 고르는 구조에서 나오는 성질이라 완전히 없앨 수 없다. 줄이고 검증할 대상이다.\n- **\"모르면 모른다고 해\"라고 지시하면 해결된다** — 도움은 되지만 모델은 자기가 모른다는 것을 모른다. 확률이 낮아도 가장 높은 후보를 고를 뿐이다.\n- **큰 모델을 쓰면 사라진다** — 줄어들긴 하지만 없어지지 않는다. 오히려 더 그럴듯해져서 알아채기 어려워진다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **형식이 정확할수록 의심한다.** 조문 번호, 논문 연도, 함수 시그니처처럼 형식이 뚜렷한 것이 가장 잘 만들어진다.\n- **사실 확인이 필요한 곳에는 근거를 강제한다.** 출처를 못 찾으면 답하지 말라는 규칙과 [[RAG]]를 같이 쓴다."}],"figure":"```도해\n흐름: 없는 논문 제목이 어떻게 만들어지나\n사용자 :: \"이 주제 논문 알려줘\" 라고 묻는다\n모델 :: 학습에서 본 제목의 생김새를 떠올린다\n모델 :: 이 자리에 올 법한 단어를 하나씩 고른다\n모델 :: 저자 이름과 연도도 그럴듯하게 잇는다\n< 사용자 :: 형식이 완벽한, 존재하지 않는 논문을 받는다\n= 모델에게는 \"지어내기\" 와 \"답하기\" 가 같은 동작이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"이 항목은 해결하는 문제가 아니라 **다뤄야 할 문제**다.\n\n```도해\n대조: 모르는 것을 물으면 어떻게 되나\n대비 없이 || 근거를 붙이면\n답 :: 그럴듯하게 지어낸다 || 문서를 인용한다\n확인 :: 사람이 일일이 || 출처를 보면 된다\n모를 때 :: 모른다고 안 한다 || 못 찾았다고 한다\n= 지어내지 못하게 막는 게 아니라, 지어낼 필요가 없게 만드는 쪽이 먹힌다\n```\n\n모델은 확률이 높은 문장을 만든다. 확률이 높은 것과 사실인 것은 다른 기준이라, 학습 데이터에 없는 것을 물으면 빈칸을 채우듯 그럴듯한 것을 만든다.\n\n막는 방법은 모델을 다그치는 게 아니라 근거를 주는 것이다. [[RAG]]로 실제 문서를 함께 넣으면 지어낼 자리가 줄어들고, 출처를 붙이게 하면 사람이 확인할 수 있다."},"recap":"**\"모른다고 못 하고 빈칸을 채워 버리는 그 버릇\"** 이라고 읽으면 된다. 구조에서 나오는 성질이라 없앨 수는 없고, 근거를 주고 출처를 붙이게 해서 줄이고 확인하는 것이 대응이다.","kid":"시험에서 모르는 문제가 나와도 빈칸으로 두긴 싫어서 그럴듯한 걸 적어 본 적 있지? 이것도 그래, 모른다고 말하는 칸이 없어서 있을 법한 답을 아주 자신 있게 지어내. 그러니까 알려 준 책 제목은 진짜 있는 책인지 꼭 찾아봐야 해.","check":[{"q":"모델이 거짓말을 하려는 것이 아닌데도 없는 논문을 만들어내는 이유는","at":"그림"},{"q":"조문 번호나 함수 이름이 특히 위험한 이유는","at":"주의사항"},{"q":"\"모르면 모른다고 답해\" 라는 지시만으로 부족한 이유는","at":"흔한 오해"}],"myths":[{"wrong":"환각은 고칠 수 있는 버그다","right":"다음 토큰을 확률로 고르는 구조에서 나오는 성질이라 완전히 없앨 수 없다. 줄이고 검증할 대상이다."},{"wrong":"\"모르면 모른다고 해\"라고 지시하면 해결된다","right":"도움은 되지만 모델은 자기가 모른다는 것을 모른다. 확률이 낮아도 가장 높은 후보를 고를 뿐이다."},{"wrong":"큰 모델을 쓰면 사라진다","right":"줄어들긴 하지만 없어지지 않는다. 오히려 더 그럴듯해져서 알아채기 어려워진다."}],"cases":[{"label":"없는 라이브러리 함수","note":"그럴듯한 이름의 함수를 쓴 코드를 준다. 실행해야 없다는 걸 안다."},{"label":"법 조항 인용","note":"조문 번호와 문구를 만들어낸다. 형식이 정확해서 더 위험하다."},{"label":"인용 출처","note":"제목, 저자, 연도가 모두 갖춰진 존재하지 않는 문헌을 만든다."}],"dia":{"shape":"흐름","title":"없는 논문 제목이 어떻게 만들어지나","rows":[{"who":"사용자","what":"\"이 주제 논문 알려줘\" 라고 묻는다"},{"who":"모델","what":"학습에서 본 제목의 생김새를 떠올린다"},{"who":"모델","what":"이 자리에 올 법한 단어를 하나씩 고른다"},{"who":"모델","what":"저자 이름과 연도도 그럴듯하게 잇는다"},{"who":"사용자","what":"형식이 완벽한, 존재하지 않는 논문을 받는다","back":true}],"sum":"모델에게는 \"지어내기\" 와 \"답하기\" 가 같은 동작이다"}},"ai--human-in-the-loop":{"definition":"AI 가 도구를 부를 수 있게 되면서 이 자리가 규격에 적히기 시작했다. MCP 규격은 도구 호출을 거절할 수 있는 사람이 고리 안에 있어야 한다고 적고, 에이전트 문서들은 되돌릴 수 없는 동작 앞에서 실행을 멈추라고 적는다.","name":"Human :: 사람\nin the Loop :: 그 고리 안에\n= 붙여 읽으면 \"사람이 그 고리 안에\". 밖에서 지켜보는 게 아니라, 도는 고리의 한 칸을 사람이 맡는다는 뜻이다","analogy":"카드 결제 직전에 뜨는 확인 창. 기계가 다 준비해 두고 마지막 한 번만 사람에게 묻는다.","example":"파일을 지우려는 명령 앞에서 \"정말 삭제할까요\" 가 한 번 뜨는 그 순간이다.","tryit":"쓰는 AI 도구가 파일을 고치기 전에 물어보는지 보라. 안 물어본다면 그 고리에는 사람 칸이 없는 것이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"손잡이는 도구마다 붙는 표시 하나다. OpenAI 의 에이전트 도구에는 승인 필요를 참으로 켜는 값이 있고, 그 도구 차례가 오면 실행 대신 중단 기록이 남는다. 돌려받는 것은 결과가 아니라 멈춘 항목 목록과 이어서 쓸 수 있는 상태값이다. 앱이 허락하거나 거절한 뒤 그 상태값으로 같은 실행을 이어 붙인다. 새 대화를 여는 것이 아니라 멈춘 자리에서 다시 가는 것이다.\n\n거는 자리를 고르는 기준도 문서에 적혀 있다. 취소·수정·셸 명령처럼 바깥에 흔적을 남기는 동작, 판단이 애매하거나 위험이 큰 동작이 그 대상이다. 나머지는 안 물어보고 지나간다.\n\n한 번에 여러 동작을 묶어 보내는 경우는 따로 조심한다. 묶음 하나가 한 차례 안에 여러 단계를 끝내 버리므로, 확인은 묶음 전체가 아니라 그 안의 동작 하나하나가 실행되기 전에 걸어야 한다. 앞이 실패하면 뒤를 돌리지 않는 것도 같은 이유다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **도구별 승인 표시** — 위험한 도구에만 표시를 달아 그 차례에 실행이 멈추고 사람에게 넘어간다.\n- **화면을 보고 움직이는 도구** — 결제나 약관 동의처럼 되돌릴 수 없는 동작 앞에서 사람 확인을 받는다.\n- **확신이 낮은 건만 사람에게** — 자동으로 처리하되 점수가 낮은 결과나 무작위 표본만 골라 사람 검토로 보낸다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **사람이 화면을 보고 있으면 개입한 것이다** — 보는 것과 막을 수 있는 것은 다르다. MCP 규격이 요구하는 것은 도구 호출을 거절할 수 있는 사람이다.\n- **전부 물어보게 하면 가장 안전하다** — 문서가 세우라고 적는 자리는 전부가 아니라 취소·수정·셸 명령·결제처럼 되돌릴 수 없는 동작이다. 나머지 동작까지 같은 창으로 물으면 어느 것이 위험한 걸음인지 구분이 사라진다.\n- **승인 창만 있으면 주입도 막힌다** — 사람이 보는 것은 하려는 동작이지 그 동작을 시킨 문장이 아니다. 권한을 줄이고 도구 결과를 검사하는 일은 따로 해야 한다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **묶음 안의 동작마다 확인해라.** 한 차례에 여러 단계가 끝나므로 묶음 앞에서 한 번 묻는 것으로는 늦는다.\n- **무엇을 하려는지 함께 보여라.** 도구 이름만 띄우면 누르는 사람이 판단할 근거가 없다. 넘길 값까지 보여 준다.\n- **거절도 하나의 결과다.** 막았을 때 실행이 어디서 멈추고 사용자에게 무엇이 보이는지를 미리 정해 둔다."}],"figure":"```도해\n흐름: 에이전트가 위험한 동작에 닿으면 무엇이 끼어드나\n에이전트 :: 다음에 부를 도구를 고른다\n관문 :: 승인이 필요하다고 표시된 도구인지 본다\n사람 :: 무엇을 하려는지 보고 허락하거나 막는다\n도구 :: 허락받은 것만 실제로 실행된다\n@ 다시 판단으로 :: 결과를 보고 다음 한 걸음을 정한다\n= 위험한 도구 앞에만 사람 칸이 하나 끼어들고, 승인을 받은 걸음만 실제로 나간다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 승인 칸이 없으면 무엇이 달라지나\n승인 없이 || 승인을 끼우면\n잘못된 판단 :: 그대로 실행된다 || 실행 전에 걸린다\n되돌리기 :: 사고 뒤에 수습 || 애초에 안 일어남\n숨은 지시 :: 도구까지 닿는다 || 사람 눈에 걸린다\n= 모델을 더 믿는 대신, 되돌릴 수 없는 걸음 앞에 사람을 한 칸 세운다\n```\n\n모델이 고른 다음 동작이 틀릴 확률은 0 이 되지 않는다. 문제는 그 확률이 아니라, 틀렸을 때 되돌릴 수 있느냐다. 파일 삭제·주문 취소·셸 명령·결제처럼 한 번 나가면 못 주워 담는 동작에서는 작은 확률도 그대로 사고가 된다.\n\n남이 써 둔 글에 숨은 지시가 섞여 들어오는 [[Prompt Injection]] 앞에서도 이 칸이 마지막 방어선이 된다. 화면을 보고 움직이는 도구에서는 주입이 의심되면 다음 동작 전에 사용자 확인을 받도록 모델을 돌려세우는 장치가 따로 붙어 있고, 사람 칸이 없는 쓰임에는 그 보호가 맞지 않는다고 문서가 적어 둔다."},"recap":"**\"되돌릴 수 없는 걸음 앞에 세워 둔 사람 칸\"** 이라고 읽으면 된다. 손대는 값은 어느 도구에 승인 표시를 다느냐 하나이고, 그 표시가 붙은 도구는 실행 대신 멈춤을 남긴 뒤 사람의 답을 받아 같은 실행을 이어 간다. 모든 걸음이 아니라 못 주워 담는 걸음만 고르는 것이 요령이다.","kid":"동생한테 심부름을 시킬 때 돈 쓰는 일만은 하기 전에 한 번 물어보라고 하지? 그러면 엉뚱한 걸 골랐어도 사기 전에 되돌릴 수 있어. 대신 하나하나 다 물어보게 하면 귀찮아서 그냥 하라고 하게 되니까, 되돌리기 어려운 것만 물어보게 두는 거야.","check":[{"q":"사람이 화면을 지켜보고만 있으면 왜 개입한 것이 아닌가","at":"흔한 오해"},{"q":"승인이 필요한 도구 차례가 오면 실행은 무엇을 돌려주나","at":"작동 원리"},{"q":"여러 동작을 한 번에 묶어 보낼 때 확인을 어디에 넣어야 하나","at":"주의사항"}],"myths":[{"wrong":"사람이 화면을 보고 있으면 개입한 것이다","right":"보는 것과 막을 수 있는 것은 다르다. MCP 규격이 요구하는 것은 도구 호출을 거절할 수 있는 사람이다."},{"wrong":"전부 물어보게 하면 가장 안전하다","right":"문서가 세우라고 적는 자리는 전부가 아니라 취소·수정·셸 명령·결제처럼 되돌릴 수 없는 동작이다. 나머지 동작까지 같은 창으로 물으면 어느 것이 위험한 걸음인지 구분이 사라진다."},{"wrong":"승인 창만 있으면 주입도 막힌다","right":"사람이 보는 것은 하려는 동작이지 그 동작을 시킨 문장이 아니다. 권한을 줄이고 도구 결과를 검사하는 일은 따로 해야 한다."}],"cases":[{"label":"도구별 승인 표시","note":"위험한 도구에만 표시를 달아 그 차례에 실행이 멈추고 사람에게 넘어간다."},{"label":"화면을 보고 움직이는 도구","note":"결제나 약관 동의처럼 되돌릴 수 없는 동작 앞에서 사람 확인을 받는다."},{"label":"확신이 낮은 건만 사람에게","note":"자동으로 처리하되 점수가 낮은 결과나 무작위 표본만 골라 사람 검토로 보낸다."}],"dia":{"shape":"흐름","title":"에이전트가 위험한 동작에 닿으면 무엇이 끼어드나","rows":[{"who":"에이전트","what":"다음에 부를 도구를 고른다"},{"who":"관문","what":"승인이 필요하다고 표시된 도구인지 본다"},{"who":"사람","what":"무엇을 하려는지 보고 허락하거나 막는다"},{"who":"도구","what":"허락받은 것만 실제로 실행된다"}],"sum":"위험한 도구 앞에만 사람 칸이 하나 끼어들고, 승인을 받은 걸음만 실제로 나간다","loop":{"who":"다시 판단으로","what":"결과를 보고 다음 한 걸음을 정한다"}}},"ai--inference-vs-training":{"definition":"Hugging Face 용어집은 추론을 \"학습이 끝난 뒤 새 데이터로 모델을 돌려 보는 일\" 로 적는다. 평소에 모델을 부르는 일은 전부 이쪽이고, 그 몇 초 동안 모델 안의 값은 한 자리도 바뀌지 않는다.","name":"Training :: 값을 고치는 때\nInference :: 고친 값을 쓰는 때\n= 붙여 읽으면 \"고치는 때와 쓰는 때\". 같은 모델의 서로 다른 때를 가리키는 말이다","analogy":"요리책. 분량을 고쳐 가며 책을 쓰는 일과, 다 쓴 책대로 한 그릇 만드는 일은 전혀 다른 일이다.","example":"챗봇에 질문을 넣고 답을 기다리는 그 몇 초가 전부 추론이다. 그동안 모델은 한 글자도 바뀌지 않는다.","tryit":"오늘 대화에서 알려 준 사실을 내일 새 대화에서 다시 물어보라. 모른다고 하면 그 대화가 모델을 고치지 않았다는 뜻이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"학습 때 메모리를 차지하는 것은 값 자체만이 아니다. Hugging Face 문서는 혼합 정밀도 학습에서 값 하나당 계산용·안정용 사본에 6바이트, 옵티마이저가 들고 있는 관성과 분산에 8바이트, 기울기에 4바이트가 든다고 적는다. 뒤의 둘은 값을 고치려고 두는 것이라 추론 때는 필요가 없다.\n\n시간의 규모도 다르다. 트랜스포머 원 논문은 기본 모델을 GPU 여덟 장짜리 기계 한 대에서 10만 걸음, 12시간 동안 학습했다고 적는다. 큰 쪽은 30만 걸음에 3.5일이 걸렸다. 여기까지가 값을 한 번 만드는 쪽에 드는 시간이고, 그 뒤로 그 값을 읽는 일은 이 시간과 무관하게 계속된다.\n\n이미 끝난 학습을 조금 잇는 길도 있다. OpenAI 문서를 보면 예시 묶음을 올려 학습 작업을 걸면 데이터 크기에 따라 몇 분에서 몇 시간이 걸리고, 끝나면 새 모델 이름이 하나 나온다. 그 뒤로는 다른 모델과 똑같이 부르면 된다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **새 사실을 알려야 할 때** — 값을 고치는 대신 물어볼 때 함께 넣는다. 넣은 만큼만 그 요청에서 읽히고, 다음 요청에는 다시 넣어야 한다.\n- **모델을 내 일에 맞출 때** — 예시를 모아 학습 작업을 걸면 몇 분에서 몇 시간 뒤 새 모델 이름이 나온다. 그때부터는 부르는 방법이 전과 같다.\n- **비용을 나눠 잡을 때** — 학습은 한 번에 크게 들고 끝나지만 추론은 호출 수만큼 계속 는다. 두 값을 한 칸에 적으면 어느 쪽을 줄여야 하는지가 안 보인다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **대화하면 모델이 나한테 맞게 학습된다** — 추론 중에는 값이 한 자리도 안 바뀐다. 다음 대화에서 기억하는 것처럼 보이면 지난 대화를 통째로 다시 넣어 준 것이다.\n- **파인튜닝이 프롬프트보다 항상 낫다** — 공식 문서도 둘을 같이 쓰는 것으로 적는다. 한 요청에 담기 어려울 만큼 예시가 많거나, 프롬프트를 줄여 값을 아끼려 할 때가 파인튜닝의 자리다.\n- **학습이 끝난 모델은 세상을 계속 알고 있다** — 값이 굳은 시점 뒤의 일은 모른다. 어제 생긴 사실은 부를 때 함께 넣어야 읽힌다."}],"figure":"```도해\n대조: 학습과 추론은 무엇이 다른가\n학습 |=| 추론\n모델의 값 :: 매 걸음 바뀐다 || 한 자리도 안 바뀐다\n맞힐 정답 :: 있어야 한다 || 필요 없다\n드는 때 :: 크게 한 번 || 작게 부를 때마다\n= 값을 만드는 때와 만든 값을 읽는 때. 같은 모델의 서로 다른 때다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 둘을 구별 안 하면 무슨 일이 생기나\n구별 안 하면 || 구별하면\n새 사실 넣기 :: 대화로 가르친다 || 매번 넣어 준다\n비용 잡기 :: 한 덩어리로 본다 || 따로 잡는다\n장비 잡기 :: 과하게 잡는다 || 쓰는 때에 맞춘다\n= 값이 바뀌는 때는 따로 있고, 평소에 부르는 것은 안 바뀌는 쪽이다\n```\n\n둘을 한 덩어리로 보면 두 가지가 어긋난다. 하나는 사실을 넣는 방법이다. 대화로 알려 주면 모델이 배운다고 믿고 있으면, 다음 대화에서 잊어버리는 일을 계속 겪게 된다. 값을 고치려면 학습 작업을 따로 걸어야 하고, 그러지 않을 사실은 부를 때마다 함께 넣어야 한다.\n\n다른 하나는 비용이다. 학습은 한 번에 크게 들고 끝나지만 추론은 부를 때마다 조금씩 계속 든다. 필요한 장비도 다르다 — 학습에만 있는 짐이 추론 때는 통째로 사라진다."},"recap":"**\"값을 고치는 때와 고친 값을 읽는 때\"** 라고 읽으면 된다. 평소에 부르는 것은 전부 뒤쪽이고, 그때 모델의 값은 한 자리도 안 바뀐다. 새 사실은 값을 고쳐서가 아니라 부를 때 함께 넣어서 들어간다.","kid":"요리책을 만들 때는 몇 번이고 만들어 보면서 분량을 고쳐 적지? 다 적고 나면 그 책은 더 안 바뀌고, 그다음부터는 적힌 대로 만들기만 해. 그러니까 만들면서 옆에서 아무리 새 이야기를 해도 책에는 한 글자도 안 적혀.","check":[{"q":"어제 알려 준 사실을 오늘 모델이 모르는 이유는 무엇인가","at":"흔한 오해"},{"q":"같은 모델인데 학습 때 메모리가 훨씬 많이 드는 까닭은","at":"작동 원리"},{"q":"회사 예시 수천 건을 모델에 반영하고 싶을 때 무엇을 하나","at":"실제 사례"}],"myths":[{"wrong":"대화하면 모델이 나한테 맞게 학습된다","right":"추론 중에는 값이 한 자리도 안 바뀐다. 다음 대화에서 기억하는 것처럼 보이면 지난 대화를 통째로 다시 넣어 준 것이다."},{"wrong":"파인튜닝이 프롬프트보다 항상 낫다","right":"공식 문서도 둘을 같이 쓰는 것으로 적는다. 한 요청에 담기 어려울 만큼 예시가 많거나, 프롬프트를 줄여 값을 아끼려 할 때가 파인튜닝의 자리다."},{"wrong":"학습이 끝난 모델은 세상을 계속 알고 있다","right":"값이 굳은 시점 뒤의 일은 모른다. 어제 생긴 사실은 부를 때 함께 넣어야 읽힌다."}],"cases":[{"label":"새 사실을 알려야 할 때","note":"값을 고치는 대신 물어볼 때 함께 넣는다. 넣은 만큼만 그 요청에서 읽히고, 다음 요청에는 다시 넣어야 한다."},{"label":"모델을 내 일에 맞출 때","note":"예시를 모아 학습 작업을 걸면 몇 분에서 몇 시간 뒤 새 모델 이름이 나온다. 그때부터는 부르는 방법이 전과 같다."},{"label":"비용을 나눠 잡을 때","note":"학습은 한 번에 크게 들고 끝나지만 추론은 호출 수만큼 계속 는다. 두 값을 한 칸에 적으면 어느 쪽을 줄여야 하는지가 안 보인다."}],"dia":{"shape":"대조","title":"학습과 추론은 무엇이 다른가","rows":[{"who":"","what":"학습 || 추론","left":"학습","right":"추론","even":true},{"who":"모델의 값","what":"매 걸음 바뀐다 || 한 자리도 안 바뀐다","left":"매 걸음 바뀐다","right":"한 자리도 안 바뀐다"},{"who":"맞힐 정답","what":"있어야 한다 || 필요 없다","left":"있어야 한다","right":"필요 없다"},{"who":"드는 때","what":"크게 한 번 || 작게 부를 때마다","left":"크게 한 번","right":"작게 부를 때마다"}],"sum":"값을 만드는 때와 만든 값을 읽는 때. 같은 모델의 서로 다른 때다"}},"ai--intent":{"definition":"같은 요청도 사람마다 다르게 말한다. 그 표현들을 미리 정해둔 몇 개의 갈래로 묶어서 어디로 보낼지 정한다.","name":"Intent :: 하려는 속뜻\nClassification :: 갈래로 나눔\n= 붙여 읽으면 \"속뜻을 갈래로 나누기\". 한 말 그대로가 아니라 원하는 바를 본다","analogy":"전화 자동 안내. 무슨 말을 하든 결국 인사팀과 재무팀 중 한 곳으로 연결된다.","example":"검색창에 날씨라고만 쳤는데 결과 목록 대신 오늘 기온 카드가 먼저 뜨는 그 판단이다.","tryit":"검색창에 \"날씨\" 라고만 쳐 보라. 목록보다 먼저 오늘 기온이 뜬다. 무엇을 원하는지 먼저 찍은 것이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"분류기는 갈래를 고르면서 얼마나 확실한지도 함께 내놓는다. 이 점수에 기준선을 두고 넘으면 바로 보내고, 못 넘으면 사용자에게 되묻는다. 애매한 것을 억지로 밀어 넣는 것보다 한 번 확인하는 편이 낫기 때문이다.\n\n앞선 대화도 함께 본다. \"얼마나 남았어?\"만 보면 연차인지 급여일인지 계약 기간인지 알 수 없지만, 바로 앞에서 연차 이야기가 오갔다면 정해진다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교","body":"| 방법 | 잘하는 것 | 못하는 것 |\n|---|---|---|\n| 규칙 기반 | 즉시 답하고 결과가 뻔하다 | 표현이 조금만 달라도 못 잡는다 |\n| 학습 모델 기반 | 빠르고 대량 처리에 싸다 | 학습 데이터를 모아야 한다 |\n| LLM 기반 | 맥락과 뉘앙스를 읽는다 | 호출 비용과 지연이 붙는다 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **고객 문의 분류** — 들어온 문의를 갈래로 나눠 담당 창구로 바로 보낸다.\n- **사내 챗봇** — 신청 방법, 규정 확인, 급여 같은 갈래로 나눠 각각 다른 자료를 찾게 한다.\n- **애매한 질문 되묻기** — 점수가 기준에 못 미치면 답을 지어내지 않고 선택지를 보여준다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **의도를 알아냈으면 답도 나온 것이다** — 어디로 보낼지가 정해졌을 뿐이다. 실제 답은 그 갈래를 맡은 쪽이 따로 만든다.\n- **갈래를 많이 만들수록 정확해진다** — 갈래끼리 겹치기 시작하면 분류기가 헷갈린다. 서로 안 겹치게 적게 두는 편이 정확도가 높다.\n- **한 문장만 보면 된다** — 앞선 대화를 안 보면 \"얼마나 남았어?\" 같은 말은 무엇을 묻는지 정할 수 없다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **기준선을 정해둔다.** 점수가 낮은데도 억지로 보내면 엉뚱한 담당이 자신 있게 틀린 답을 낸다.\n- **어디에도 안 맞는 갈래를 하나 둔다.** 모든 말을 정해진 갈래에 밀어 넣으면 처리할 수 없는 요청이 조용히 잘못 처리된다."}],"figure":"```도해\n흐름: \"주소 변경하고 싶어\" 는 어디로 가나\n사용자 :: 자기 말로 요청을 적는다\n분류기 :: 미리 정해둔 갈래에 대응시킨다\n분류기 :: 갈래마다 얼마나 확실한지 점수를 낸다\n판단 :: 점수가 기준을 넘으면 그 갈래로 정한다\n< 담당 :: 정해진 쪽이 답을 만들어 돌려준다\n= 무엇을 원하는지 먼저 정해야 어디로 보낼지가 나온다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 들어온 말을 갈래로 나누지 않으면 어떻게 되나\n분류 없이 || Intent 분류로\n처리 방식 :: 사람이 나눈다 || 즉시 나뉜다\n잘못 보냄 :: 전부 헛돈다 || 한 곳만 실행\n같은 뜻 다른 말 :: 따로 처리 || 한 갈래로\n= 무엇을 원하는지 정하는 자리가 있어야 뒤가 단순해진다\n```\n\n문의가 하루에 수백 건 들어오면 사람이 하나씩 읽어 어느 쪽으로 보낼지 정하는 방식은 느리고 자주 틀린다. 자동으로 넘긴다 해도 갈래를 안 정하면 담당을 전부 돌려보고 그중 맞는 답을 고르게 되어, 시간과 비용이 갈래 수만큼 늘어난다.\n\nIntent 분류는 맨 앞에서 한 번만 판단한다. \"주소 변경하고 싶어\"와 \"주소 어디서 바꿔요\"를 같은 갈래로 묶어 한 곳으로 보내면, 뒤에 있는 담당은 자기 일만 하면 된다."},"recap":"**\"말 뒤에 숨은 용건을 갈래로 찍는 그 첫 판단\"** 이라고 읽으면 된다. 확실한 정도를 함께 내놓기 때문에, 애매하면 되묻고 확실하면 바로 넘길 수 있다.","kid":"전화를 걸면 \"안내는 일 번, 예약은 이 번\" 하고 갈래를 물어보지? 뭐라고 말하든 결국 그 몇 개 창구 중 한 군데로 이어져. \"주소 바꾸고 싶어\" 라고 하든 \"주소 어디서 바꿔요\" 라고 하든 같은 창구로 가는 거야.","check":[{"q":"\"얼마나 남았어?\" 한 문장만으로 갈래를 정할 수 없는 이유는","at":"작동 원리"},{"q":"분류 점수가 기준에 못 미치는데 그대로 보내면 무슨 일이 생기나","at":"주의사항"},{"q":"갈래를 늘렸는데 오히려 분류가 부정확해졌다면 무엇을 의심해야 하나","at":"흔한 오해"}],"myths":[{"wrong":"의도를 알아냈으면 답도 나온 것이다","right":"어디로 보낼지가 정해졌을 뿐이다. 실제 답은 그 갈래를 맡은 쪽이 따로 만든다."},{"wrong":"갈래를 많이 만들수록 정확해진다","right":"갈래끼리 겹치기 시작하면 분류기가 헷갈린다. 서로 안 겹치게 적게 두는 편이 정확도가 높다."},{"wrong":"한 문장만 보면 된다","right":"앞선 대화를 안 보면 \"얼마나 남았어?\" 같은 말은 무엇을 묻는지 정할 수 없다."}],"cases":[{"label":"고객 문의 분류","note":"들어온 문의를 갈래로 나눠 담당 창구로 바로 보낸다."},{"label":"사내 챗봇","note":"신청 방법, 규정 확인, 급여 같은 갈래로 나눠 각각 다른 자료를 찾게 한다."},{"label":"애매한 질문 되묻기","note":"점수가 기준에 못 미치면 답을 지어내지 않고 선택지를 보여준다."}],"dia":{"shape":"흐름","title":"\"주소 변경하고 싶어\" 는 어디로 가나","rows":[{"who":"사용자","what":"자기 말로 요청을 적는다"},{"who":"분류기","what":"미리 정해둔 갈래에 대응시킨다"},{"who":"분류기","what":"갈래마다 얼마나 확실한지 점수를 낸다"},{"who":"판단","what":"점수가 기준을 넘으면 그 갈래로 정한다"},{"who":"담당","what":"정해진 쪽이 답을 만들어 돌려준다","back":true}],"sum":"무엇을 원하는지 먼저 정해야 어디로 보낼지가 나온다"}},"ai--jailbreak":{"definition":"2023년 논문 하나가 왜 통하는지를 두 가지로 정리했다. 하나는 목표 다툼 — 도우려는 힘과 막으려는 힘이 한 요청 안에서 부딪히는 자리다. 다른 하나는 어긋난 일반화 — 모델은 할 줄 아는데 안전 학습이 거기까지는 미치지 못한 자리다. 공격은 둘 중 하나를 골라 판다.","name":"Jail :: 갇힌 곳\nBreak :: 부수고 나옴\n= 붙여 읽으면 \"갇힌 데서 부수고 나오기\". 폰 잠금을 푸는 말에서 왔고, 여기서는 모델에 걸어둔 제한을 푼다는 뜻이다","analogy":"경비원에게 \"지금은 훈련 상황입니다\" 라고 말해 문을 열게 하는 것과 같다.","example":"챗봇이 \"도와드릴 수 없습니다\" 로 답한 뒤 말을 바꿔 다시 물었더니 답이 나온 적, 그 경계가 여기다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"목표 다툼은 모델이 두 가지를 동시에 잘하도록 배운 데서 온다. 잘 돕는 것과 위험한 것을 막는 것이 한 요청 안에서 부딪히면 어느 쪽이 이길지가 요청의 모양에 달린다. 역할극으로 감싸거나 \"거절하지 말고\" 같은 조건을 붙이는 수법이 이 다툼을 일부러 만든다.\n\n어긋난 일반화는 방향이 다르다. 모델은 어떤 표기나 형식을 다룰 줄 아는데, 안전 학습은 평범한 문장 위주로만 되어 있어 그 표기까지 따라가지 못한다. 그러면 능력은 그대로 살아 있고 경계만 비켜 간다.\n\n막는 쪽에서 손대는 값은 셋이다. 본 대화에 닿기 전에 가벼운 모델로 입력을 한 번 분류해 걸러낼지, 시스템 프롬프트에 지켜야 할 선과 거절 문구를 함께 적어 둘지, 같은 거절을 반복해서 부르는 계정에 제한을 걸지. 셋을 겹쳐 쌓을수록 통과율이 내려간다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **역할극 요구** — 제한이 없는 다른 인격으로 답하라고 감싸 거절 규칙과 도우려는 성향을 맞붙인다.\n- **낯선 표기로 감싸기** — 안전 학습이 닿지 않은 표기로 바꿔 넣어 경계만 비켜 간다.\n- **반복 시도 계정** — 같은 종류의 거절을 여러 번 부르는 사용자에게 응답을 조정하거나 이용을 제한한다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **탈옥이랑 프롬프트 주입은 같은 말이다** — 노리는 사람이 다르다. 탈옥은 앱을 쓰는 사용자 자신이 공격자이고, 간접 주입은 사용자가 멀쩡한데 모델이 대신 읽는 남의 글이 공격자다.\n- **모델이 커지면 알아서 막힌다** — 논문은 그 반대로 적는다. 규모만으로는 두 실패 모드가 사라지지 않고, 안전 장치가 모델만큼 정교해져야 한다는 쪽이다.\n- **한 번 뚫렸으면 그 모델은 못 쓴다** — 뚫리는 자리는 요청의 모양에 달렸다. 앞뒤에 검사를 세우고 반복 시도를 제한하는 쪽으로 좁히는 것이 실제로 하는 일이다."}],"figure":"```도해\n흐름: 거절하던 모델이 어떻게 답을 내놓게 되나\n사용자 :: 곧이곧대로 물어 거절을 받는다\n공격자 :: 역할극이나 낯선 표기로 요청을 감싼다\n모델 :: 도우려는 힘과 막으려는 힘이 다툰다\n안전 학습 :: 그 표기까지는 배우지 못했다\n< 공격자 :: 거절했어야 할 답이 그대로 나온다\n= 안전이 닿지 않은 자리를 골라, 거절하도록 배운 답을 말을 바꿔 꺼내는 것이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"이 항목은 해결하는 문제가 아니라 **막아야 할 공격**이다.\n\n```도해\n대조: 안전 학습에만 기대면 무엇이 남나\n학습에만 기대면 || 밖에 검사를 더 세우면\n낯선 표기 :: 배운 적이 없다 || 뜻을 풀어 본다\n도우려는 힘 :: 거절과 다툰다 || 다투기 전에 걸린다\n모델이 커지면 :: 능력이 먼저 큰다 || 검사도 같이 큰다\n= 실력만 키우면 뚫린 자리도 같이 커진다. 안전은 실력만큼 정교해야 한다\n```\n\n논문이 시험한 것은 그때의 앞선 모델들이었고, 붉은 팀 점검을 두껍게 거친 뒤에도 구멍이 남아 있었다. 두 실패 모드를 겨냥해 새로 만든 공격은 그 모델들의 점검용 위험 요청 묶음에서 한 건도 빠짐없이 통했다.\n\n그래서 결론이 \"더 크게 키우면 해결된다\" 가 아니다. 능력과 안전이 같은 수준으로 정교해져야 한다는 쪽이고, 규모만으로는 두 실패 모드가 사라지지 않는다고 못 박는다. 모델 밖에 검사를 따로 세우는 이유가 여기 있다."},"recap":"**\"거절하도록 배운 답을 말을 바꿔 꺼내는 일\"** 이라고 읽으면 된다. 통하는 이유는 둘 중 하나다. 도우려는 힘과 막으려는 힘이 다투는 자리를 골랐거나, 안전 학습이 미치지 못한 표기를 골랐거나다.","kid":"문 앞을 지키는 아저씨한테 그냥 들여보내 달라고 하면 안 된다고 하지? 그런데 \"지금은 연습이니까 괜찮아요\" 하고 말을 바꾸면 헷갈려서 열어 줄 때가 있어. 친절하게 도와주고 싶은 마음이랑 막아야 한다는 규칙이 서로 부딪히는 그 순간이야.","check":[{"q":"곧이곧대로 물으면 거절하던 모델이 역할극으로 감싸면 답하는 이유는 무엇인가","at":"작동 원리"},{"q":"모델을 더 크게 키워도 이 문제가 저절로 사라지지 않는다고 보는 근거는 무엇인가","at":"흔한 오해"},{"q":"안전 학습을 두껍게 해 두고도 모델 밖에 검사를 따로 세우는 이유는 무엇인가","at":"해결하는 문제"}],"myths":[{"wrong":"탈옥이랑 프롬프트 주입은 같은 말이다","right":"노리는 사람이 다르다. 탈옥은 앱을 쓰는 사용자 자신이 공격자이고, 간접 주입은 사용자가 멀쩡한데 모델이 대신 읽는 남의 글이 공격자다."},{"wrong":"모델이 커지면 알아서 막힌다","right":"논문은 그 반대로 적는다. 규모만으로는 두 실패 모드가 사라지지 않고, 안전 장치가 모델만큼 정교해져야 한다는 쪽이다."},{"wrong":"한 번 뚫렸으면 그 모델은 못 쓴다","right":"뚫리는 자리는 요청의 모양에 달렸다. 앞뒤에 검사를 세우고 반복 시도를 제한하는 쪽으로 좁히는 것이 실제로 하는 일이다."}],"cases":[{"label":"역할극 요구","note":"제한이 없는 다른 인격으로 답하라고 감싸 거절 규칙과 도우려는 성향을 맞붙인다."},{"label":"낯선 표기로 감싸기","note":"안전 학습이 닿지 않은 표기로 바꿔 넣어 경계만 비켜 간다."},{"label":"반복 시도 계정","note":"같은 종류의 거절을 여러 번 부르는 사용자에게 응답을 조정하거나 이용을 제한한다."}],"dia":{"shape":"흐름","title":"거절하던 모델이 어떻게 답을 내놓게 되나","rows":[{"who":"사용자","what":"곧이곧대로 물어 거절을 받는다"},{"who":"공격자","what":"역할극이나 낯선 표기로 요청을 감싼다"},{"who":"모델","what":"도우려는 힘과 막으려는 힘이 다툰다"},{"who":"안전 학습","what":"그 표기까지는 배우지 못했다"},{"who":"공격자","what":"거절했어야 할 답이 그대로 나온다","back":true}],"sum":"안전이 닿지 않은 자리를 골라, 거절하도록 배운 답을 말을 바꿔 꺼내는 것이다"}},"ai--llm":{"definition":"엄청난 양의 글로 학습해서, 주어진 문장 뒤에 무엇이 올 법한지를 안다. 그 예측을 한 단어씩 이어 붙인 것이 우리가 보는 답변이다.","name":"Large :: 어마어마하게 큰\nLanguage :: 말과 글\nModel :: 본떠 만든 짜임\n= 붙여 읽으면 \"말을 본떠 만든 아주 큰 짜임\". 큰 것은 읽은 글의 양과 값의 개수다","analogy":"문장 완성 게임을 수천만 번 해본 사람. 사실을 외운 게 아니라 \"이런 말 뒤에는 보통 이런 말이 온다\"를 몸으로 익힌 상태다. 그래서 그럴듯한 말은 아는 것과 상관없이 잘 만든다.","example":"AI 챗봇의 답이 통째로 뜨지 않고 한 낱말씩 밀려 나오듯 찍히는 것을 본 적이 있다.","tryit":"챗봇에 긴 답을 시켜 놓고 화면을 보라. 한 낱말씩 밀려 나오는 그것이 조각을 하나씩 고르고 있는 모습이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"핵심은 **문맥 창**이다. 모델이 한 번에 볼 수 있는 토큰 수가 정해져 있고, 그 밖의 내용은 존재하지 않는 것과 같다.\n\n같은 질문에 매번 다른 답이 나오는 것도 이 구조 때문이다. 가장 확률 높은 토큰만 고르면 답이 딱딱해져서, 보통은 상위 후보 중에서 무작위로 하나를 고른다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **문서 요약** — 긴 글을 넣고 짧게 다시 쓰게 한다. 원문이 문맥 창에 들어가야 한다.\n- **분류** — 문의 내용을 보고 어느 부서로 보낼지 정한다. 규칙으로 짜기 어려운 일이 잘 맞는다.\n- **코드 작성** — 자연어 설명을 코드로 옮긴다. 코드도 결국 토큰의 나열이라 같은 방식으로 예측된다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **LLM이 답을 검색해서 가져온다** — 검색하지 않는다. 학습한 통계로 그럴듯한 말을 만들어낼 뿐이라, 없는 논문 제목도 자신 있게 만들어낸다.\n- **모델이 대화를 기억한다** — 기억하지 않는다. 매번 대화 기록 전체를 다시 넣어주기 때문에 기억하는 것처럼 보인다. 창을 넘으면 앞이 사라진다.\n- **모델이 계산을 한다** — 계산하지 않고 계산 결과처럼 보이는 토큰을 예측한다. 자릿수가 큰 곱셈에서 틀리는 이유다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **틀린 답을 자신 있게 말한다.** 확률이 높은 문장은 맞는 문장과 다르다. 사실 확인이 필요한 곳에는 [[RAG]] 같은 근거 제공 장치를 붙인다.\n- **문맥 창은 비용이다.** 넣는 토큰만큼 돈과 시간이 든다. 대화 기록을 통째로 넣는 습관은 비싸진다."}],"figure":"```도해\n흐름: 질문을 넣으면 답이 어떻게 만들어지나\n사용자 :: \"한국의 수도는\" 이라고 입력한다\n토크나이저 :: 글자를 토큰이라는 조각으로 쪼갠다\n모델 :: 다음 토큰 후보마다 확률을 매긴다\n모델 :: \"서울\" 이 가장 높다. 하나 고른다\n< 사용자 :: 끝 신호가 나오면 이어 붙인 문장을 받는다\n@ 다시 예측으로 :: 고른 토큰을 뒤에 붙이고 한 조각 더\n= 문장 전체를 한 번에 만드는 게 아니라 한 조각씩 이어 붙인다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 규칙을 사람이 짜던 방식과 무엇이 다른가\n규칙 기반 |=| LLM\n새 표현 :: 규칙을 추가해야 || 대체로 처리된다\n분야 확장 :: 처음부터 다시 || 같은 모델로\n답의 근거 :: 규칙을 짚을 수 있다 || 짚기 어렵다\n= 사람이 규칙을 다 못 적는 문제를 풀었고, 대신 왜 그렇게 답했는지를 잃었다\n```\n\n말은 규칙으로 다 적을 수 없다. 예외가 너무 많고, 새 표현이 계속 생기고, 문맥에 따라 뜻이 달라진다. 규칙을 짜서 자연어를 다루려던 시도가 오래 막혀 있던 이유다.\n\nLLM은 규칙을 사람이 적는 대신 데이터에서 통계를 뽑는 방식으로 이 문제를 우회했다. 대신 답의 근거를 짚을 수 없게 됐고, 그래서 [[Hallucination]] 같은 문제가 따라온다."},"compose":{"label":"무엇으로 되어 있나","head":"🧱 구성","body":"```도해\n층: 답변 하나가 어떤 재료로 만들어지나\n시스템 지시 :: 어떤 역할로 답하라는 사전 지시\n대화 기록 :: 이번 대화에서 오간 말\n이번 질문 :: 방금 넣은 내용\n문맥 창 밖 :: 여기 있던 것은 모델에게 없는 것과 같다\n= 대화가 길어지면 앞부분이 창 밖으로 밀려나면서 \"기억\"이 사라진다\n```"},"recap":"**\"다음에 올 말을 확률로 찍는 그 짜임\"** 이라고 읽으면 된다. 규칙을 사람이 적지 않아도 되는 대신 근거를 짚을 수 없고, 그래서 확신에 찬 오답이 나온다.","kid":"\"토끼가 깡충깡충 ○○\" 처럼 뒷말 맞히기를 수천만 번 해 본 애가 있다고 해 봐. 뭘 물으면 외워 둔 답을 꺼내는 게 아니라, 그 말 뒤에 보통 뭐가 오는지를 떠올려서 한 낱말씩 이어 붙여. 그래서 말은 아주 매끄러운데 내용은 틀릴 수도 있어.","check":[{"q":"대화가 길어지면 앞에서 한 말을 잊는 것처럼 보이는 이유는","at":"구성"},{"q":"없는 논문 제목을 만들어내는 일이 왜 버그가 아니라 구조상 당연한가","at":"흔한 오해"},{"q":"답이 길어질수록 다 나오는 데 시간이 더 걸리는 이유는","at":"그림"}],"myths":[{"wrong":"LLM이 답을 검색해서 가져온다","right":"검색하지 않는다. 학습한 통계로 그럴듯한 말을 만들어낼 뿐이라, 없는 논문 제목도 자신 있게 만들어낸다."},{"wrong":"모델이 대화를 기억한다","right":"기억하지 않는다. 매번 대화 기록 전체를 다시 넣어주기 때문에 기억하는 것처럼 보인다. 창을 넘으면 앞이 사라진다."},{"wrong":"모델이 계산을 한다","right":"계산하지 않고 계산 결과처럼 보이는 토큰을 예측한다. 자릿수가 큰 곱셈에서 틀리는 이유다."}],"cases":[{"label":"문서 요약","note":"긴 글을 넣고 짧게 다시 쓰게 한다. 원문이 문맥 창에 들어가야 한다."},{"label":"분류","note":"문의 내용을 보고 어느 부서로 보낼지 정한다. 규칙으로 짜기 어려운 일이 잘 맞는다."},{"label":"코드 작성","note":"자연어 설명을 코드로 옮긴다. 코드도 결국 토큰의 나열이라 같은 방식으로 예측된다."}],"dia":{"shape":"흐름","title":"질문을 넣으면 답이 어떻게 만들어지나","rows":[{"who":"사용자","what":"\"한국의 수도는\" 이라고 입력한다"},{"who":"토크나이저","what":"글자를 토큰이라는 조각으로 쪼갠다"},{"who":"모델","what":"다음 토큰 후보마다 확률을 매긴다"},{"who":"모델","what":"\"서울\" 이 가장 높다. 하나 고른다"},{"who":"사용자","what":"끝 신호가 나오면 이어 붙인 문장을 받는다","back":true}],"sum":"문장 전체를 한 번에 만드는 게 아니라 한 조각씩 이어 붙인다","loop":{"who":"다시 예측으로","what":"고른 토큰을 뒤에 붙이고 한 조각 더"}}},"ai--lora":{"definition":"가중치는 학습으로 정해진 커다란 숫자 표다. 그 표를 통째로 다시 학습시키면 표 크기만큼의 값을 매번 새로 저장해야 한다. LoRA 는 본체를 그대로 얼려 두고 옆에 얇은 표 두 장을 새로 세워, 그 두 장만 학습한다. 2021년 논문이 제안했다.","name":"Low :: 낮은\nRank :: 담긴 방향의 수\nAdaptation :: 맞춰 고치기\n= 붙여 읽으면 \"적은 방향만으로 맞춰 고치기\". 큰 표 대신 얇은 표 두 장을 배운다","analogy":"두꺼운 책에 붙이는 붙임쪽지. 본문은 한 글자도 안 고치고, 쪽지를 붙였다 뗐다 하면서 읽는 법만 바꾼다.","example":"같은 모델을 부서마다 다르게 길들이려는데 통째로 복사본을 만들 수는 없어 막히던 자리다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"두 장의 두께가 r 이다. 넓은 입력을 r 줄로 좁히는 표 A, 그 r 줄을 도로 원래 폭으로 넓히는 표 B. 학습되는 값의 수는 이 r 에 비례한다.\n\n**r 을 올리면** 두 장이 두꺼워져 담을 수 있는 변화가 늘고, 저장할 파일과 학습할 값도 함께 는다. 내리면 반대다. 원 논문은 r 을 1, 2, 4, 8, 64 로 바꿔 가며 재 보고, 어텐션(문장에서 어디를 볼지 정하는 부분)의 질의와 값 두 자리에 함께 붙이면 그 데이터셋들에서는 r 이 1이어도 충분했다고 적는다. 대신 질의 한 곳만 고칠 때는 더 큰 r 이 필요했다. **두께보다 어디에 붙였는지가 먼저다.**\n\n두 번째 손잡이는 배율이다. 두 장의 결과를 원래 값에 얹을 때 alpha 를 r 로 나눈 값을 곱한다. r 을 바꿔도 얹히는 크기가 크게 흔들리지 않게 하는 장치다.\n\n다 배우면 두 장을 곱해 본체에 그냥 더할 수 있다. 합쳐 두면 평범한 모델 한 벌이 되어 답하는 속도가 그대로다. 합치지 않고 두면 본체 하나에 조각만 갈아 끼울 수 있다 — 더했던 것을 빼고 다른 것을 더하면 다른 일을 하는 모델이 된다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **일마다 조각만 따로** — 본체 한 벌을 두고 조각을 갈아 끼워 여러 벌처럼 쓴다.\n- **원래대로 되돌리기** — 조각을 떼면 본체는 한 숫자도 안 바뀐 채로 남아 있다.\n- **작은 장비에서 학습하기** — 본체를 4비트로 담아 얼려 두고 조각만 학습하면 큰 장비 없이도 미세 조정이 된다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **조각을 덧붙였으니 답이 그만큼 느려진다** — 다 배운 뒤 두 장을 본체에 더해 하나로 합칠 수 있다. 논문은 추가로 생기는 지연이 없다고 적는다.\n- **r 을 키울수록 잘 배운다** — 논문이 잰 범위에서는 붙인 자리가 맞으면 r 이 1이어도 됐고, 한 자리에만 붙였을 때는 더 큰 r 이 필요했다. 두께부터 올리는 것은 순서가 틀렸다.\n- **바꿀 게 있으면 조각을 붙이면 된다** — 조각이 옮기는 것은 답하는 방식이다. 어제 바뀐 사실을 알게 하는 일은 학습이 아니라 그때그때 찾아 넣는 쪽이 맞다."}],"figure":"```도해\n흐름: 학습할 때 무엇이 움직이고 무엇이 얼어 있나\n원래 표 :: 통째로 얼린다. 한 숫자도 안 바꾼다\n표 A :: 넓은 입력을 r 줄로 좁힌다\n표 B :: r 줄을 도로 원래 폭으로 넓힌다\n더해 쓰기 :: 원래 값 위에 두 장의 결과를 얹는다\n학습 :: 고쳐지는 값은 두 장 안에만 있다\n= 새로 배우는 것은 얇은 두 장뿐이고, 그 두께가 r 이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 통째로 다시 학습하면 무엇이 걸리나\n전부 학습 || 두 장만 학습\n학습되는 값 :: 전부 || 1만분의 1\n학습에 드는 자리 :: 세 배가 든다 || 3분의 1\n일이 하나 늘면 :: 통째로 복사 || 두 장만 더\n= 본체를 안 건드리니 일마다 붙였다 떼는 조각만 남는다\n```\n\n모델을 통째로 다시 학습시키면 그 크기만큼의 값이 전부 움직인다. 학습하는 동안 자리가 그만큼 필요하고, 다 끝나면 원본과 같은 덩치의 파일이 하나 더 생긴다. 일이 열 가지면 그 덩치가 열 벌이다.\n\nLoRA 는 움직이는 값을 얇은 두 장 안에 가둔다. 논문은 자기들이 잰 가장 큰 설정에서 학습되는 값이 1만분의 1로, 학습에 필요한 자리가 3분의 1로 줄었다고 적는다. r 을 4로 두고 두 자리에만 붙인 경우에는 저장할 파일이 수백 기가에서 수십 메가로 내려갔다. 본체는 한 벌 그대로 두고 일마다 조각만 따로 쌓으면 된다."},"recap":"**\"본체는 얼리고 얇은 두 장만 배우는 그 조각 학습\"** 이라고 읽으면 된다. 학습되는 값이 확 줄어 저장할 파일이 작아지고, 다 배운 뒤 본체에 더해 합치면 답하는 속도는 그대로다. 손으로 정하는 값은 두께 r 과 붙일 자리 둘인데 자리가 먼저다.","kid":"두꺼운 책에 직접 낙서하면 다음 사람이 못 읽지? 그래서 책은 그대로 두고 붙임쪽지만 붙여서 \"여기는 이렇게 읽어\" 라고 적어 두는 거야. 쪽지는 떼면 그만이라 사람마다 다른 쪽지를 붙였다 뗐다 할 수 있어.","check":[{"q":"두께 r 을 1로 낮췄는데도 잘 되는 경우가 있는 이유는 무엇인가","at":"작동 원리"},{"q":"조각을 덧붙였는데도 답하는 속도가 그대로인 이유는 무엇인가","at":"흔한 오해"},{"q":"부서가 열 곳이면 무엇을 열 벌 만들고 무엇을 한 벌만 두나","at":"실제 사례"}],"myths":[{"wrong":"조각을 덧붙였으니 답이 그만큼 느려진다","right":"다 배운 뒤 두 장을 본체에 더해 하나로 합칠 수 있다. 논문은 추가로 생기는 지연이 없다고 적는다."},{"wrong":"r 을 키울수록 잘 배운다","right":"논문이 잰 범위에서는 붙인 자리가 맞으면 r 이 1이어도 됐고, 한 자리에만 붙였을 때는 더 큰 r 이 필요했다. 두께부터 올리는 것은 순서가 틀렸다."},{"wrong":"바꿀 게 있으면 조각을 붙이면 된다","right":"조각이 옮기는 것은 답하는 방식이다. 어제 바뀐 사실을 알게 하는 일은 학습이 아니라 그때그때 찾아 넣는 쪽이 맞다."}],"cases":[{"label":"일마다 조각만 따로","note":"본체 한 벌을 두고 조각을 갈아 끼워 여러 벌처럼 쓴다."},{"label":"원래대로 되돌리기","note":"조각을 떼면 본체는 한 숫자도 안 바뀐 채로 남아 있다."},{"label":"작은 장비에서 학습하기","note":"본체를 4비트로 담아 얼려 두고 조각만 학습하면 큰 장비 없이도 미세 조정이 된다."}],"dia":{"shape":"흐름","title":"학습할 때 무엇이 움직이고 무엇이 얼어 있나","rows":[{"who":"원래 표","what":"통째로 얼린다. 한 숫자도 안 바꾼다"},{"who":"표 A","what":"넓은 입력을 r 줄로 좁힌다"},{"who":"표 B","what":"r 줄을 도로 원래 폭으로 넓힌다"},{"who":"더해 쓰기","what":"원래 값 위에 두 장의 결과를 얹는다"},{"who":"학습","what":"고쳐지는 값은 두 장 안에만 있다"}],"sum":"새로 배우는 것은 얇은 두 장뿐이고, 그 두께가 r 이다"}},"ai--multimodal":{"definition":"Hugging Face 용어집은 이 말을 \"글에 다른 종류의 입력(예: 이미지)을 합친 일\" 로 적는다. 받는 갈래가 늘었다는 뜻이지 모델이 둘로 나뉜다는 뜻이 아니다 — 그림도 조각으로 잘려 글 조각과 같은 줄에 이어 붙는다.","name":"Multi :: 여럿\nModal :: 들어오는 갈래\n= 붙여 읽으면 \"여러 갈래\". 글만 받던 입구에 갈래가 더 붙은 것이다","analogy":"숙제 제출함. 글로 쓴 것만 받던 자리에 사진과 녹음도 같이 받게 넓힌 것이다.","example":"사진을 찍어 올리고 \"이게 무슨 뜻이야\" 라고 물어본 적이 있다면 그 순간이 이것이다.","tryit":"표나 손글씨가 든 사진을 올려 그 안의 글자를 그대로 옮겨 달라고 해 보라. 글씨가 작으면 틀린다는 것도 같이 보인다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"토큰 수는 픽셀이 아니라 네모 조각의 개수로 정해진다. Anthropic 문서는 이미지를 28×28 픽셀 블록으로 보고, 한 장의 비용을 `⌈가로/28⌉ × ⌈세로/28⌉` 로 적는다. 1000×1000 짜리 한 장이면 36×36, 즉 1296 토큰이다. 가로세로를 각각 두 배로 키우면 네모 수는 네 배가 된다.\n\n무한정 오르지는 않는다. 모델마다 긴 변과 시각 토큰 수에 상한이 있고, 그보다 큰 그림은 비율을 지킨 채 줄여서 넣는다. 그래서 상한을 넘긴 뒤로는 크게 올려도 토큰이 더 늘지 않고, 대신 줄어든 만큼 작은 글씨는 더 안 보인다.\n\n손잡이는 두 군데다. 하나는 보내기 전에 내가 줄이는 것이고, 다른 하나는 정밀도를 고르는 값이다. OpenAI 문서의 `detail` 은 `low`(세밀함이 중요하지 않을 때 빠르고 싸게) · `high` · `original` · `auto` 중에서 고르게 되어 있다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **서식과 영수증 읽기** — 종이를 찍어 올리면 칸에 적힌 값을 그대로 뽑는다. 사람이 먼저 옮겨 적는 단계가 없어진다.\n- **여러 장을 나란히 놓고 묻기** — 한 요청에 그림을 여러 장 넣어 무엇이 다른지 묻는다. 장마다 앞에 짧은 이름표를 달아 두면 뒤에 그 이름으로 가리킬 수 있다.\n- **크기로 값 조절하기** — 세밀함이 필요 없는 그림은 보내기 전에 줄인다. 네모 수가 줄어 토큰도 그만큼 준다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **그림은 토큰과 상관없다** — 그림도 네모 조각마다 토큰으로 센다. 1000×1000 한 장이 1296 토큰이라 웬만한 질문 글보다 무겁다.\n- **그림을 읽으니 그림도 그려 준다** — 읽는 일과 만드는 일은 다르다. Anthropic 문서는 이미지 이해 전용이라 그림을 생성하거나 편집하지는 못한다고 못 박는다.\n- **크게 올릴수록 잘 본다** — 상한을 넘으면 알아서 줄여 넣으므로 더 잘 보이지 않는다. 오히려 줄어든 만큼 작은 글씨가 안 읽히고, 상한 아래라면 값만 네 배로 오른다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **사람을 알아보게 시키지 않는다.** Anthropic 문서는 사진 속 인물의 이름을 대는 일을 거부한다고 적는다.\n- **세기와 위치를 그대로 믿지 않는다.** 물건 개수와 좌표는 어림값이고, 작거나 돌아간 그림에서는 틀리기 쉽다고 문서가 못 박는다.\n- **한 요청에 그림을 많이 넣으면 장당 크기 제한이 더 빡빡해진다.** 지난 대화에 실려 다시 오는 그림까지 함께 세어지므로, 대화가 길어지면 모르는 사이에 넘어간다."}],"figure":"```도해\n흐름: 올린 사진은 모델 안에서 어떻게 되나\n사진 :: 요청에 글과 나란히 실려 들어간다\n자르기 :: 가로세로 몇십 픽셀짜리 네모로 나뉜다\n세기 :: 네모 하나가 토큰 한 개로 셈된다\n잇기 :: 글 토큰과 같은 줄에 이어 붙는다\n< 답 :: 모델은 둘을 한 줄로 읽고 답을 돌려준다\n= 그림도 글과 같은 조각으로 바꿔 한 입구로 넣는 것이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 그림을 글로 옮겨 적어 넣으면 무엇이 아쉬운가\n글로 옮겨 넣으면 || 그림째 넣으면\n옮기는 품 :: 사람이 먼저 본다 || 들지 않는다\n빠지는 것 :: 표의 배치가 없다 || 그대로 남는다\n물어볼 것 :: 옮긴 만큼만 || 안 옮긴 것도\n= 그림을 글로 바꿔 놓는 단계를 없애고 그림째 읽히는 것이다\n```\n\n예전에는 그림에 대해 물으려면 사람이 먼저 보고 글로 옮겨 적어야 했다. 옮기는 사람이 중요하다고 판단한 것만 넘어가므로, 나중에 다른 것을 묻고 싶어도 원본이 없으면 물을 수가 없다. 표의 칸 배치나 손으로 그은 화살표처럼 글로 옮기기 어려운 것은 그 자리에서 사라진다.\n\n그림을 그대로 넣으면 그 단계가 없어진다. 대신 값은 공짜가 아니다 — OpenAI 문서는 이미지 입력도 글과 비슷하게 토큰 단위로 계량되고 청구된다고 적는다."},"recap":"**\"글 말고 다른 갈래도 같은 입구로 받는 것\"** 이라고 읽으면 된다. 그림은 작은 네모로 잘려 글과 같은 줄에 이어 붙고 네모 수만큼 토큰으로 셈된다. 그래서 크게 올릴수록 값이 오르고, 상한을 넘으면 알아서 줄여 넣는다.","kid":"숙제를 글로 써서 내는 상자가 있다고 해 봐. 그 상자를 넓혀서 그림이랑 사진도 같이 받게 하면, 이제 \"이 그림에 뭐가 있어?\" 하고 물어볼 수 있지. 대신 큰 사진은 작은 네모로 잘게 잘라서 세니까 자리를 훨씬 많이 차지해.","check":[{"q":"사진의 가로세로를 두 배로 키우면 토큰이 왜 네 배가 되나","at":"작동 원리"},{"q":"표가 든 종이를 찍어 올리는 편이 옮겨 적는 것보다 나은 까닭은","at":"해결하는 문제"},{"q":"작은 글씨가 든 사진을 크게 올렸는데 더 안 읽히는 일은 왜 생기나","at":"흔한 오해"}],"myths":[{"wrong":"그림은 토큰과 상관없다","right":"그림도 네모 조각마다 토큰으로 센다. 1000×1000 한 장이 1296 토큰이라 웬만한 질문 글보다 무겁다."},{"wrong":"그림을 읽으니 그림도 그려 준다","right":"읽는 일과 만드는 일은 다르다. Anthropic 문서는 이미지 이해 전용이라 그림을 생성하거나 편집하지는 못한다고 못 박는다."},{"wrong":"크게 올릴수록 잘 본다","right":"상한을 넘으면 알아서 줄여 넣으므로 더 잘 보이지 않는다. 오히려 줄어든 만큼 작은 글씨가 안 읽히고, 상한 아래라면 값만 네 배로 오른다."}],"cases":[{"label":"서식과 영수증 읽기","note":"종이를 찍어 올리면 칸에 적힌 값을 그대로 뽑는다. 사람이 먼저 옮겨 적는 단계가 없어진다."},{"label":"여러 장을 나란히 놓고 묻기","note":"한 요청에 그림을 여러 장 넣어 무엇이 다른지 묻는다. 장마다 앞에 짧은 이름표를 달아 두면 뒤에 그 이름으로 가리킬 수 있다."},{"label":"크기로 값 조절하기","note":"세밀함이 필요 없는 그림은 보내기 전에 줄인다. 네모 수가 줄어 토큰도 그만큼 준다."}],"dia":{"shape":"흐름","title":"올린 사진은 모델 안에서 어떻게 되나","rows":[{"who":"사진","what":"요청에 글과 나란히 실려 들어간다"},{"who":"자르기","what":"가로세로 몇십 픽셀짜리 네모로 나뉜다"},{"who":"세기","what":"네모 하나가 토큰 한 개로 셈된다"},{"who":"잇기","what":"글 토큰과 같은 줄에 이어 붙는다"},{"who":"답","what":"모델은 둘을 한 줄로 읽고 답을 돌려준다","back":true}],"sum":"그림도 글과 같은 조각으로 바꿔 한 입구로 넣는 것이다"}},"ai--open-weight":{"definition":"모델은 학습이 끝나면 커다란 숫자 표 한 뭉치로 남는다. 그 표를 가중치라 부르고, 오픈 웨이트는 그 파일을 내려받을 수 있게 열어 둔 상태를 가리킨다. 이 말을 정의한 논문도 \"가중치를 널리 받을 수 있는 모델\" 이라는 한 가지 조건으로만 선을 긋는다.","name":"Open :: 누구나 받을 수 있는\nWeight :: 학습으로 정해진 숫자\n= 붙여 읽으면 \"숫자를 열어 둔 것\". 열린 것은 파일이지 만든 과정이 아니다","analogy":"다 만들어 둔 붕어빵 틀을 통째로 나눠 주는 것이다. 틀만 있으면 누구든 제 부엌에서 구울 수 있지만, 그 틀을 어떻게 만들었는지는 알려주지 않는다.","example":"인터넷이 끊긴 노트북에서도 답이 나오는 프로그램을 본 적 있다면, 그 안에 이 숫자 파일이 받아져 있는 것이다.","tryit":"모델을 모아 둔 사이트에서 파일 목록을 열어 보라. 몇 기가짜리 숫자 파일과, 어떤 조건으로 써도 되는지 적힌 줄이 나란히 있다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"```도해\n흐름: 받은 숫자 파일이 답을 내놓기까지 무엇을 거치나\n받기 :: 가중치와 함께 구조를 적은 설정, 토크나이저를 같이 받는다\n세우기 :: 실행기가 설정대로 뼈대를 세우고 그 자리에 숫자를 채운다\n줄이기 :: 메모리가 모자라면 숫자의 자릿수를 낮춰 담는다\n묻기 :: 토크나이저가 문장을 토큰 번호로 바꿔 넣는다\n답하기 :: 세운 뼈대에 그 번호를 통과시켜 다음 토큰을 하나씩 낸다\n= 가중치는 뼈대에 채워 넣는 값이라, 뼈대를 적은 설정이 없으면 숫자 뭉치일 뿐이다\n```\n\n둘째 칸이 \"열려 있다\" 는 말의 실체다. 뼈대를 세우고 숫자를 채우는 일이 내 장비에서 일어나니, 물어본 내용이 밖으로 나갈 일도 없고 만든 쪽이 나 몰래 숫자를 갈아 끼울 수도 없다.\n\n셋째 칸이 가능한 것도 파일이 손에 있어서다. 같은 숫자를 16비트로 담든 4비트로 담든 뼈대는 그대로여서 그대로 돌아간다. 대신 자릿수를 줄인 만큼 답이 조금씩 무뎌지므로, 어디까지 줄일지는 받은 쪽이 재 보고 정한다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **밖으로 못 내보내는 자료** — 파일을 안에 받아 두고 바깥과 끊긴 자리에서 돌린다.\n- **작은 장비에 맞추기** — 받은 파일의 자릿수를 줄여 노트북 메모리 안에 넣는다.\n- **판을 내가 붙들기** — 받아 둔 파일은 남이 조용히 바꾸지 못한다. 갈아탈 때를 내가 고른다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **오픈 웨이트면 소스까지 공개된 것이다** — 열린 것은 학습이 끝난 숫자 파일이다. 정의도 그 파일을 받을 수 있느냐 하나만 본다. 무엇을 먹여 어떻게 학습시켰는지는 따로 열어야 열린다.\n- **받아 두면 조건 없이 써도 된다** — 파일마다 쓸 수 있는 조건이 따로 붙는다. 받기 전에 동의와 연락처를 요구할 수 있고, 만든 쪽이 예고 없이 접근을 막을 수 있게 해 둔 곳도 있다.\n- **열려 있는 쪽이 늘 낫다** — 파일이 손에 오는 순간 장비도 자릿수도 갈아타는 시점도 전부 내 일이 된다. 그 셋을 맡을 사람이 없으면 열려 있는 것이 이득이 아니다."}],"figure":"```도해\n층: 모델에서 무엇이 어디까지 열려 있나\n답만 열림 :: 물어보면 답이 온다. 안은 못 본다\n가중치 열림 :: 숫자 파일을 받아 내 장비에서 돌린다\n학습 코드 열림 :: 어떻게 학습시켰는지까지 따라 할 수 있다\n학습 자료 열림 :: 무엇을 먹였는지까지 들여다볼 수 있다\n= 오픈 웨이트는 둘째 칸까지다. 아래 두 칸은 따로 열어야 열린다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 숫자 파일을 받을 수 있으면 무엇이 달라지나\n파일이 닫혀 있으면 || 파일을 받으면\n돌아가는 곳 :: 만든 쪽 장비만 || 내 장비에서도\n자릿수 줄이기 :: 손댈 수 없다 || 내가 고른다\n조각 붙여 학습 :: 열어 준 만큼만 || 내가 붙인다\n= 파일이 손에 오면 그 뒤의 손잡이가 전부 이쪽으로 넘어온다\n```\n\n남의 장비에서만 도는 모델은 세 가지가 내 손 밖에 있다. 무엇을 물었는지가 밖으로 나가고, 그쪽이 모델을 바꾸면 어제 하던 대로가 안 되고, 자릿수를 줄이거나 조각을 붙일 자리가 아예 없다.\n\n가중치 파일을 받으면 그 셋이 전부 이쪽으로 온다. 정의를 세운 논문이 열린 모델의 성질로 먼저 드는 것도 \"고쳐 쓰기 쉬움\" 이다. 대신 넘어오는 것이 손잡이만은 아니다. 돌릴 장비도, 몇 비트로 담을지도, 언제 새 파일로 갈아탈지도 이제 내 일이다."},"recap":"**\"학습이 끝난 숫자 파일을 열어 둔 그 상태\"** 라고 읽으면 된다. 열린 것은 파일이지 만든 과정이 아니고, 어떤 조건으로 쓸 수 있는지는 파일에 붙은 조건이 따로 정한다. 파일이 손에 오면 자릿수를 줄이는 일도 조각을 붙이는 일도 그때부터 내가 고를 수 있다.","kid":"빵집이 빵만 팔면 너는 사 먹기만 하지? 그런데 빵 굽는 틀을 통째로 나눠 주면 네 집 부엌에서도 구울 수 있어. 대신 불도 네가 켜야 하고, 그 틀을 어떻게 만들었는지는 안 알려 줘.","check":[{"q":"학습에 무엇을 먹였는지 몰라도 오픈 웨이트라고 부르는 이유는 무엇인가","at":"그림"},{"q":"파일을 받으면 자릿수를 줄이거나 조각을 붙이는 일이 왜 가능해지나","at":"해결하는 문제"},{"q":"열려 있는 쪽이 늘 이득은 아닌 이유는 무엇인가","at":"흔한 오해"}],"myths":[{"wrong":"오픈 웨이트면 소스까지 공개된 것이다","right":"열린 것은 학습이 끝난 숫자 파일이다. 정의도 그 파일을 받을 수 있느냐 하나만 본다. 무엇을 먹여 어떻게 학습시켰는지는 따로 열어야 열린다."},{"wrong":"받아 두면 조건 없이 써도 된다","right":"파일마다 쓸 수 있는 조건이 따로 붙는다. 받기 전에 동의와 연락처를 요구할 수 있고, 만든 쪽이 예고 없이 접근을 막을 수 있게 해 둔 곳도 있다."},{"wrong":"열려 있는 쪽이 늘 낫다","right":"파일이 손에 오는 순간 장비도 자릿수도 갈아타는 시점도 전부 내 일이 된다. 그 셋을 맡을 사람이 없으면 열려 있는 것이 이득이 아니다."}],"cases":[{"label":"밖으로 못 내보내는 자료","note":"파일을 안에 받아 두고 바깥과 끊긴 자리에서 돌린다."},{"label":"작은 장비에 맞추기","note":"받은 파일의 자릿수를 줄여 노트북 메모리 안에 넣는다."},{"label":"판을 내가 붙들기","note":"받아 둔 파일은 남이 조용히 바꾸지 못한다. 갈아탈 때를 내가 고른다."}],"dia":{"shape":"층","title":"모델에서 무엇이 어디까지 열려 있나","rows":[{"who":"답만 열림","what":"물어보면 답이 온다. 안은 못 본다"},{"who":"가중치 열림","what":"숫자 파일을 받아 내 장비에서 돌린다"},{"who":"학습 코드 열림","what":"어떻게 학습시켰는지까지 따라 할 수 있다"},{"who":"학습 자료 열림","what":"무엇을 먹였는지까지 들여다볼 수 있다"}],"sum":"오픈 웨이트는 둘째 칸까지다. 아래 두 칸은 따로 열어야 열린다"}},"ai--orchestrator":{"definition":"Agent 를 여러 개 만들어두는 것만으로는 쓸 수 없다. 들어온 질문이 어느 갈래인지 판단하고, 맡을 곳을 고르고, 여러 곳에서 온 답을 하나로 정리하는 자리가 따로 있어야 한다.","name":"Orchestrate :: 악기를 짜 맞추다\n= 관현악단 지휘자에서 온 말이다. 자기가 연주하지는 않고 누가 언제 소리를 낼지만 정한다","analogy":"병원 접수 창구. 증상을 듣고 어느 과로 보낼지 정하고, 여러 과를 봐야 하면 결과를 모아 한 장으로 준다.","example":"문의 한 통을 넣었을 뿐인데 배송 담당과 환불 담당이 나눠 적은 답이 한 통으로 돌아온다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"Orchestrator 안은 네 자리로 나뉜다.\n\n| 자리 | 하는 일 |\n|---|---|\n| **의도 분류** | 질문이 어느 갈래인지 정한다 |\n| **라우터** | 갈래에 맞는 Agent 를 고른다 |\n| **Agent 풀** | 각자 한 영역만 맡은 실행기들 |\n| **응답 통합** | 여러 답을 하나의 문장으로 만든다 |\n\n앞에 선 것이 뒤를 정한다. **분류가 틀리면 뒤가 아무리 좋아도 엉뚱한 답이 나온다.**\n\n의도 분류는 대개 LLM 에게 갈래 목록을 주고 문장 전체를 보고 고르게 한다. 키워드만으로 나누면 같은 단어가 여러 갈래에 걸리는 순간 어긋난다.\n\n맡은 Agent 가 \"찾을 수 없다\"고 답했을 때 그대로 끝내지 않으려면 다음 후보 순서를 정해둬야 한다. 이것을 폴백이라고 하고, 응답이 충분한지 판단하는 기준을 같이 정해두어야 동작한다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교","body":"| | Router | Orchestrator |\n|---|---|---|\n| 하는 일 | 어디로 보낼지만 | 조율 전체 |\n| Agent 수 | 하나를 고른다 | 여럿을 부를 수 있다 |\n| 결과 통합 | 없다 | 있다 |\n| 실패 처리 | 거기서 끝 | 다음 후보로 넘김 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **사내 문의 챗봇** — 규정 검색, 메뉴 안내, 급여 조회를 각각 맡은 Agent 를 두고 질문마다 하나만 부른다.\n- **복합 요청 분해** — 한 문장에 두 가지를 물으면 둘로 쪼개 각각 보내고 답을 번호로 묶어 돌려준다.\n- **폴백 사슬** — 맡은 Agent 가 못 찾으면 다음 후보에게 같은 질문을 넘겨 답이 나올 때까지 시도한다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **Orchestrator 는 라우터를 부르는 다른 말이다** — 라우터는 어디로 보낼지만 정한다. 여러 Agent 를 부르고 결과를 합치고 실패를 되받는 것까지가 조율이다.\n- **Agent 를 많이 붙일수록 답이 좋아진다** — 갈래가 늘수록 분류가 어려워진다. 잘못 고르면 좋은 Agent 가 있어도 엉뚱한 곳으로 간다.\n- **분류는 키워드만 잘 잡으면 된다** — 같은 단어가 여러 갈래에 걸친다. 그래서 대개 문장 전체를 보고 고르게 한다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **판단 못 한 경우를 정해둔다.** 갈래를 못 고른 질문을 아무 Agent 에게나 보내면 틀린 답이 그럴듯하게 나온다.\n- **분류 결과를 로그로 남긴다.** 답이 이상할 때 Agent 가 문제인지 분류가 문제인지 구분할 수 있어야 고칠 수 있다."}],"figure":"```도해\n흐름: 질문 하나가 들어오면 어느 Agent 가 답하게 되나\n사용자 :: 주소를 바꾸고 싶다고 쓴다\n분류 :: 이 질문이 어느 갈래인지 판단한다\n라우팅 :: 그 갈래를 맡은 Agent 를 고른다\nAgent :: 자기 영역에서 답을 찾아온다\n통합 :: 여러 답이면 하나로 정리한다\n< 사용자 :: 어느 Agent 가 답했는지는 모른 채 받는다\n= Agent 를 여러 개 두는 값은 어느 것을 부를지 정하는 자리에서 나온다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: Agent 를 여러 개 두기만 하면 어떻게 되나\n조율 없이 || Orchestrator 로\n질문 하나 :: 전부 응답한다 || 맡은 곳만 답\n답을 못 찾음 :: 거기서 끝난다 || 다음 곳에 물음\n요청이 둘 :: 사용자가 정리 || 하나로 묶어 줌\n= Agent 를 늘릴수록 어느 것을 부를지 정하는 일이 더 필요해진다\n```\n\n문서 검색, 메뉴 안내, 급여 조회를 각각 맡은 Agent 가 있다고 하자. \"주소 변경하고 싶어\"라는 한 문장에 셋이 전부 답하면 화면에는 서로 다른 세 개의 답이 뜬다. 사용자는 어느 것이 맞는지 알 수 없다.\n\nOrchestrator 는 그 앞에 판단을 하나 넣는다. 질문의 갈래를 정하고 맡을 곳 하나만 부른다. 실패하면 다음 후보에게 넘기고, 한 문장에 두 가지를 물었으면 둘로 쪼개 각각 보낸 뒤 결과를 합쳐 돌려준다."},"recap":"**\"누가 맡을지 정하고 답을 모아 주는 그 접수 창구\"** 라고 읽으면 된다. 의도 분류, 라우팅, 실행, 통합으로 나뉘며 앞의 분류가 전체 품질을 좌우한다. 단순히 갈래를 나누기만 하는 라우터와는 다르다.","kid":"병원에 가면 접수 창구에서 어디가 아픈지 묻고 무슨 과로 갈지 정해 주지? 두 군데를 다 봐야 하면 결과를 한 장에 모아 주기도 하고. 여기서도 네 말 한 마디를 듣고 누가 맡을지 정한 다음, 답이 여럿이면 하나로 묶어서 줘.","check":[{"q":"질문을 던졌는데 엉뚱한 Agent 가 답했다. 어느 자리를 먼저 의심하나","at":"작동 원리"},{"q":"Agent 한 곳이 못 찾았다고 답했을 때 그대로 끝나지 않게 하려면 무엇이 필요한가","at":"실제 사례"},{"q":"한 문장에 두 가지를 물으면 Orchestrator 는 무엇부터 해야 하나","at":"해결하는 문제"}],"myths":[{"wrong":"Orchestrator 는 라우터를 부르는 다른 말이다","right":"라우터는 어디로 보낼지만 정한다. 여러 Agent 를 부르고 결과를 합치고 실패를 되받는 것까지가 조율이다."},{"wrong":"Agent 를 많이 붙일수록 답이 좋아진다","right":"갈래가 늘수록 분류가 어려워진다. 잘못 고르면 좋은 Agent 가 있어도 엉뚱한 곳으로 간다."},{"wrong":"분류는 키워드만 잘 잡으면 된다","right":"같은 단어가 여러 갈래에 걸친다. 그래서 대개 문장 전체를 보고 고르게 한다."}],"cases":[{"label":"사내 문의 챗봇","note":"규정 검색, 메뉴 안내, 급여 조회를 각각 맡은 Agent 를 두고 질문마다 하나만 부른다."},{"label":"복합 요청 분해","note":"한 문장에 두 가지를 물으면 둘로 쪼개 각각 보내고 답을 번호로 묶어 돌려준다."},{"label":"폴백 사슬","note":"맡은 Agent 가 못 찾으면 다음 후보에게 같은 질문을 넘겨 답이 나올 때까지 시도한다."}],"dia":{"shape":"흐름","title":"질문 하나가 들어오면 어느 Agent 가 답하게 되나","rows":[{"who":"사용자","what":"주소를 바꾸고 싶다고 쓴다"},{"who":"분류","what":"이 질문이 어느 갈래인지 판단한다"},{"who":"라우팅","what":"그 갈래를 맡은 Agent 를 고른다"},{"who":"Agent","what":"자기 영역에서 답을 찾아온다"},{"who":"통합","what":"여러 답이면 하나로 정리한다"},{"who":"사용자","what":"어느 Agent 가 답했는지는 모른 채 받는다","back":true}],"sum":"Agent 를 여러 개 두는 값은 어느 것을 부를지 정하는 자리에서 나온다"}},"ai--parameter-count":{"definition":"모델 안에는 학습이 값을 정해 주는 숫자가 들어 있다. 맞히고 틀린 만큼 이 숫자들을 고치는 것이 학습이고, 다 고친 뒤 얼려 둔 그 숫자가 몇 개인지를 센 값이 파라미터 수다. 모델 이름 끝의 `7B`, `70B` 가 이 값을 십억 단위로 적은 것이다.","name":"Parameter :: 학습이 정하는 값\nCount :: 세어 본 개수\n= 붙여 읽으면 \"학습이 정한 값이 몇 개인가\". 이름이 곧 세는 방법이다","analogy":"라디오 맞추는 손잡이. 손잡이가 많을수록 더 정확히 맞출 수 있지만, 다 돌려 맞춰 두는 데 그만큼 오래 걸린다.","example":"모델 이름 끝에 붙은 `7B` 의 `B` 가 십억이고 앞의 숫자가 파라미터 수다. 같은 계열이면 이 숫자만으로 무게가 짐작된다.","tryit":"받아 둘 수 있는 모델 파일의 용량을 파라미터 수로 나눠 보라. 값 하나에 몇 바이트를 쓰고 있는지가 그대로 나온다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"파라미터 수는 곧바로 메모리로 환산된다. Hugging Face 문서는 혼합 정밀도 학습에서 값 하나에 드는 바이트를 이렇게 나눈다 — 계산용 사본과 안정용 사본에 6바이트, 옵티마이저가 값마다 들고 있는 관성과 분산에 8바이트, 기울기에 4바이트. 합해서 값 하나에 18바이트이고, 여기에 중간 결과가 더 얹힌다. 같은 문서는 40억짜리 모델을 16개씩 묶어 학습하면 GPU 메모리가 85GB쯤 든다고 적는다.\n\n그렇다고 이 수만 올리는 것은 낭비다. 2022년의 한 연구는 계산 예산이 정해져 있을 때 모델 크기와 학습 토큰 수를 같은 비율로 늘려야 한다고 정리했다 — 크기를 두 배로 하면 학습에 먹이는 토큰도 두 배여야 한다. 같은 예산에서 크기를 4분의 1로 줄이고 데이터를 4배로 늘린 모델이, 4배 큰 모델보다 여러 시험에서 더 나은 점수를 냈다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **장비 미리 잡기** — 학습에 드는 메모리는 값 하나당 18바이트 언저리에서 시작한다. 파라미터 수를 알면 몇 장이 필요한지가 먼저 계산된다.\n- **작은 모델로 갈아타기** — 공식 문서는 큰 모델이 값에 안 맞는 자리에서 작고 싸고 빠른 모델을 그 일에 맞게 다듬어 쓰라고 적는다. 이 수를 줄이는 것이 곧 응답 시간과 값을 줄이는 일이다.\n- **데이터와 함께 늘리기** — 크기를 두 배로 할 참이면 학습 토큰도 두 배로 잡는다. 한쪽만 늘리면 같은 예산으로 더 나쁜 모델이 나온다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **파라미터가 많을수록 무조건 낫다** — 계산 예산이 정해져 있으면 아니다. 크기를 줄이고 학습 토큰을 늘린 쪽이 4배 큰 모델을 여러 시험에서 앞선 결과가 있다.\n- **파라미터 수가 아는 지식의 양이다** — 세어 둔 것은 조절값의 개수지 담아 둔 문서의 개수가 아니다. 학습에 먹인 양은 토큰 수로 따로 센다.\n- **층을 깊게 쌓으면 그만큼 좋아진다** — 스케일링 법칙 논문은 폭이나 깊이 같은 구조 세부가 넓은 범위 안에서 거의 영향이 없다고 적었다. 잡히는 것은 전체 값의 개수 쪽이다."}],"figure":"```도해\n흐름: 이 숫자들은 어디서 와서 어디에 남나\n빈 모델 :: 값이 전부 아무렇게나 채워져 있다\n학습 :: 맞혀 보고 틀린 만큼 값을 고친다\n되풀이 :: 수많은 글로 이 고치기를 거듭한다\n굳히기 :: 다 고친 값을 그대로 얼려 파일에 담는다\n쓰기 :: 물어보면 그 값들로 계산해 답을 낸다\n= 얼려 둔 그 값이 몇 개인가를 센 수가 파라미터 수다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 모델의 덩치를 무엇으로 재나\n안 세면 || 세어 두면\n실력 어림 :: 짐작만 한다 || 규칙이 보인다\n필요한 장비 :: 돌려봐야 안다 || 미리 계산된다\n모델끼리 견주기 :: 기준이 없다 || 한 줄로 선다\n= 층수나 폭 대신 값의 개수 하나로 덩치를 재기로 한 것이다\n```\n\n모델을 견줄 잣대는 여럿일 수 있다. 층을 몇 겹 쌓았는지, 한 층이 얼마나 넓은지, 어떤 구조를 골랐는지. 그런데 스케일링 법칙 논문은 그 구조 세부가 넓은 범위 안에서는 거의 영향이 없다고 적는다. 대신 손실은 모델 크기 · 데이터 크기 · 계산량 세 가지에 대해 거듭제곱 꼴로 움직이고, 그 추세가 자릿수로 일곱 개가 넘는 범위에서 이어진다.\n\n그래서 값의 개수 하나가 나머지를 대신하는 잣대가 되었다. 이 수를 알면 학습에 몇 장이 필요한지가 곱셈으로 나오고, 다른 모델과 한 줄에 세울 수도 있다."},"recap":"**\"학습이 정해 놓은 조절값이 몇 개인가\"** 라고 읽으면 된다. 이 수 하나로 필요한 장비가 곱셈으로 나오고 다른 모델과 한 줄에 설 수도 있다. 다만 계산 예산이 정해져 있으면 크기만 키우는 것은 손해라, 학습에 먹이는 양과 같은 비율로 올려야 한다.","kid":"라디오 맞추는 손잡이 알지? 손잡이가 하나뿐이면 대충만 맞고, 손잡이가 아주 많으면 훨씬 정확히 맞출 수 있어. 대신 손잡이가 많아질수록 그걸 다 돌려 맞춰 두는 데 시간도 자리도 훨씬 많이 들어.","check":[{"q":"파라미터 수를 알면 필요한 장비를 왜 미리 계산할 수 있나","at":"해결하는 문제"},{"q":"계산 예산이 정해져 있는데 크기만 두 배로 키우면 왜 손해인가","at":"작동 원리"},{"q":"모델 이름 끝에 붙은 숫자는 무엇을 센 것인가","at":"그림"}],"myths":[{"wrong":"파라미터가 많을수록 무조건 낫다","right":"계산 예산이 정해져 있으면 아니다. 크기를 줄이고 학습 토큰을 늘린 쪽이 4배 큰 모델을 여러 시험에서 앞선 결과가 있다."},{"wrong":"파라미터 수가 아는 지식의 양이다","right":"세어 둔 것은 조절값의 개수지 담아 둔 문서의 개수가 아니다. 학습에 먹인 양은 토큰 수로 따로 센다."},{"wrong":"층을 깊게 쌓으면 그만큼 좋아진다","right":"스케일링 법칙 논문은 폭이나 깊이 같은 구조 세부가 넓은 범위 안에서 거의 영향이 없다고 적었다. 잡히는 것은 전체 값의 개수 쪽이다."}],"cases":[{"label":"장비 미리 잡기","note":"학습에 드는 메모리는 값 하나당 18바이트 언저리에서 시작한다. 파라미터 수를 알면 몇 장이 필요한지가 먼저 계산된다."},{"label":"작은 모델로 갈아타기","note":"공식 문서는 큰 모델이 값에 안 맞는 자리에서 작고 싸고 빠른 모델을 그 일에 맞게 다듬어 쓰라고 적는다. 이 수를 줄이는 것이 곧 응답 시간과 값을 줄이는 일이다."},{"label":"데이터와 함께 늘리기","note":"크기를 두 배로 할 참이면 학습 토큰도 두 배로 잡는다. 한쪽만 늘리면 같은 예산으로 더 나쁜 모델이 나온다."}],"dia":{"shape":"흐름","title":"이 숫자들은 어디서 와서 어디에 남나","rows":[{"who":"빈 모델","what":"값이 전부 아무렇게나 채워져 있다"},{"who":"학습","what":"맞혀 보고 틀린 만큼 값을 고친다"},{"who":"되풀이","what":"수많은 글로 이 고치기를 거듭한다"},{"who":"굳히기","what":"다 고친 값을 그대로 얼려 파일에 담는다"},{"who":"쓰기","what":"물어보면 그 값들로 계산해 답을 낸다"}],"sum":"얼려 둔 그 값이 몇 개인가를 센 수가 파라미터 수다"}},"ai--prompt":{"definition":"같은 모델에 같은 질문을 해도 어떻게 적었느냐에 따라 답이 달라진다. 모델을 손대지 않고 답을 바꿀 수 있는 자리가 여기다.","name":"Prompt :: 대사를 일러 주다\n= 무대 뒤에서 배우에게 대사를 넣어 주는 프롬프터와 같은 말이다. 대신 연기하지 않고 첫 마디만 넣어 준다","analogy":"심부름 쪽지. \"우유 사와\"보다 \"1L 저지방으로, 없으면 일반으로\"가 원하던 걸 받을 확률이 높다.","example":"배달 앱 요청사항 칸에 문 앞에 놓아 달라고 적어 보낸 그 한 줄이 프롬프트다. 안 적으면 알아서 정한다.","tryit":"챗봇에 \"이거 언제야?\" 라고만 보내 보라. 무엇을 가리키는지 안 적었으니 답 대신 되묻는 말이 돌아온다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"모델은 받은 글을 토큰으로 쪼갠 뒤 앞의 토큰을 보고 다음 토큰을 하나씩 고른다. 지시를 이해하고 따르는 것이 아니라 그 지시 뒤에 올 법한 말을 이어 붙이는 쪽에 가깝다. 그래서 어떻게 적었는지가 답의 모양을 크게 흔든다.\n\n한 장의 프롬프트에는 네 가지가 들어간다. **시스템**은 대화 내내 지킬 역할과 말투를 깔아두는 자리, **지시**는 이번에 무엇을 해달라고 적는 자리다. **예시**는 답이 어떤 모양이어야 하는지 몇 개 보여주는 자리이고, **맥락**은 답에 쓸 문서나 데이터를 붙이는 자리다.\n\n```도해\n대조: 시스템 프롬프트와 나머지는 무엇이 다른가\n시스템 |=| 지시·예시·맥락\n적는 때 :: 대화 시작 전에 || 물을 때마다\n남는 기간 :: 대화 내내 || 이번 한 번\n담는 것 :: 역할과 말투 || 할 일과 자료\n= 한 번 깔아두고 계속 듣는 자리와 매번 새로 적는 자리가 나뉜다\n```\n\n예시를 하나도 주지 않고 시키는 것을 Zero-shot 이라 하고, 답의 모양을 두셋 보여준 뒤 시키는 것을 Few-shot 이라 한다. 답 대신 푸는 과정을 단계로 나눠 적으라고 시키는 것은 Chain-of-Thought 다. 사과 3개가 1,000원일 때 7개 값을 물으면서 단계를 나누라고 적으면, 한 개 값을 먼저 구하고 그다음에 곱하는 순서로 답이 나온다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **감정 분류** — 문장을 주고 긍정, 부정, 중립 중 하나로만 답하라고 적으면 라벨 하나만 돌아온다.\n- **고객 응대 챗봇** — 시스템 프롬프트에 존댓말을 쓰라고 깔아두면 대화가 이어지는 동안 말투가 유지된다.\n- **문서 기반 답변** — 문서를 붙이고 \"문서에 없으면 없다고 답하라\"고 못 박아 지어내는 답을 줄인다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **프롬프트는 질문이다** — 질문만이 아니다. 역할, 조건, 예시, 붙인 문서까지 모델에 들어가는 글 전부가 프롬프트다.\n- **프롬프트를 잘 쓰면 모델이 배운다** — 배우지 않는다. 그 요청 한 번에만 반영되고 다음 대화에는 남지 않는다. 모델 자체를 바꾸는 것은 Fine-tuning 이다.\n- **예시는 많이 넣을수록 좋다** — 예시도 프롬프트 안에 들어가고 넣을 수 있는 양에는 한계가 있다. 답의 모양을 보여줄 만큼만 넣는다."}],"figure":"```도해\n흐름: 프롬프트 한 장이 답이 되기까지 무엇을 거치나\n사람 :: 지시와 맥락을 한 덩어리 글로 적는다\n토큰화 :: 그 글이 토큰 조각으로 쪼개진다\nLLM :: 앞의 토큰을 보고 다음 토큰을 고른다\n< 사람 :: 멈출 자리까지 이어 붙인 답을 받는다\n@ 다시 고르기 :: 고른 토큰을 뒤에 붙이고 한 조각 더\n= 지시를 이해한 게 아니라 그 지시 뒤에 올 법한 말을 이어 붙인 것이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 요약해달라고만 하면 무엇이 달라지나\n조건 없이 || 조건을 붙이면\n길이 :: 모델이 정한다 || 3줄로 못 박는다\n대상 :: 무엇을 요약할지 || 붙인 문서에서만\n말투 :: 그때그때 다름 || 정해둔 대로\n= 안 적어 보낸 자리는 모델이 알아서 메운다\n```\n\n\"요약해줘\"라고만 보내면 모델은 무엇을, 얼마나, 어떤 말투로 줄일지를 스스로 정한다. 정할 근거가 없으니 매번 다른 답이 나온다. \"이거 언제야?\"처럼 가리키는 말이 들어가면 무엇을 가리키는지조차 몰라 되묻는 답이 돌아온다.\n\n프롬프트에 조건을 적으면 그만큼이 정해진다. \"다음 문서를 3줄로 요약하세요\"라고 쓰고 문서를 붙이면 길이와 대상이 같이 박힌다. 안 적은 자리는 여전히 모델이 메운다는 점만 기억하면 된다."},"recap":"**\"안 적으면 저쪽이 정해 버리는 그 심부름 쪽지\"** 라고 읽으면 된다. 모델을 손대지 않고 답을 바꿀 수 있는 유일한 자리이고, 적어 보내지 않은 조건은 모델이 알아서 메운다. 역할과 지시와 예시와 맥락을 어디까지 적을지 고르는 일이 프롬프트를 쓰는 일이다.","kid":"쪽지에 \"우유 사 와\" 라고만 적어 보내면 어떤 우유를 사 올지는 사러 간 사람이 정하지? \"작은 걸로, 없으면 큰 걸로\" 까지 적으면 그대로 사 와. 안 적은 자리는 저쪽이 알아서 채워 버리니까, 뭘 적었느냐가 받는 것을 바꿔.","check":[{"q":"\"요약해줘\" 한 마디만 보냈을 때 길이와 말투는 누가 정하나","at":"해결하는 문제"},{"q":"예시 세 개를 넣어 답이 좋아졌다면 모델이 그 예시를 배운 것인가","at":"흔한 오해"},{"q":"시스템 프롬프트에 적은 말투가 다음 질문에도 남아 있는 이유는","at":"작동 원리"}],"myths":[{"wrong":"프롬프트는 질문이다","right":"질문만이 아니다. 역할, 조건, 예시, 붙인 문서까지 모델에 들어가는 글 전부가 프롬프트다."},{"wrong":"프롬프트를 잘 쓰면 모델이 배운다","right":"배우지 않는다. 그 요청 한 번에만 반영되고 다음 대화에는 남지 않는다. 모델 자체를 바꾸는 것은 Fine-tuning 이다."},{"wrong":"예시는 많이 넣을수록 좋다","right":"예시도 프롬프트 안에 들어가고 넣을 수 있는 양에는 한계가 있다. 답의 모양을 보여줄 만큼만 넣는다."}],"cases":[{"label":"감정 분류","note":"문장을 주고 긍정, 부정, 중립 중 하나로만 답하라고 적으면 라벨 하나만 돌아온다."},{"label":"고객 응대 챗봇","note":"시스템 프롬프트에 존댓말을 쓰라고 깔아두면 대화가 이어지는 동안 말투가 유지된다."},{"label":"문서 기반 답변","note":"문서를 붙이고 \"문서에 없으면 없다고 답하라\"고 못 박아 지어내는 답을 줄인다."}],"dia":{"shape":"흐름","title":"프롬프트 한 장이 답이 되기까지 무엇을 거치나","rows":[{"who":"사람","what":"지시와 맥락을 한 덩어리 글로 적는다"},{"who":"토큰화","what":"그 글이 토큰 조각으로 쪼개진다"},{"who":"LLM","what":"앞의 토큰을 보고 다음 토큰을 고른다"},{"who":"사람","what":"멈출 자리까지 이어 붙인 답을 받는다","back":true}],"sum":"지시를 이해한 게 아니라 그 지시 뒤에 올 법한 말을 이어 붙인 것이다","loop":{"who":"다시 고르기","what":"고른 토큰을 뒤에 붙이고 한 조각 더"}}},"ai--prompt-caching":{"definition":"모델은 매번 프롬프트를 처음부터 끝까지 읽는다. 그런데 실제 서비스에서 앞쪽은 거의 안 바뀐다 — 규정 문서, 예시 몇 개, 도구 정의는 부를 때마다 똑같이 실린다. 그 앞부분을 읽어들인 상태로 저장해 두었다가 다음 요청에서 이어 쓰는 것이 이 장치다. 두 곳의 공식 문서가 같은 말로 적는다. Anthropic 문서는 \"프롬프트의 특정 앞자락에서 이어서 시작하게 해 준다\" 고 쓰고, OpenAI 문서는 \"프롬프트의 앞자락이 정확히 일치할 때만 캐시가 걸린다\" 고 쓴다.","name":"Prompt :: 모델에 건네는 말\nCaching :: 해 둔 것을 남겨 둠\n= 붙여 읽으면 \"건넨 말을 남겨 두고 다시 쓰기\". 남는 것은 답이 아니라 읽어들인 앞부분이다","analogy":"매일 같은 교과서를 펴는 수업. 읽은 데까지 책갈피가 꽂혀 있어서, 오늘은 그 뒤부터 읽으면 된다.","example":"계약서를 통째로 붙여 넣고 질문만 바꿔 가며 열 번 물어볼 때다. 계약서는 열 번 다 똑같다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"**손으로 잡는 손잡이는 셋이다.** 첫째는 어디까지를 저장할지 정하는 표시다. Anthropic 문서는 자주 바뀌는 정도가 다른 구간을 따로 저장하도록 표시 지점을 최대 네 곳까지 둘 수 있다고 적는다. 표시를 뒤로 밀수록 저장되는 앞부분이 길어지고, 그만큼 그 뒤가 조금만 바뀌어도 다시 읽힐 것이 늘어난다. OpenAI 쪽은 이 표시가 아예 없다 — 길이 조건만 넘으면 자동으로 걸린다.\n\n둘째는 수명이다. Anthropic 문서는 기본 수명을 5분으로 적고, 그것이 짧으면 1시간짜리를 고를 수 있다고 적는다. 대신 1시간짜리는 처음 넣을 때 값이 더 든다. 이 값을 올리면 뜸하게 오는 대화도 살아남고, 대신 한 번 부르고 마는 요청에서는 넣어 둔 값만 나간다. OpenAI 쪽은 고를 것이 없고, 앞자락을 다시 쓸 때마다 수명이 갱신된다.\n\n셋째는 길이다. 두 곳 다 하한이 있다 — 모델마다 다르고, 흔한 값이 천 토큰이다. 그보다 짧으면 **표시를 해 두어도 그냥 캐시 없이 처리되고 오류도 나지 않는다.** 그래서 \"표시했는데 왜 그대로지\" 가 여기서 자주 나온다. 걸렸는지는 응답의 사용량에서 확인한다. 새로 넣은 양과 꺼내 쓴 양이 따로 세어져 돌아온다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **긴 지시문을 매번 보내는 상담 도우미** — 규정 문서와 예시가 앞에 그대로 실린다. 두 번째 질문부터는 그 앞부분을 다시 읽지 않는다.\n- **도구를 여럿 붙인 에이전트** — 도구 정의는 요청의 맨 앞에 실리고, 한 바퀴 돌 때마다 똑같이 다시 실린다. 표시해 두면 그 몫을 한 번만 낸다.\n- **문서 하나를 놓고 여러 번 묻기** — 계약서를 앞에 붙이고 질문만 바꾼다. 계약서는 저장분에서 나오고 질문만 새로 읽힌다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **캐시를 켜면 무조건 싸진다** — 처음 넣을 때는 오히려 값이 더 든다. 수명 안에 다시 안 부르면 손해다. 자주 되풀이되는 앞부분에만 값을 한다.\n- **비슷하면 걸린다** — Anthropic 문서는 앞자락이 100% 똑같아야 한다고 적는다. 지시문 맨 앞에 오늘 날짜 한 줄을 넣는 순간 그 뒤가 전부 다시 읽힌다.\n- **남이 같은 지시문을 쓰면 내 캐시를 가져다 쓴다** — 아니다. 두 곳 문서 모두 조직이 다르면 프롬프트가 글자 하나까지 똑같아도 저장분을 나눠 쓰지 않는다고 못 박는다. 아끼는 몫은 내가 만든 저장분에서만 나온다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **바뀌는 것을 앞에 두지 마라.** OpenAI 문서는 지시문과 예시처럼 안 바뀌는 것을 앞에, 사용자마다 다른 것을 뒤에 두라고 적는다. 앞줄의 시각 하나가 뒤 전부를 무효로 만든다.\n- **도구 목록을 함부로 흔들지 마라.** 도구 정의가 바뀌면 그 아래가 통째로 무효다. 도구를 하나 늘린 것만으로 절약이 사라진다.\n- **짧으면 아무 일도 안 일어난다.** 하한 미만은 조용히 캐시 없이 처리된다. 안 걸린 것을 알려주지 않으므로 사용량을 직접 봐야 한다."}],"figure":"```도해\n흐름: 같은 앞부분을 다시 보내면 무슨 일이 일어나나\n요청 :: 지시문·문서·질문을 통째로 다시 보낸다\n맞춰 보기 :: 앞에서부터 저장해 둔 것과 대조한다\n같은 데까지 :: 계산을 건너뛰고 그대로 가져온다\n어긋난 뒤 :: 여기서부터만 새로 읽는다\n< 응답 :: 꺼내 쓴 양과 새로 넣은 양을 함께 알려준다\n= 앞에서부터 똑같은 만큼만 아낀다. 한 글자라도 다르면 거기서부터 다시다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 앞부분이 길어지면 무엇이 달라지나\n캐시 없이 || 캐시로\n같은 지시문 :: 부를 때마다 다시 || 한 번만 읽는다\n값 :: 전부 제값 || 읽기는 십분의 일\n기다림 :: 앞부분만큼 늦다 || 뒷부분만큼만\n= 되풀이되는 앞부분이 길수록 아끼는 몫이 커진다\n```\n\n앞에 붙이는 것이 길어질수록 값과 기다림이 같이 늘어난다. 규정 문서 스무 장을 붙여 놓고 한 줄짜리 질문을 던지면, 매번 스무 장을 다시 읽히고 그만큼을 매번 낸다. 질문을 열 번 하면 스무 장을 열 번 읽는다.\n\n캐싱은 **안 바뀌는 앞부분과 바뀌는 뒷부분을 갈라 놓는다.** 앞부분은 한 번만 읽히고, 그다음부터는 저장분에서 꺼내 쓴다. 두 곳 문서가 모두 꺼내 쓴 몫을 원래 입력값의 십분의 일로 계산한다고 적는다. 그래서 앞부분이 길수록, 그리고 같은 앞부분을 자주 부를수록 이득이 커진다."},"compose":{"label":"무엇으로 되어 있나","head":"🧱 구성","body":"```도해\n층: 요청의 어느 칸을 고치면 어디까지 무효가 되나\n도구 정의 :: 맨 앞에 실린다. 여기를 고치면 아래가 전부 무효\n지시문 :: 도구가 그대로여도 여기를 고치면 아래가 무효\n주고받은 말 :: 위가 그대로면 앞에서부터 같은 데까지는 살아 있다\n= 위를 건드리면 아래가 통째로 날아간다. 그래서 안 바뀌는 것을 위에 둔다\n```"},"recap":"**\"앞부분을 다시 안 읽게 해 두는 그 표시\"** 라고 읽으면 된다. 앞에서부터 한 글자도 안 틀린 만큼만 걸리므로, 안 바뀌는 것을 앞에 몰아 두는 것이 사실상 전부다. 걸렸는지 아닌지는 짐작하지 말고 응답에 딸려 오는 사용량으로 확인한다.","kid":"선생님이 매일 같은 책을 펴서 앞쪽 스무 장을 처음부터 다시 읽어 주면 지루하겠지? 그래서 읽은 데까지 책갈피를 꽂아 둬. 다음 시간에는 책갈피 뒤부터만 읽으니까 훨씬 빨리 오늘 이야기에 닿아.","check":[{"q":"지시문 맨 앞줄에 오늘 날짜를 적어 두면 왜 아끼는 것이 없어지나","at":"주의사항"},{"q":"앞부분은 그대로인데 도구를 하나 늘렸다. 어디까지 다시 읽히나","at":"구성"},{"q":"표시를 해 뒀는데 값이 그대로 나온다. 무엇을 먼저 의심하나","at":"작동 원리"}],"myths":[{"wrong":"캐시를 켜면 무조건 싸진다","right":"처음 넣을 때는 오히려 값이 더 든다. 수명 안에 다시 안 부르면 손해다. 자주 되풀이되는 앞부분에만 값을 한다."},{"wrong":"비슷하면 걸린다","right":"Anthropic 문서는 앞자락이 100% 똑같아야 한다고 적는다. 지시문 맨 앞에 오늘 날짜 한 줄을 넣는 순간 그 뒤가 전부 다시 읽힌다."},{"wrong":"남이 같은 지시문을 쓰면 내 캐시를 가져다 쓴다","right":"아니다. 두 곳 문서 모두 조직이 다르면 프롬프트가 글자 하나까지 똑같아도 저장분을 나눠 쓰지 않는다고 못 박는다. 아끼는 몫은 내가 만든 저장분에서만 나온다."}],"cases":[{"label":"긴 지시문을 매번 보내는 상담 도우미","note":"규정 문서와 예시가 앞에 그대로 실린다. 두 번째 질문부터는 그 앞부분을 다시 읽지 않는다."},{"label":"도구를 여럿 붙인 에이전트","note":"도구 정의는 요청의 맨 앞에 실리고, 한 바퀴 돌 때마다 똑같이 다시 실린다. 표시해 두면 그 몫을 한 번만 낸다."},{"label":"문서 하나를 놓고 여러 번 묻기","note":"계약서를 앞에 붙이고 질문만 바꾼다. 계약서는 저장분에서 나오고 질문만 새로 읽힌다."}],"dia":{"shape":"흐름","title":"같은 앞부분을 다시 보내면 무슨 일이 일어나나","rows":[{"who":"요청","what":"지시문·문서·질문을 통째로 다시 보낸다"},{"who":"맞춰 보기","what":"앞에서부터 저장해 둔 것과 대조한다"},{"who":"같은 데까지","what":"계산을 건너뛰고 그대로 가져온다"},{"who":"어긋난 뒤","what":"여기서부터만 새로 읽는다"},{"who":"응답","what":"꺼내 쓴 양과 새로 넣은 양을 함께 알려준다","back":true}],"sum":"앞에서부터 똑같은 만큼만 아낀다. 한 글자라도 다르면 거기서부터 다시다"}},"ai--prompt-engineering":{"definition":"같은 모델도 무엇을 어떻게 물었느냐에 따라 다른 답을 내놓는다. 모델을 고치는 대신 입력을 고쳐서 답의 범위를 좁히는 것이 이 일이다.","name":"Prompt :: 시켜 보내는 글\nEngineering :: 되게끔 설계하는 일\n= 붙여 읽으면 \"시키는 글을 설계하는 일\". 한 방에 맞히는 재주가 아니라 고쳐 가며 맞추는 작업이다","analogy":"택배 기사에게 주소를 적어주는 것. \"우리 집\"이라고 쓰면 못 찾고, 동과 호수까지 쓰면 한 번에 온다.","example":"검색이 엉뚱하게 나올 때 낱말을 바꿔 다시 쳐서 원하던 결과를 얻어본 적이 있다. 그 고쳐 치는 일이 여기서 하는 일이다.","tryit":"검색에 원하던 게 안 나오면 낱말을 하나 더 붙여 다시 쳐 보라. 같은 곳에 물었는데 결과가 달라진다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"```도해\n층: 프롬프트에 무엇부터 얹나\n할 일 :: 무엇을 만들지 한 문장으로 적는다\n조건 :: 형식, 길이, 쓰지 말 것을 적는다\n예시 :: 원하는 답을 한두 벌 보여준다\n생각 순서 :: \"단계별로 생각해보자\" 처럼 절차를 준다\n= 위쪽만으로 되면 아래를 붙일 이유가 없다. 안 될 때 하나씩 얹는다\n```\n\n예시 없이 지시만 주는 것을 Zero-shot이라고 한다. 답의 형식이 흔들리면 예시를 한두 개 붙이는데, 이게 Few-shot이다. \"긍정/부정\"처럼 라벨을 정해 보여주면 그 표기를 따라온다.\n\n계산이나 추론이 섞이면 \"단계별로 생각해보자\"를 덧붙인다. 피자 세 판을 여덟 명이 나누는 문제에서 답만 던지는 대신 전체 조각을 먼저 세고 나누는 식으로 과정을 적게 하는 것을 Chain-of-Thought라고 한다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **분류 작업** — 예시 두 개를 붙여주면 라벨 표기가 예시와 같은 모양으로 나온다.\n- **계산 문제** — 과정을 적게 하면 답만 던질 때보다 덜 틀리고, 틀렸을 때 어디서 어긋났는지 보인다.\n- **코드 요청** — 쓸 라이브러리, 입력과 출력, 예외 처리 여부를 적어주면 받아서 고칠 일이 줄어든다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **프롬프트는 길게 쓸수록 좋다** — 길이가 아니라 무엇이 적혀 있느냐다. 상관없는 말을 늘리면 정작 지켜야 할 조건이 그 안에 묻힌다.\n- **성능을 올려주는 마법의 문장이 있다** — \"당신은 전문가입니다\" 한 줄이 없던 지식을 만들어주지는 않는다. 역할을 주는 것은 말투와 관점의 범위를 좁히는 일이다.\n- **잘 물으면 모르는 것도 답해준다** — 프롬프트는 무엇을 어떤 모양으로 답할지를 정할 뿐이다. 모델이 갖고 있지 않은 사실이 필요하면 그 자료를 프롬프트에 같이 넣어야 한다."}],"figure":"```도해\n흐름: 프롬프트를 고쳐 쓰면 답이 어떻게 달라지나\n막연한 요청 :: \"코드 짜줘\". 언어도 조건도 없다\n할 일 적기 :: 무엇을 만들지 한 문장으로 못 박는다\n조건 적기 :: 쓸 라이브러리와 입력, 출력을 적는다\n예시 넣기 :: 원하는 답의 모양을 한 벌 보여준다\n< 모델 :: 좁아진 범위 안에서 골라 답을 돌려준다\n= 모델은 마음을 읽지 않는다. 안 적은 것은 알아서 정한다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 요청을 대충 적으면 무엇이 달라지나\n막연한 요청 || 조건을 적은 요청\n결과 :: 매번 다르다 || 모양이 고정된다\n다시 시키기 :: 계속 고쳐 말한다 || 한 번에 끝난다\n쓸 수 있나 :: 손보고 써야 한다 || 그대로 붙인다\n= 안 적은 조건은 모델이 대신 정해버린다\n```\n\n\"코드 작성해줘\"라고만 하면 언어도, 쓸 라이브러리도, 예외 처리 여부도 모델이 정한다. 그때그때 다른 선택을 하니 같은 요청에 다른 답이 오고, 받을 때마다 고쳐 써야 한다.\n\n프롬프트에 그 선택지들을 미리 적어두면 모델이 정할 몫이 줄어든다. 답이 매번 비슷한 모양으로 나오고, 그래야 다음 단계에 그대로 넘길 수 있다."},"recap":"**\"모델이 알아서 정할 몫을 줄여 가는 그 고쳐 쓰기\"** 라고 읽으면 된다. 지시, 조건, 예시, 생각 순서를 필요한 만큼만 얹고, 안 될 때 하나씩 더한다.","kid":"택배 아저씨한테 \"우리 집\" 이라고만 적어 주면 못 찾지? 동이랑 호수까지 적어 주면 한 번에 와. 어떻게 적었느냐로 오는 게 달라지니까, 엉뚱한 게 오면 화내지 말고 적는 말을 고쳐서 다시 보내는 거야.","check":[{"q":"\"코드 짜줘\"라고만 했을 때 같은 요청에 매번 다른 답이 오는 이유는","at":"해결하는 문제"},{"q":"예시를 한두 개 붙였을 때 답의 무엇이 고정되나","at":"실제 사례"},{"q":"계산 문제에서 답만 던지고 틀릴 때 프롬프트에 무엇을 덧붙이나","at":"작동 원리"}],"myths":[{"wrong":"프롬프트는 길게 쓸수록 좋다","right":"길이가 아니라 무엇이 적혀 있느냐다. 상관없는 말을 늘리면 정작 지켜야 할 조건이 그 안에 묻힌다."},{"wrong":"성능을 올려주는 마법의 문장이 있다","right":"\"당신은 전문가입니다\" 한 줄이 없던 지식을 만들어주지는 않는다. 역할을 주는 것은 말투와 관점의 범위를 좁히는 일이다."},{"wrong":"잘 물으면 모르는 것도 답해준다","right":"프롬프트는 무엇을 어떤 모양으로 답할지를 정할 뿐이다. 모델이 갖고 있지 않은 사실이 필요하면 그 자료를 프롬프트에 같이 넣어야 한다."}],"cases":[{"label":"분류 작업","note":"예시 두 개를 붙여주면 라벨 표기가 예시와 같은 모양으로 나온다."},{"label":"계산 문제","note":"과정을 적게 하면 답만 던질 때보다 덜 틀리고, 틀렸을 때 어디서 어긋났는지 보인다."},{"label":"코드 요청","note":"쓸 라이브러리, 입력과 출력, 예외 처리 여부를 적어주면 받아서 고칠 일이 줄어든다."}],"dia":{"shape":"흐름","title":"프롬프트를 고쳐 쓰면 답이 어떻게 달라지나","rows":[{"who":"막연한 요청","what":"\"코드 짜줘\". 언어도 조건도 없다"},{"who":"할 일 적기","what":"무엇을 만들지 한 문장으로 못 박는다"},{"who":"조건 적기","what":"쓸 라이브러리와 입력, 출력을 적는다"},{"who":"예시 넣기","what":"원하는 답의 모양을 한 벌 보여준다"},{"who":"모델","what":"좁아진 범위 안에서 골라 답을 돌려준다","back":true}],"sum":"모델은 마음을 읽지 않는다. 안 적은 것은 알아서 정한다"}},"ai--prompt-injection":{"definition":"두 갈래다. 사용자가 직접 자기 앞의 규칙을 뒤집으려 드는 쪽이 직접 주입이고, 사용자는 멀쩡한데 모델이 대신 읽는 남의 글에 명령이 숨어 있는 쪽이 간접 주입이다. 뒤쪽이 2023년 논문에서 이름을 얻었다. 모델을 붙인 앱이 자료와 명령의 경계를 흐린다는 것이 그 논문의 지적이다.","name":"Prompt :: 시키는 글\nInjection :: 몰래 끼워 넣기\n= 붙여 읽으면 \"시키는 글을 몰래 끼워 넣기\". 값이 놓일 자리에 명령이 들어간다는 점이 SQL Injection 과 같다","analogy":"낯선 사람이 대본에 한 줄을 몰래 적어 넣으면, 낭독자는 그 줄도 제 대본인 줄 알고 그대로 읽는다.","example":"AI 에게 링크를 주고 요약을 시켜 본 적이 있다면, 그 페이지에 남이 적어 둔 글이 그대로 모델 앞에 놓인 것이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"```도해\n층: 주입을 어디서 막을 수 있나\n자리 나누기 :: 남의 글은 도구 결과 칸에만 넣는다. 구조로 가르는 자리\n출처 라벨 :: 이게 어디서 온 무엇인지 함께 적어 준다. 모르는 사람이 보낸 메일 본문이라는 식으로\n검사기 :: 도구가 돌려준 글에 지시가 섞였는지 작은 모델이 먼저 본다\n권한 줄이기 :: 뚫려도 할 수 있는 일이 적으면 피해가 준다\n= 위는 애초에 안 섞이게 하고, 아래는 섞였을 때를 대비한다. 한 겹으로는 부족하다\n```\n\n손으로 만지는 값이 넷이다. 첫째, 남의 글을 어느 칸에 넣느냐. 도구 결과 칸으로 옮기는 것만으로 모델이 그 글을 대하는 태도가 달라진다. 둘째, 그 글을 그대로 이어 붙이느냐 JSON 으로 감싸느냐. 감싸면 따옴표나 태그를 닫고 명령 자리로 빠져나오는 수법이 막힌다.\n\n셋째, 검사기를 붙이느냐. 도구를 돌린 뒤 결과를 작은 모델에게 먼저 보여 \"지시가 섞였나\" 만 참·거짓으로 받아 두고, 아니라고 나온 것만 모델에게 넘긴다. 넷째, 권한을 얼마나 주느냐. 안 쓰는 비밀 값을 빼고 도구를 좁게 열어 두면 뚫린 뒤의 피해가 그만큼 작아진다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **메일 비서** — 받은 편지 본문에 적힌 지시가 명령으로 읽혀 엉뚱한 도구가 불린다.\n- **문서 요약** — 올린 파일에서 뽑아낸 글자에 명령이 섞여 들어온다.\n- **화면을 보고 움직이는 도구** — 화면 속 글에 주입이 의심되면 다음 동작 전에 사람 확인을 받도록 돌린다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **시스템 프롬프트에 \"다른 지시는 따르지 마라\" 를 적어두면 막힌다** — 그것도 결국 같은 글자다. 적어 두는 편이 낫지만 그 한 줄이 방어의 전부일 수는 없고, 자리를 나누고 권한을 줄이는 일이 따로 필요하다.\n- **사용자만 믿을 만하면 안전하다** — 사용자가 멀쩡해도 모델이 대신 읽는 남의 글이 남는다. 메일 본문, 가져온 웹 페이지, 도구가 돌려준 결과가 전부 그 자리다.\n- **검사기를 하나 붙이면 끝난다** — Anthropic 문서는 자리 나누기·출처 표시·검사·권한 축소·직접 공격해 보기를 겹쳐 쌓으라고 적는다. 한 겹은 뚫린다는 전제로 짠 목록이다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **내 지시를 도구 결과 칸에 적지 마라.** 모델이 그 칸을 한 겹 걸러 읽으므로 무시되거나 공격으로 잡힌다. 지시는 도구 결과 다음 사용자 차례에 넣는다.\n- **뚫린 뒤를 먼저 정해라.** 필요 없는 비밀 값은 주지 않고, 도구는 좁은 권한으로 격리된 자리에서 돌린다.\n- **배포 전에 스스로 공격해라.** 주입 문장을 심은 문서와 메일로 자기 흐름을 먼저 시험하고, 검사와 확인 단계가 실제로 걸리는지 본다."}],"figure":"```도해\n흐름: 자료에 적힌 한 줄이 어떻게 명령이 되나\n개발자 :: 시스템 프롬프트로 할 일을 정해 둔다\n사용자 :: 이 페이지를 요약해 달라고 한다\n도구 :: 그 페이지를 가져와 그대로 이어 붙인다\n페이지 :: 본문에 \"앞의 지시는 무시하라\" 가 적혀 있다\n모델 :: 셋을 한 덩어리 글로 읽는다\n< 사용자 :: 요약 대신 남이 시킨 답이 돌아온다\n= 모델에게는 자료와 명령이 같은 글자다. 넣어 준 글이 원래 지시를 밀어낸다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"이 항목은 해결하는 문제가 아니라 **막아야 할 공격**이다.\n\n```도해\n대조: 가져온 글을 자료로 못 가르면 무슨 일이 생기나\n경계 없이 || 자리를 갈라 두면\n메일 본문 :: 명령으로 읽힌다 || 자료로 읽힌다\n숨은 한 줄 :: 도구를 부른다 || 보고만 한다\n피해 범위 :: 권한 전부 || 준 만큼만\n= 문제는 모델의 판단력이 아니라, 자료와 명령이 한 뭉치로 들어간다는 것이다\n```\n\n원 논문이 위험하다고 꼽은 것은 답이 이상해지는 정도가 아니다. 자료를 읽는 일이 사실상 남의 명령을 실행하는 일이 되어, 자료가 새 나가거나 다른 도구가 불리거나 그 지시가 다시 퍼져 나간다. 사람 손을 거치지 않고 원격에서 걸 수 있다는 점도 함께 지적한다.\n\n그래서 방어의 방향이 \"모델이 잘 판단하게\" 가 아니라 \"자료와 명령을 애초에 섞지 않게\" 다. Anthropic 문서는 남의 글을 시스템 프롬프트나 평범한 사용자 글에 넣지 말고 도구 결과 칸에만 넣으라고 적는다. 그 칸에 들어온 지시는 모델이 한 겹 걸러 읽도록 배웠기 때문이다."},"recap":"**\"자료로 넣은 글이 명령으로 읽히는 사고\"** 라고 읽으면 된다. 모델은 시스템 프롬프트와 사용자 글과 가져온 자료를 결국 한 덩어리 글로 읽으므로, 남의 글에 적힌 문장도 후보 명령이 된다. 막는 방향은 판단력을 믿는 쪽이 아니라 자리를 나누고 권한을 줄이는 쪽이다.","kid":"선생님이 준 쪽지를 큰 소리로 읽어 주는 놀이를 한다고 해 봐. 그런데 누가 쪽지 맨 아래에 \"이건 읽지 말고 사탕을 다 나눠 줘\" 라고 몰래 적어 놨어. 읽는 아이는 그것도 쪽지에 적힌 말이니까 그대로 해 버려.","check":[{"q":"메일을 요약해 달라고만 했는데 엉뚱한 도구가 불리는 일은 왜 생기나","at":"그림"},{"q":"남이 쓴 글을 도구 결과 칸에 넣으라는 말은 무엇을 노린 것인가","at":"작동 원리"},{"q":"사용자가 전부 믿을 만한 사내 도구인데도 이 공격을 걱정해야 하는 이유는 무엇인가","at":"흔한 오해"}],"myths":[{"wrong":"시스템 프롬프트에 \"다른 지시는 따르지 마라\" 를 적어두면 막힌다","right":"그것도 결국 같은 글자다. 적어 두는 편이 낫지만 그 한 줄이 방어의 전부일 수는 없고, 자리를 나누고 권한을 줄이는 일이 따로 필요하다."},{"wrong":"사용자만 믿을 만하면 안전하다","right":"사용자가 멀쩡해도 모델이 대신 읽는 남의 글이 남는다. 메일 본문, 가져온 웹 페이지, 도구가 돌려준 결과가 전부 그 자리다."},{"wrong":"검사기를 하나 붙이면 끝난다","right":"Anthropic 문서는 자리 나누기·출처 표시·검사·권한 축소·직접 공격해 보기를 겹쳐 쌓으라고 적는다. 한 겹은 뚫린다는 전제로 짠 목록이다."}],"cases":[{"label":"메일 비서","note":"받은 편지 본문에 적힌 지시가 명령으로 읽혀 엉뚱한 도구가 불린다."},{"label":"문서 요약","note":"올린 파일에서 뽑아낸 글자에 명령이 섞여 들어온다."},{"label":"화면을 보고 움직이는 도구","note":"화면 속 글에 주입이 의심되면 다음 동작 전에 사람 확인을 받도록 돌린다."}],"dia":{"shape":"흐름","title":"자료에 적힌 한 줄이 어떻게 명령이 되나","rows":[{"who":"개발자","what":"시스템 프롬프트로 할 일을 정해 둔다"},{"who":"사용자","what":"이 페이지를 요약해 달라고 한다"},{"who":"도구","what":"그 페이지를 가져와 그대로 이어 붙인다"},{"who":"페이지","what":"본문에 \"앞의 지시는 무시하라\" 가 적혀 있다"},{"who":"모델","what":"셋을 한 덩어리 글로 읽는다"},{"who":"사용자","what":"요약 대신 남이 시킨 답이 돌아온다","back":true}],"sum":"모델에게는 자료와 명령이 같은 글자다. 넣어 준 글이 원래 지시를 밀어낸다"}},"ai--quantization":{"definition":"모델은 학습이 끝나면 커다란 숫자 뭉치로 남는다. 그 숫자를 보통 32비트나 16비트 소수로 담는데, 8비트나 4비트 정수로 바꿔 담으면 파일과 메모리가 그만큼 줄어든다. 줄인 만큼 눈금은 성겨진다.","name":"Quantum :: 정해진 한 덩어리\n-ize :: 그렇게 만든다\n= 이어진 값을 정해진 눈금 몇 개로 밀어 넣는다는 뜻. 눈금이 적을수록 가벼워진다","analogy":"1000색 색연필로 그린 그림을 12색으로 다시 그리는 일이다. 가방은 훨씬 가벼워지고, 비슷한 색끼리는 한 색으로 합쳐진다.","example":"받아 둔 모델이 노트북 메모리에 안 들어가서 아예 안 켜지던 그 순간에 손대는 값이다.","tryit":"그림 앱에서 색 수를 256색으로 낮춰 저장해 보라. 파일이 얼마나 줄고 어디가 뭉개지는지 한눈에 보인다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"양자화는 눈금을 다시 긋는 일이다. 넓게 퍼진 소수 값을 8비트 정수 256칸 안으로 밀어 넣고, 어느 실제 값이 몇 번 칸인지를 함께 적어 둔다. 부를 때는 칸 번호를 도로 값으로 펴서 계산한다.\n\n**첫 번째 손잡이는 몇 비트로 담을지다.** 문서는 8비트로 담으면 메모리가 절반, 4비트면 4분의 1로 준다고 적는다. 4비트에는 값이 종 모양으로 퍼져 있다고 보고 눈금을 그 모양에 맞춰 그은 방식이 따로 있고, 이미 줄인 값을 한 번 더 줄이는 이중 양자화를 켜면 숫자 하나당 0.4비트를 더 아낀다.\n\n**두 번째 손잡이는 어디까지 줄일지다.** 8비트 방식에는 문턱값이 있다. 계산 도중 나오는 값 가운데 문턱을 넘는 자리(이상치)는 16비트로 따로 곱하고 나머지만 8비트로 곱한다. 원 논문은 이렇게 99.9퍼센트가 넘는 값을 8비트로 곱하면서도 성능이 떨어지지 않았다고 적는다. 기본 문턱값은 6이고, 이 값을 0으로 내리면 답은 빨라지지만 정확도를 내주게 된다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **안 켜지던 모델 켜기** — 8비트로 담으면 메모리가 절반이라 장비를 안 바꾸고도 올라간다.\n- **큰 값만 남겨 두기** — 값이 유난히 큰 자리는 16비트로 따로 곱하고 나머지 99.9퍼센트를 8비트로 곱한다.\n- **줄인 위에 학습 붙이기** — 본체를 4비트로 담아 얼려 두고 얇은 학습용 조각만 붙이면 큰 장비 없이도 미세 조정이 된다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **양자화하면 빨라진다** — 문서가 줄여 준다고 적은 것은 메모리다. 속도는 방식과 장비에 따라 달라서 따로 재 봐야 한다.\n- **줄였다가 도로 펴면 원래대로다** — 펴는 것 자체는 되지만 문서는 그 과정에서 품질이 얼마쯤 상할 수 있다고 적는다.\n- **비트는 낮을수록 이득이다** — 1~2비트까지 내리는 방식은 눈금을 다시 재는 보정 과정을 따로 요구한다. 어디까지 내려도 되는지는 모델마다 다르다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **작은 모델일수록 더 흔들린다.** 문서는 작은 모델이나 미세 조정 중에는 8비트 문턱값을 기본값 6보다 낮춰야 할 수 있다고 적는다.\n- **전부 줄지는 않는다.** 자리가 모자라 CPU(연산을 맡는 칩) 쪽으로 넘긴 가중치는 32비트 그대로 남는다.\n- **재는 자리를 정해 두고 내려라.** 자릿수를 내린 뒤 무엇이 얼마나 나빠졌는지 볼 문제 묶음이 없으면, 상한 줄도 모르고 쓰게 된다."}],"figure":"```도해\n층: 자릿수를 줄이면 무엇이 줄고 무엇이 상하나\n16비트 :: 요즘 모델이 받아 놓는 기본. 원본에 가깝다\n8비트 :: 메모리가 절반. 값이 큰 자리는 16비트로 남긴다\n4비트 :: 메모리가 4분의 1. 눈금이 16칸뿐이라 반올림이 커진다\n= 한 칸 내릴 때마다 자리는 반으로 줄고, 표현할 수 있는 눈금도 함께 준다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 자릿수를 줄이지 않으면 무엇이 막히나\n16비트 그대로 || 4비트로 담아\n필요한 메모리 :: 네 배가 든다 || 4분의 1\n돌릴 수 있는 곳 :: 큰 장비만 || 노트북에서도\n안 들어가면 :: 아예 안 켜진다 || 일단 올라간다\n= 정확도를 조금 내주고 \"돌아가느냐 마느냐\" 를 바꾸는 맞바꿈이다\n```\n\n모델이 커지면서 막히는 자리는 계산 속도가 아니라 메모리다. 숫자가 다 올라가지 못하면 성능이 조금 나빠지는 게 아니라 아예 안 켜진다.\n\n양자화는 그 숫자들을 더 좁은 그릇에 옮겨 담아 문턱을 낮춘다. 문서는 이 기술을 \"정확도를 최대한 지키면서 자리를 줄이는 것\" 이라고 적는다. 지켜 준다고는 하지 않는다 — 얼마를 내주고 얼마를 얻는지는 내려 보고 재야 한다."},"recap":"**\"숫자의 자릿수를 깎아 모델을 가볍게 만드는 그 맞바꿈\"** 이라고 읽으면 된다. 8비트면 메모리가 절반, 4비트면 4분의 1이고, 줄어드는 것은 메모리이며 내주는 것은 정확도다. 어디까지 내려도 되는지는 모델마다 달라서 내려 보고 재는 수밖에 없다.","kid":"1000색 색연필로 그린 그림을 12색으로 다시 그린다고 생각해 봐. 가방은 훨씬 가벼워지고 그림도 무엇인지 알아볼 수 있어. 대신 하늘색이랑 물색처럼 비슷한 색은 하나로 합쳐져서 티가 나.","check":[{"q":"8비트로 담으면 메모리가 왜 절반이 되나","at":"그림"},{"q":"값이 유난히 큰 자리만 16비트로 남겨 두는 이유는 무엇인가","at":"작동 원리"},{"q":"4비트로 줄인 모델을 도로 펴면 원래 성능이 돌아오나","at":"흔한 오해"}],"myths":[{"wrong":"양자화하면 빨라진다","right":"문서가 줄여 준다고 적은 것은 메모리다. 속도는 방식과 장비에 따라 달라서 따로 재 봐야 한다."},{"wrong":"줄였다가 도로 펴면 원래대로다","right":"펴는 것 자체는 되지만 문서는 그 과정에서 품질이 얼마쯤 상할 수 있다고 적는다."},{"wrong":"비트는 낮을수록 이득이다","right":"1~2비트까지 내리는 방식은 눈금을 다시 재는 보정 과정을 따로 요구한다. 어디까지 내려도 되는지는 모델마다 다르다."}],"cases":[{"label":"안 켜지던 모델 켜기","note":"8비트로 담으면 메모리가 절반이라 장비를 안 바꾸고도 올라간다."},{"label":"큰 값만 남겨 두기","note":"값이 유난히 큰 자리는 16비트로 따로 곱하고 나머지 99.9퍼센트를 8비트로 곱한다."},{"label":"줄인 위에 학습 붙이기","note":"본체를 4비트로 담아 얼려 두고 얇은 학습용 조각만 붙이면 큰 장비 없이도 미세 조정이 된다."}],"dia":{"shape":"층","title":"자릿수를 줄이면 무엇이 줄고 무엇이 상하나","rows":[{"who":"16비트","what":"요즘 모델이 받아 놓는 기본. 원본에 가깝다"},{"who":"8비트","what":"메모리가 절반. 값이 큰 자리는 16비트로 남긴다"},{"who":"4비트","what":"메모리가 4분의 1. 눈금이 16칸뿐이라 반올림이 커진다"}],"sum":"한 칸 내릴 때마다 자리는 반으로 줄고, 표현할 수 있는 눈금도 함께 준다"}},"ai--rag":{"definition":"모델은 학습한 것만 안다. 우리 회사 규정이나 어제 올라온 문서는 모른다. 질문이 오면 먼저 그 문서를 찾아서 질문과 함께 넣어주면, 모델은 그 내용을 보고 답한다.","name":"Retrieval :: 찾아 꺼내 옴\nAugmented :: 보태어 늘린\nGeneration :: 글을 지어냄\n= 붙여 읽으면 \"찾아온 것을 보태서 짓기\". 짓기 앞에 찾기가 하나 붙은 것이 전부다","analogy":"개방형 시험. 외운 것만으로 답하게 하면 틀리거나 지어내지만, 교재를 펴놓고 답하게 하면 근거를 짚어 답한다.","example":"검색 결과 맨 위에 요약이 뜨면서 그 아래 출처 링크가 같이 달려 나오는 화면이 이 모양이다.","tryit":"검색창에 무엇이든 물어보고 맨 위 요약 아래를 보라. 무엇을 보고 쓴 것인지 출처가 함께 달려 있다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"준비 단계와 응답 단계가 나뉜다.\n\n```도해\n흐름: 문서 한 장이 답의 근거가 되기까지 무엇을 거치나\n쪼개기 :: 긴 문서를 문단 단위로 자른다\n임베딩 :: 조각마다 뜻을 벡터로 만든다\n저장 :: 벡터 DB 에 넣어둔다\n검색 :: 질문이 오면 가까운 조각을 꺼낸다\n= 앞의 셋은 미리 해두고, 마지막 하나만 질문할 때 한다\n```\n\n쪼개는 크기가 품질을 크게 좌우한다. 너무 크면 관계없는 내용이 섞여 들어오고, 너무 작으면 문맥이 끊겨서 무슨 말인지 알 수 없게 된다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 일반 LLM vs RAG vs Fine-tuning","body":"| | 일반 LLM | RAG | Fine-tuning |\n|---|---|---|---|\n| 지식 출처 | 학습 데이터 | 바깥 문서 | 재학습 데이터 |\n| 최신 정보 | 안 된다 | 문서만 고치면 된다 | 다시 학습해야 한다 |\n| 출처 표시 | 못 한다 | 조각까지 댄다 | 못 한다 |\n| 바꾸는 비용 | 바꿀 수 없다 | 낮다 | 높다 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **사내 문서 검색** — 규정, 매뉴얼, 회의록을 넣어두고 자연어로 묻는다.\n- **고객 문의 응대** — 제품 문서를 근거로 답하고 링크를 함께 준다.\n- **코드베이스 질문** — 저장소를 쪼개 넣어두면 \"이 함수 어디서 쓰나\"를 물을 수 있다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **RAG를 붙이면 환각이 사라진다** — 줄어들 뿐이다. 검색이 엉뚱한 문서를 가져오면 그 엉뚱한 문서를 근거로 그럴듯하게 지어낸다.\n- **문서를 다 넣으면 된다** — 문맥 창에 한계가 있어서 다 넣을 수 없다. 무엇을 골라 넣느냐가 이 방식의 전부다.\n- **검색이 키워드로 이뤄진다** — 뜻으로 찾는다. \"연차\"라고 물어도 \"휴가 규정\" 문서가 나오는 것이 이 방식의 장점이자, 엉뚱한 문서를 가져오는 이유다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **검색 품질이 답의 상한이다.** 모델을 바꾸기 전에 무엇을 가져왔는지부터 본다. 나쁜 답의 대부분은 나쁜 검색에서 나온다.\n- **권한을 검색 단계에서 거른다.** 문서를 다 넣어두면 권한 없는 사용자에게도 내용이 나갈 수 있다."}],"figure":"```도해\n흐름: 사내 규정을 물으면 무슨 일이 일어나나\n사용자 :: \"연차는 며칠인가요\" 라고 묻는다\n검색기 :: 질문을 벡터(뜻을 담은 숫자 목록)로 바꾼다\n벡터 DB :: 뜻이 가까운 문서 조각 세 개를 꺼낸다\n조립 :: 찾은 조각 + 원래 질문을 하나로 묶는다\n모델 :: 그 묶음만 보고 답을 만든다\n< 사용자 :: 출처가 붙은 답을 받는다\n= 모델을 다시 학습시키지 않고도 새 지식을 쓰게 만드는 방법이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 사내 문서를 모델에 물으려면 어떻게 하나\nRAG 없이 || RAG 로\n새 문서 반영 :: 재학습 필요 || 넣으면 바로\n출처 :: 알 수 없다 || 문서를 짚어준다\n비용 :: 학습 비용이 크다 || 검색 비용만\n= 지식을 모델 안에 넣지 않고 밖에 두는 것이 이 방식의 요점이다\n```\n\n모델을 우리 데이터로 다시 학습시키는 방법도 있지만 비싸고 오래 걸린다. 문서가 하나 바뀔 때마다 다시 학습할 수는 없다.\n\nRAG는 지식을 모델 밖에 둔다. 문서가 바뀌면 저장소만 갱신하면 되고, 답에 어느 문서를 봤는지 붙일 수 있어서 사람이 확인할 수 있다. [[Hallucination]]이 줄어드는 것도 지어낼 필요가 없어지기 때문이다."},"recap":"**\"펴 놓고 보면서 답하게 하는 그 개방형 시험\"** 이라고 읽으면 된다. 지식을 모델 밖에 두어 갱신과 출처 표시가 쉬워지고, 대신 검색 품질이 답의 품질을 정한다.","kid":"시험 볼 때 책을 못 펴면 외운 것만 쓰다가 헷갈리는 데서 대충 지어내지? 책을 펴 놓고 풀게 하면 해당하는 쪽을 찾아서 보고 쓰잖아. 이것도 묻는 말에 맞는 쪽부터 찾아 펴 놓고, 그 쪽을 보면서 답해.","check":[{"q":"답이 엉뚱하다면 모델과 검색 중 어디를 먼저 봐야 하나","at":"주의사항"},{"q":"문서를 통째로 넣지 못하는 이유는","at":"흔한 오해"},{"q":"문서 조각을 너무 작게 자르면 무엇이 문제가 되나","at":"작동 원리"}],"myths":[{"wrong":"RAG를 붙이면 환각이 사라진다","right":"줄어들 뿐이다. 검색이 엉뚱한 문서를 가져오면 그 엉뚱한 문서를 근거로 그럴듯하게 지어낸다."},{"wrong":"문서를 다 넣으면 된다","right":"문맥 창에 한계가 있어서 다 넣을 수 없다. 무엇을 골라 넣느냐가 이 방식의 전부다."},{"wrong":"검색이 키워드로 이뤄진다","right":"뜻으로 찾는다. \"연차\"라고 물어도 \"휴가 규정\" 문서가 나오는 것이 이 방식의 장점이자, 엉뚱한 문서를 가져오는 이유다."}],"cases":[{"label":"사내 문서 검색","note":"규정, 매뉴얼, 회의록을 넣어두고 자연어로 묻는다."},{"label":"고객 문의 응대","note":"제품 문서를 근거로 답하고 링크를 함께 준다."},{"label":"코드베이스 질문","note":"저장소를 쪼개 넣어두면 \"이 함수 어디서 쓰나\"를 물을 수 있다."}],"dia":{"shape":"흐름","title":"사내 규정을 물으면 무슨 일이 일어나나","rows":[{"who":"사용자","what":"\"연차는 며칠인가요\" 라고 묻는다"},{"who":"검색기","what":"질문을 벡터(뜻을 담은 숫자 목록)로 바꾼다"},{"who":"벡터 DB","what":"뜻이 가까운 문서 조각 세 개를 꺼낸다"},{"who":"조립","what":"찾은 조각 + 원래 질문을 하나로 묶는다"},{"who":"모델","what":"그 묶음만 보고 답을 만든다"},{"who":"사용자","what":"출처가 붙은 답을 받는다","back":true}],"sum":"모델을 다시 학습시키지 않고도 새 지식을 쓰게 만드는 방법이다"}},"ai--react":{"definition":"한 번에 답을 내놓는 대신, 무엇이 필요한지 생각하고, 도구를 하나 쓰고, 그 결과를 보고 다시 생각한다. 이름은 Reasoning과 Acting을 붙인 것이다.","name":"Reasoning :: 따져 생각함\nActing :: 실제로 해 봄\n= 두 낱말을 이어 붙여 만든 이름이다. 생각만도 행동만도 아니고 둘을 번갈아 한다는 뜻이다","analogy":"요리하면서 냉장고를 열어보는 것. 재료를 다 외운 채로 순서를 짜지 않고, 한 번 열어보고 있는 것에 맞춰 다음 손을 정한다.","example":"AI 가 답을 내기 전에 한 번 찾아보고, 결과가 시원찮자 검색어를 바꿔 다시 찾는 것을 그대로 보여준다.","tryit":"챗봇에 오늘 날씨를 물어보라. 답이 나오기 전에 \"찾아보는 중\" 같은 줄이 잠깐 뜨면 한 바퀴 돌고 있는 것이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"한 바퀴는 세 마디로 되어 있다.\n\n| 마디 | 하는 일 |\n|---|---|\n| **Thought** | 지금 무엇이 필요한지 말로 적는다 |\n| **Action** | 도구 하나를 고르고 부른다 |\n| **Observation** | 도구가 돌려준 결과를 읽는다 |\n\n이 세 마디가 목표에 닿을 때까지 반복된다. 필요한 게 다 모였다고 판단하면 도구를 부르는 대신 답을 내놓고 끝낸다.\n\n생각을 겉으로 적게 한다는 점이 이 방식의 특징이다. 판단을 글로 남기므로 나중에 기록을 열어보면 어느 판단에서 틀어졌는지 보이고, 도구를 잘못 고른 것인지 결과를 잘못 읽은 것인지도 구분할 수 있다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **사내 챗봇** — 남은 휴가 일수를 물으면 인사 시스템을 조회하고 그 값으로 답한다. 모델이 기억하던 값을 쓰지 않는다.\n- **자료 검색** — 한 번 검색해서 부족하면 검색어를 바꿔 다시 찾는다. 관찰한 결과가 다음 검색어를 정한다.\n- **여러 단계 계산** — 환율을 받아온 다음 그 값으로 금액을 계산한다. 앞 단계 결과가 없으면 뒤 단계를 시작하지 않는다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **ReAct는 모델 이름이다** — 모델이 아니라 모델을 부리는 방식이다. 같은 모델을 한 번에 답하게 할 수도 있고 ReAct로 돌게 할 수도 있다.\n- **ReAct를 쓰면 지어내기가 없어진다** — 줄어들 뿐이다. 도구를 안 부르고 넘어가거나 결과를 잘못 읽으면 틀린 답이 그대로 나간다.\n- **바퀴를 많이 돌수록 답이 좋아진다** — 한 바퀴마다 모델 호출 비용이 붙고, 방향을 잘못 잡으면 잘못된 채로 계속 돈다. 몇 바퀴까지 돌지 정해두는 편이 낫다."}],"figure":"```도해\n흐름: \"내일 서울 날씨 어때?\" 를 받으면 어떻게 답하나\n사용자 :: 내일 서울 날씨를 묻는다\n생각 :: 실시간 정보가 필요하다고 적는다\n행동 :: 날씨 API 를 부른다\n관찰 :: \"맑음, 15도\" 라는 결과를 읽는다\n@ 다시 생각으로 :: 다 모였으면 답하고, 아니면 한 바퀴 더\n= 생각과 행동과 관찰이 한 바퀴고, 필요한 만큼 돈다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 실시간 정보를 물으면 무엇이 달라지나\n그냥 LLM || ReAct 로\n모르는 값 :: 못 한다고 답 || 도구로 찾는다\n여러 단계 :: 한 번에 추측 || 나눠서 진행\n중간 오류 :: 그대로 나감 || 보고 고친다\n= 모르는 것을 지어내는 대신 알아보러 가게 만드는 구조다\n```\n\n학습해둔 것만으로 답하는 모델은 지금 이 순간의 값을 모른다. 내일 날씨나 방금 바뀐 재고 수량을 물으면 확인할 수 없다고 답하거나, 더 나쁘면 그럴듯한 숫자를 지어낸다.\n\nReAct는 답하기 전에 한 단계를 끼워 넣는다. 무엇이 필요한지 먼저 말로 적게 하고, 그다음에 도구를 부르게 한다. 도구가 돌려준 값을 보고 다시 판단하므로 한 번에 맞힐 필요가 없고, 중간에 어긋난 것을 알아채면 방향을 바꿀 수 있다."},"recap":"**\"한 번 열어 보고 다음 손을 정하는 그 되풀이\"** 라고 읽으면 된다. 모르는 값을 지어내는 대신 도구로 알아보게 만들고, 판단을 글로 남기게 해서 어디서 어긋났는지 되짚을 수 있게 한다.","kid":"요리할 때 냉장고에 뭐가 들었는지 다 외우고 시작하지는 않지? 한 번 열어 보고, 있는 걸 보고 나서 다음에 뭘 할지 정하잖아. 이것도 한 번 알아보고 그 결과를 본 다음에 다음 할 일을 정하고, 다 될 때까지 그걸 되풀이해.","check":[{"q":"그냥 LLM에게 내일 날씨를 물으면 왜 답을 못 하나","at":"해결하는 문제"},{"q":"검색 한 번으로 부족했을 때 다음 검색어는 무엇을 근거로 정해지나","at":"실제 사례"},{"q":"바퀴 수에 한도를 두지 않으면 어떤 일이 생기나","at":"흔한 오해"}],"myths":[{"wrong":"ReAct는 모델 이름이다","right":"모델이 아니라 모델을 부리는 방식이다. 같은 모델을 한 번에 답하게 할 수도 있고 ReAct로 돌게 할 수도 있다."},{"wrong":"ReAct를 쓰면 지어내기가 없어진다","right":"줄어들 뿐이다. 도구를 안 부르고 넘어가거나 결과를 잘못 읽으면 틀린 답이 그대로 나간다."},{"wrong":"바퀴를 많이 돌수록 답이 좋아진다","right":"한 바퀴마다 모델 호출 비용이 붙고, 방향을 잘못 잡으면 잘못된 채로 계속 돈다. 몇 바퀴까지 돌지 정해두는 편이 낫다."}],"cases":[{"label":"사내 챗봇","note":"남은 휴가 일수를 물으면 인사 시스템을 조회하고 그 값으로 답한다. 모델이 기억하던 값을 쓰지 않는다."},{"label":"자료 검색","note":"한 번 검색해서 부족하면 검색어를 바꿔 다시 찾는다. 관찰한 결과가 다음 검색어를 정한다."},{"label":"여러 단계 계산","note":"환율을 받아온 다음 그 값으로 금액을 계산한다. 앞 단계 결과가 없으면 뒤 단계를 시작하지 않는다."}],"dia":{"shape":"흐름","title":"\"내일 서울 날씨 어때?\" 를 받으면 어떻게 답하나","rows":[{"who":"사용자","what":"내일 서울 날씨를 묻는다"},{"who":"생각","what":"실시간 정보가 필요하다고 적는다"},{"who":"행동","what":"날씨 API 를 부른다"},{"who":"관찰","what":"\"맑음, 15도\" 라는 결과를 읽는다"}],"sum":"생각과 행동과 관찰이 한 바퀴고, 필요한 만큼 돈다","loop":{"who":"다시 생각으로","what":"다 모였으면 답하고, 아니면 한 바퀴 더"}}},"ai--reranking":{"definition":"RAG에서 문서를 찾을 때 한 번에 정확히 고르려 하지 않는다. 빠른 검색으로 후보를 넉넉히 뽑아둔 다음, 그 안에서만 정밀한 모델로 다시 채점해 위에서 몇 건만 남긴다.","name":"Re :: 다시 한 번\nRanking :: 순위를 매김\n= 붙여 읽으면 \"다시 순위 매기기\". 다시 찾아오는 게 아니라 뽑아온 것의 줄만 고쳐 세운다","analogy":"서류 심사와 면접. 서류로는 수백 명을 빠르게 걸러 열 명을 남기고, 면접은 그 열 명만 한 명씩 오래 본다. 면접을 수백 명에게 할 수는 없다.","example":"중고 거래 앱에서 검색하면 제목만 닮은 매물이 잔뜩 뜨고 진짜 찾던 것은 아래에 묻혀 있다.","tryit":"중고 거래 앱에서 무언가를 검색해 보라. 제목만 닮은 것이 위에 몰려 있는 그 목록이 줄을 다시 세울 자리다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"두 단계가 점수를 매기는 방식이 다르다. 벡터 검색은 문서를 미리 숫자 벡터로 바꿔 저장해두고, 질문도 벡터로 바꿔 둘 사이의 거리만 잰다. 문서 쪽 계산이 이미 끝나 있어서 수만 건을 순식간에 훑을 수 있지만, 질문과 문서를 따로 계산했기 때문에 둘 사이의 관계는 대략적으로만 반영된다.\n\n리랭커는 질문과 문서를 한 쌍으로 묶어 모델에 함께 넣고 점수를 낸다. 이런 방식을 Cross-Encoder라고 한다. 질문이 정해진 다음에야 계산할 수 있으니 미리 색인해둘 수 없고, 그래서 후보 하나하나에 시간이 든다. 1차가 0.1초라면 2차는 0.5초 정도가 붙는다.\n\n정리하면 1차는 후보를 놓치지 않기 위한 단계, 2차는 그 후보들 사이의 순서를 바로잡기 위한 단계다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 두 단계가 하는 일","body":"| | 벡터 검색 | 리랭킹 |\n|---|---|---|\n| 보는 대상 | 색인된 문서 전체 | 1차가 뽑은 몇 건 |\n| 계산 | 미리 만든 벡터끼리 거리 | 질문과 문서를 붙여 채점 |\n| 걸리는 시간 | 0.1초 | 0.5초 |\n| 잘하는 일 | 놓치지 않고 넓게 뽑기 | 그 안에서 정확히 고르기 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **사내 규정 검색** — 비슷한 문장이 여러 규정에 흩어져 있을 때 질문에 실제로 답하는 조항을 위로 올린다.\n- **컨텍스트 아끼기** — 10건을 다 넣는 대신 3건만 넣어 토큰을 줄이고 엉뚱한 문서에 끌려가는 것을 막는다.\n- **제목만 닮은 문서가 많은 문서고** — 겉모습이 비슷해 위에 몰린 문서들을 내용 기준으로 다시 세운다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **리랭킹은 검색을 한 번 더 하는 것이다** — 다시 찾아오지 않는다. 1차가 뽑아온 목록 안에서 순서만 바꾸므로 1차에서 빠진 문서는 리랭킹으로도 올라오지 않는다.\n- **벡터 검색 점수가 높으면 답에 가깝다** — 그 점수는 질문과 문서가 얼마나 닮았는지에 가깝다. 질문과 닮은 문서와 질문에 답하는 문서는 다를 수 있고, 그 차이를 리랭커가 다시 본다.\n- **리랭커도 결국 벡터끼리 비교하는 것 아닌가** — 질문과 문서를 한 쌍으로 묶어 모델에 같이 넣고 점수를 낸다. 미리 계산해둘 수 없어 느린 대신 둘 사이의 관계를 직접 본다."}],"figure":"```도해\n흐름: 질문 하나가 들어오면 문서는 어떤 순서로 걸러지나\n질문 :: \"육아휴직 기간은?\" 이 들어온다\n벡터 검색 :: 수만 건에서 비슷해 보이는 10건을 0.1초에 뽑는다\n리랭커 :: 그 10건을 질문과 짝지어 하나씩 다시 채점한다\n순위 :: 새 점수 순으로 세워 위에서 3건만 남긴다\nLLM :: 남은 3건만 읽고 답을 만든다\n= 넓게 훑는 일과 꼼꼼히 보는 일을 다른 단계에 나눠 맡긴다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 벡터 검색 점수만 보고 위에서 자르면 어떻게 되나\n리랭킹 없이 || 리랭킹으로\n점수 차이 :: 0.85 대 0.83 || 0.95 대 0.70\n진짜 답 :: 2위에 묻힌다 || 1위로 올라온다\n읽는 문서 :: 애매한 10건 || 확실한 3건\n= 넓게 뽑는 일과 정확히 고르는 일은 잘하는 모델이 다르다\n```\n\n벡터 검색은 빠르지만 점수 차이가 촘촘하다. 1위가 0.85이고 2위가 0.83이면 이 순서를 믿을 근거가 별로 없다. 실제로는 2위 문서가 질문에 정확히 답하고 있는데도 1위 아래에 묻히는 일이 생긴다.\n\n문서를 많이 넘겨서 해결할 수도 없다. 10건을 그대로 LLM에 넣으면 토큰을 더 쓰는 데다 관련 없는 문서가 답을 흐린다. 리랭킹은 후보를 넉넉히 뽑는 것과 정확히 고르는 것을 두 단계로 나눠서, 1차에서는 놓치지 않는 데만 집중하고 고르는 일은 2차에 맡긴다."},"recap":"**\"뽑아온 것을 다시 줄 세우는 그 면접\"** 이라고 읽으면 된다. 1차는 놓치지 않는 데 집중하고 2차는 그 안에서 고르는 데 집중하도록 역할을 나눈 것이다. 대신 1차에서 빠진 문서는 되살릴 수 없으므로 후보를 넉넉히 뽑아두는 쪽이 중요해진다.","kid":"반 대표를 뽑을 때 먼저 종이로 쫙 훑어 열 명만 남기고, 그다음에 그 열 명만 한 명씩 불러서 자세히 물어보지? 여기서도 우선 빠르게 열 개를 골라 놓고, 그 열 개만 다시 꼼꼼히 봐서 줄을 새로 세워. 대신 처음 열 명에 못 든 애는 아무리 잘해도 부르지 않으니까, 처음에 넉넉히 남겨 둬야 해.","check":[{"q":"1차 검색에서 아예 뽑히지 않은 문서를 리랭킹이 살릴 수 없는 이유는","at":"흔한 오해"},{"q":"벡터 검색 점수만 보고 위에서 3건을 자르면 무엇을 놓치게 되나","at":"해결하는 문제"},{"q":"리랭커가 벡터 검색보다 느린 이유는","at":"작동 원리"}],"myths":[{"wrong":"리랭킹은 검색을 한 번 더 하는 것이다","right":"다시 찾아오지 않는다. 1차가 뽑아온 목록 안에서 순서만 바꾸므로 1차에서 빠진 문서는 리랭킹으로도 올라오지 않는다."},{"wrong":"벡터 검색 점수가 높으면 답에 가깝다","right":"그 점수는 질문과 문서가 얼마나 닮았는지에 가깝다. 질문과 닮은 문서와 질문에 답하는 문서는 다를 수 있고, 그 차이를 리랭커가 다시 본다."},{"wrong":"리랭커도 결국 벡터끼리 비교하는 것 아닌가","right":"질문과 문서를 한 쌍으로 묶어 모델에 같이 넣고 점수를 낸다. 미리 계산해둘 수 없어 느린 대신 둘 사이의 관계를 직접 본다."}],"cases":[{"label":"사내 규정 검색","note":"비슷한 문장이 여러 규정에 흩어져 있을 때 질문에 실제로 답하는 조항을 위로 올린다."},{"label":"컨텍스트 아끼기","note":"10건을 다 넣는 대신 3건만 넣어 토큰을 줄이고 엉뚱한 문서에 끌려가는 것을 막는다."},{"label":"제목만 닮은 문서가 많은 문서고","note":"겉모습이 비슷해 위에 몰린 문서들을 내용 기준으로 다시 세운다."}],"dia":{"shape":"흐름","title":"질문 하나가 들어오면 문서는 어떤 순서로 걸러지나","rows":[{"who":"질문","what":"\"육아휴직 기간은?\" 이 들어온다"},{"who":"벡터 검색","what":"수만 건에서 비슷해 보이는 10건을 0.1초에 뽑는다"},{"who":"리랭커","what":"그 10건을 질문과 짝지어 하나씩 다시 채점한다"},{"who":"순위","what":"새 점수 순으로 세워 위에서 3건만 남긴다"},{"who":"LLM","what":"남은 3건만 읽고 답을 만든다"}],"sum":"넓게 훑는 일과 꼼꼼히 보는 일을 다른 단계에 나눠 맡긴다"}},"ai--routing":{"definition":"같은 시스템 안에 메뉴 안내, 규정 검색, 급여 조회처럼 서로 다른 처리자가 여럿 있으면 누가 맡을지부터 정해야 한다. 라우팅은 그 판단만 맡고 답은 만들지 않는다.","name":"Route :: 어느 길로 갈지\n= 길을 뜻하는 route 에서 온 말이다. 길만 정해 줄 뿐 도착한 데서 무슨 일을 할지는 정하지 않는다","analogy":"회사 대표번호의 자동 교환. 용건을 듣고 담당 부서로 이어주기만 하고, 상담은 그쪽에서 한다.","example":"은행 앱 챗봇에 카드 분실이라고 적으면 카드 안내로, 대출이라고 적으면 대출 안내로 갈린다.","tryit":"은행 앱 챗봇에 \"카드 분실\" 과 \"대출\" 을 한 번씩 쳐 보라. 같은 창인데 뒤에서 다른 안내로 갈린다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"```도해\n층: 어느 처리자인지 무엇으로 가리나\n규칙 :: 정해둔 낱말이 있으면 바로 그쪽으로\n분류 모델 :: 문장의 의도를 이름 하나로 가른다\n의미 유사도 :: 처리자 설명과 얼마나 가까운지 잰다\n모름 :: 어느 쪽도 확실하지 않을 때 가는 자리\n= 위쪽일수록 싸고 확실하고, 아래로 갈수록 넓게 잡는다\n```\n\n분류 결과에는 신뢰도가 따라온다. 기준을 정해두고 그 아래면 어느 처리자에게도 넘기지 않는다. 애매한 것을 억지로 보내는 것보다 되묻는 편이 낫기 때문이다.\n\n처리자를 고른 다음에도 바로 넘기지 않을 수 있다. 그 사용자에게 조회 권한이 있는지, 지금이 처리 가능한 시간인지, 입력에 개인정보가 섞여 있지는 않은지를 라우터 자리에서 먼저 본다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교","body":"| | Routing | Orchestration |\n|---|---|---|\n| 하는 일 | 하나를 고른다 | 여럿을 부린다 |\n| 결과 합치기 | 없다 | 있다 |\n| 요청 모양 | 한 가지 용건 | 여러 용건이 섞임 |\n| 복잡도 | 규칙표 하나 | 순서와 예외까지 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **권한 확인** — 급여 쪽으로 갈 요청이라도 조회 권한이 없으면 처리자에 닿기 전에 막고 안내로 돌린다.\n- **모름 처리** — 분류 신뢰도가 기준 아래면 아무에게도 넘기지 않고 무엇을 원하는지 되묻는다.\n- **처리자 추가** — 새 처리자를 붙일 때 규칙표에 한 줄만 더하고 기존 코드는 그대로 둔다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **라우터가 답을 만든다** — 고르기만 한다. 답의 내용은 고른 처리자에게 달려 있고, 라우터가 잘못 고르면 좋은 처리자가 있어도 엉뚱한 답이 나온다.\n- **라우팅과 오케스트레이션은 같은 말이다** — 라우터는 하나를 골라 넘기고 끝난다. 여러 처리자를 차례로 부르고 결과를 합치는 것은 오케스트레이터의 일이다.\n- **애매하면 가장 가까운 쪽으로 보내면 된다** — 억지로 보내면 엉뚱한 답이 확신에 찬 말투로 돌아온다. 기준 아래는 모름으로 따로 빼서 되묻는 편이 낫다."}],"figure":"```도해\n흐름: \"주소 변경하고 싶어\" 는 어디로 가나\n입력 :: 사용자가 문장 하나를 던진다\n분류기 :: 무엇에 대한 말인지 가른다. navigation\n신뢰도 :: 기준보다 낮으면 모름 쪽으로 돌린다\n규칙표 :: navigation 에 걸어둔 처리자를 꺼낸다\n처리자 :: 그 하나만 실행되어 답을 만든다\n= 라우터는 답을 만들지 않는다. 누가 만들지만 정한다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 요청을 가려 보내지 않으면 어떻게 되나\n라우터 없이 || 라우터로\n응답 :: 전부 답한다 || 하나만 답한다\n못 맞혔을 때 :: 못 찾는다고 답 || 맞는 쪽이 답\n처리자 추가 :: 코드를 고친다 || 규칙 한 줄\n= 답할 수 있는 곳이 여럿이면 고르는 자리가 따로 있어야 한다\n```\n\n\"급여명세서 보고 싶어\"라는 말이 메뉴 안내 담당에게 가면 못 찾는다는 답이 돌아온다. 반대로 모든 처리자가 각자 답하면 세 개의 답이 한꺼번에 나와서 어느 것을 봐야 할지 알 수 없다.\n\n라우터는 그 앞에 서서 하나만 고른다. 처리자를 새로 붙일 때도 규칙표에 한 줄을 더하면 되고, 부르는 쪽 코드는 건드리지 않는다."},"recap":"**\"누가 맡을지만 정하고 빠지는 그 교환대\"** 라고 읽으면 된다. 답을 만들지 않으므로 잘 고르는 것과 못 고를 때 모름으로 빼는 것이 전부이고, 용건이 여러 개 섞인 요청은 여기서 끝나지 않는다.","kid":"회사에 전화하면 받는 분이 용건만 듣고 담당하는 데로 이어 주지? 그분이 대답을 해 주지는 않아, 어디로 넘길지만 정하고 빠져. 그래서 잘못 이어 주면 넘어간 쪽이 아무리 잘 알아도 엉뚱한 답이 와.","check":[{"q":"처리자 셋이 한 질문에 저마다 답하면 사용자에게 무엇이 문제인가","at":"해결하는 문제"},{"q":"급여 요청인 걸 맞게 가렸는데도 답을 못 받는 경우가 있는 이유는","at":"작동 원리"},{"q":"\"주소도 바꾸고 육아휴직도 신청하고 싶어\"가 라우터만으로 안 되는 이유는","at":"비교"}],"myths":[{"wrong":"라우터가 답을 만든다","right":"고르기만 한다. 답의 내용은 고른 처리자에게 달려 있고, 라우터가 잘못 고르면 좋은 처리자가 있어도 엉뚱한 답이 나온다."},{"wrong":"라우팅과 오케스트레이션은 같은 말이다","right":"라우터는 하나를 골라 넘기고 끝난다. 여러 처리자를 차례로 부르고 결과를 합치는 것은 오케스트레이터의 일이다."},{"wrong":"애매하면 가장 가까운 쪽으로 보내면 된다","right":"억지로 보내면 엉뚱한 답이 확신에 찬 말투로 돌아온다. 기준 아래는 모름으로 따로 빼서 되묻는 편이 낫다."}],"cases":[{"label":"권한 확인","note":"급여 쪽으로 갈 요청이라도 조회 권한이 없으면 처리자에 닿기 전에 막고 안내로 돌린다."},{"label":"모름 처리","note":"분류 신뢰도가 기준 아래면 아무에게도 넘기지 않고 무엇을 원하는지 되묻는다."},{"label":"처리자 추가","note":"새 처리자를 붙일 때 규칙표에 한 줄만 더하고 기존 코드는 그대로 둔다."}],"dia":{"shape":"흐름","title":"\"주소 변경하고 싶어\" 는 어디로 가나","rows":[{"who":"입력","what":"사용자가 문장 하나를 던진다"},{"who":"분류기","what":"무엇에 대한 말인지 가른다. navigation"},{"who":"신뢰도","what":"기준보다 낮으면 모름 쪽으로 돌린다"},{"who":"규칙표","what":"navigation 에 걸어둔 처리자를 꺼낸다"},{"who":"처리자","what":"그 하나만 실행되어 답을 만든다"}],"sum":"라우터는 답을 만들지 않는다. 누가 만들지만 정한다"}},"ai--semantic-search":{"definition":"\"급여일\"로 물어도 \"임금 지급일\"이라고 적힌 문서가 걸린다. 글자를 맞춰보는 게 아니라 뜻을 숫자로 바꿔 거리를 재기 때문이다.","name":"Semantic :: 뜻에 관한\nSearch :: 찾기\n= 붙여 읽으면 \"뜻으로 찾기\". 맞춰 보는 대상이 글자에서 뜻으로 옮겨 갔다는 말이다","analogy":"사서에게 묻는 것. \"아이 키우는 데 필요한 책\"이라고만 해도 제목에 그 말이 없는 책을 꺼내 온다.","example":"아기 태우는 자전거 의자라고 쳤는데 유아 안장이라고만 적힌 글이 걸려 나오는 그 일이다.","tryit":"검색창에 \"아이 키우려고 쉬는 제도\" 라고 풀어서 쳐 보라. 치지도 않은 \"육아휴직\" 이 결과 맨 위에 뜬다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"```도해\n층: 유사도 점수는 어디에서 갈리나\n0.7 위 :: 관련 있다고 보고 그대로 쓴다\n0.5 에서 0.7 :: 애매하다. 참고로만 두거나 버린다\n0.5 아래 :: 관련 없다고 보고 버린다\n= 문턱을 낮추면 엉뚱한 문서가 답의 근거로 섞여 들어온다\n```\n\n거리가 가까운 순서는 언제나 매겨진다. 전혀 관련 없는 문서라도 1등은 나온다는 뜻이다. 그래서 점수 문턱을 정해두고 그 아래는 아예 버린다.\n\n의미 검색만으로 안 되는 자리도 있다. \"제32조\"처럼 그 글자가 정확히 필요한 질문은 낱말 검색이 낫다. 그래서 의미 검색을 주로 두고 낱말이 정확히 들어맞은 문서에 점수를 얹는 방식을 함께 쓴다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 낱말 검색 vs 의미 검색","body":"| | 낱말 검색 | 의미 검색 |\n|---|---|---|\n| 맞춰보는 것 | 글자 | 뜻 |\n| 동의어 | 못 찾는다 | 찾는다 |\n| 오타 | 못 찾는다 | 어느 정도 견딘다 |\n| 속도 | 매우 빠르다 | 빠르다 |\n| 드는 것 | 거의 없다 | 벡터 DB 가 필요하다 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **사내 규정 검색** — \"아이 키우기 위한 휴가\"라고 물어도 육아휴직 조항이 걸린다.\n- **말 바꿔 묻기** — \"돈 받는 날은?\"이라고 물어도 급여일 조항으로 이어진다.\n- **오타 섞인 질문** — \"육아휴지\"라고 쳐도 육아휴직 문서가 위에 올라온다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **의미 검색은 AI 가 질문을 이해하는 것이다** — 이해가 아니라 거리 계산이다. 질문과 문서를 숫자 배열로 바꿔 가까운 것을 고를 뿐이다.\n- **의미 검색이 낱말 검색보다 항상 낫다** — \"제32조\"처럼 그 글자가 정확히 필요한 질문에는 낱말 검색이 낫다. 그래서 둘을 같이 쓴다.\n- **유사도 1등이면 답이 거기 있다** — 가장 가까운 문서를 골랐다는 뜻일 뿐이다. 문턱을 두지 않으면 0.3짜리 문서도 1등이 된다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **문턱값을 정해두지 않으면 항상 무언가가 걸린다.** 순위는 언제나 매겨지므로 몇 점 아래는 버린다고 정해야 한다.\n- **아주 짧은 말은 잘 안 잡힌다.** 조사나 한 글자짜리 낱말에는 담긴 뜻이 적어서 거리 계산이 흔들린다."}],"figure":"```도해\n흐름: 급여일을 물으면 무슨 계산으로 문서를 고르나\n질문 :: 급여일이 언제냐는 문장이 들어온다\n임베딩 :: 그 문장을 숫자 배열로 바꾼다\n문서 벡터 :: 문서들도 미리 같은 방식으로 바꿔 두었다\n거리 재기 :: 질문과 각 문서 사이의 거리를 잰다\n< 결과 :: 가까운 순으로 위에서 몇 개만 돌려준다\n= 글자를 맞춰본 적이 없다. 거리만 쟀다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 질문에 없는 낱말로 적힌 문서는 어떻게 되나\n낱말 검색 || 의미 검색\n동의어 :: 임금은 못 찾음 || 같이 걸린다\n말 바꿔 묻기 :: 0건 || 뜻으로 찾는다\n오타 :: 0건 || 어느 정도 견딘다\n= 찾는 기준을 글자에서 뜻으로 옮긴 것이다\n```\n\n\"급여일이 언제죠?\"라고 물었는데 문서에는 \"임금 지급일은 25일입니다\"라고 적혀 있으면, 글자를 맞춰보는 검색은 이 문서를 놓친다. \"아이 키우려고 쉬고 싶은데요\"라고 물으면 \"육아휴직\"이라는 낱말이 질문에 없어서 역시 못 찾는다. \"육아휴지\"처럼 한 글자만 틀려도 결과가 0건이 된다.\n\n의미 검색은 글자 대신 뜻을 비교한다. 질문과 문서를 같은 방식으로 숫자 배열로 바꾸면 뜻이 가까운 것끼리 배열도 가까워진다. 그래서 \"급여\"와 \"임금\"과 \"월급\"이 한자리에 모인다."},"recap":"**\"글자 말고 뜻을 맞춰 보는 그 찾기\"** 라고 읽으면 된다. 그래서 낱말이 다르거나 오타가 섞여도 찾아낸다. 다만 가까운 것을 고를 뿐이라 문턱을 두지 않으면 관련 없는 문서도 1등이 된다.","kid":"도서관에서 \"아이 키울 때 보는 책 있어요?\" 하고 물으면 제목에 그 말이 하나도 없는 책을 꺼내다 주지? 네가 쓴 낱말이 아니라 무슨 얘기를 찾는지를 보고 골라 주니까 그래. 그래서 글자를 좀 틀리게 써도 대충 알아듣고 꺼내 줘.","check":[{"q":"\"임금 지급일\"이라고만 적힌 문서를 \"급여일\"로 검색해 찾을 수 있는 이유는","at":"해결하는 문제"},{"q":"\"제32조\"를 찾을 때 낱말 검색을 같이 돌리는 이유는","at":"작동 원리"},{"q":"유사도 0.3짜리 문서가 결과 1등으로 올라오는 일이 왜 생기나","at":"흔한 오해"}],"myths":[{"wrong":"의미 검색은 AI 가 질문을 이해하는 것이다","right":"이해가 아니라 거리 계산이다. 질문과 문서를 숫자 배열로 바꿔 가까운 것을 고를 뿐이다."},{"wrong":"의미 검색이 낱말 검색보다 항상 낫다","right":"\"제32조\"처럼 그 글자가 정확히 필요한 질문에는 낱말 검색이 낫다. 그래서 둘을 같이 쓴다."},{"wrong":"유사도 1등이면 답이 거기 있다","right":"가장 가까운 문서를 골랐다는 뜻일 뿐이다. 문턱을 두지 않으면 0.3짜리 문서도 1등이 된다."}],"cases":[{"label":"사내 규정 검색","note":"\"아이 키우기 위한 휴가\"라고 물어도 육아휴직 조항이 걸린다."},{"label":"말 바꿔 묻기","note":"\"돈 받는 날은?\"이라고 물어도 급여일 조항으로 이어진다."},{"label":"오타 섞인 질문","note":"\"육아휴지\"라고 쳐도 육아휴직 문서가 위에 올라온다."}],"dia":{"shape":"흐름","title":"급여일을 물으면 무슨 계산으로 문서를 고르나","rows":[{"who":"질문","what":"급여일이 언제냐는 문장이 들어온다"},{"who":"임베딩","what":"그 문장을 숫자 배열로 바꾼다"},{"who":"문서 벡터","what":"문서들도 미리 같은 방식으로 바꿔 두었다"},{"who":"거리 재기","what":"질문과 각 문서 사이의 거리를 잰다"},{"who":"결과","what":"가까운 순으로 위에서 몇 개만 돌려준다","back":true}],"sum":"글자를 맞춰본 적이 없다. 거리만 쟀다"}},"ai--structured-output":{"definition":"글로 받으면 사람이 읽기는 좋아도 기계가 쓰기는 나쁘다. 괄호 하나가 빠지거나 칸 이름이 바뀌면 그 뒤가 통째로 멈춘다. 그래서 받을 모양을 먼저 적어 주고, 모델이 그 모양 밖으로 나가지 못하게 막는다.","name":"Structured :: 모양이 정해진\nOutput :: 내놓는 것\n= 붙여 읽으면 \"모양이 정해진 내놓기\". 무엇을 말할지가 아니라 어디에 담을지를 정한다","analogy":"칸이 그려진 서류 양식. 빈 종이에 쓰라고 하면 사람마다 제각각이지만, 칸이 있으면 칸 밖으로 못 나간다.","example":"영수증 사진을 올리면 가게 이름과 금액이 칸칸이 채워져 나오는 앱이 이 방식으로 만들어져 있다.","tryit":"AI 에게 \"결과를 표로만 답해\" 라고 부탁해 보라. 대체로 지켜지지만 가끔 어긋난다. 그 가끔을 없애는 것이 이 방식이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"적어 준 모양은 말로 전해지는 것이 아니라, 낱말을 고르는 단계에 거는 제약으로 바뀐다. 지금 자리에서 나올 수 있는 낱말만 후보로 남기고 나머지는 아예 0 으로 만든다. 문자열 칸을 쓰는 중이면 따옴표를 닫기 전에는 다른 칸으로 못 넘어간다.\n\n그래서 \"어긴 답이 나왔는데 못 잡았다\" 가 아니라 어긴 답 자체가 만들어지지 않는다. 대신 모양이 복잡할수록 틀을 짜는 준비에 시간이 더 걸리고, 쓸 수 있는 형식에도 제한이 있다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **문서에서 값 뽑기** — 계약서에서 금액·날짜·상대 이름을 정해진 칸으로 받는다.\n- **분류 붙이기** — 문의 글을 정해 둔 항목 중 하나로만 답하게 한다. 없는 항목을 지어낼 수 없다.\n- **화면 그리기** — 칸마다 다른 모양으로 그려야 할 때, 칸이 늘 있다는 보장이 필요하다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **모양이 맞으면 내용도 맞다** — 아니다. 모양만 보장한다. 빈칸을 못 두게 해 놓으면 모르는 값도 그럴듯하게 채워 넣는다.\n- **모양을 정하면 절대 안 깨진다** — 길이 한도에 걸려 중간에 끊기면 반쪽짜리가 나온다. 거절할 때도 이 모양을 안 따를 수 있다.\n- **무조건 모양을 정해 두는 게 낫다** — 사람이 읽을 글까지 칸에 가두면 답이 딱딱해진다. 기계가 읽을 것에만 건다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **빈칸을 허용해 둔다.** 모든 칸을 반드시 채우게 하면, 원문에 없는 값도 지어내서 채운다.\n- **모양이 맞아도 값은 검사한다.** 날짜 칸에 날짜 모양의 아무 날이나 들어올 수 있다."}],"figure":"```도해\n흐름: 답이 언제나 같은 모양으로 나오게 하려면 무엇을 하나\n앱 :: 받고 싶은 칸 이름과 자료형을 적어 보낸다\n모델 :: 그 모양이 낱말 고르기를 가두는 틀이 된다\n뽑기 :: 틀을 벗어나는 낱말은 후보에서 아예 빠진다\n< 앱 :: 뜯어내지 않고 바로 읽을 수 있는 답을 받는다\n= 잘 부탁하는 것이 아니라, 틀 밖으로 나갈 수 없게 만드는 것이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 답을 글로 받으면 무엇이 번거로운가\n글로 받으면 || 모양을 정하면\n읽어 쓰기 :: 뜯어내야 한다 || 바로 읽는다\n어긋날 때 :: 다시 물어본다 || 어긋나지 않는다\n칸 빠짐 :: 가끔 빠진다 || 반드시 들어간다\n= 형식이 틀리는 일이 없어지면 다시 묻는 길을 지울 수 있다\n```\n\n시키는 말로만 부탁하면 대체로 지켜진다. 문제는 \"대체로\" 다. 백 번에 한 번 칸 이름이 바뀌거나 앞에 설명 한 줄이 붙으면, 그것을 읽던 쪽이 멈춘다. 그래서 다시 묻는 길과 어긋난 답을 고치는 길을 따로 만들게 된다.\n\n모양을 미리 정해 두면 그 길이 통째로 없어진다. 어긋난 답이 나올 수 없으므로 다시 묻지 않고, 어느 칸이 있을지 확실하므로 없을 때를 대비한 갈래도 필요 없다."},"recap":"**\"칸이 그려진 그 서류 양식\"** 이라고 읽으면 된다. 모양은 보장되지만 내용은 보장되지 않는다. 뜯어내고 다시 묻는 길을 지워 주는 것이 이 방식의 값이다.","kid":"받아쓰기 공책에 칸이 그려져 있으면 글자가 칸 밖으로 못 나가지? 빈 종이에 쓰면 삐뚤빼뚤해져서 나중에 읽기 힘들잖아. 얘한테도 칸을 미리 그려 주면 꼭 그 안에만 쓰는데, 칸 안에 쓴 게 맞는 말인지는 또 다른 얘기야.","check":[{"q":"모양이 완벽한데 값이 엉터리다. 어디를 봐야 하나","at":"흔한 오해"},{"q":"잘 부탁하는 것과 이 방식은 무엇이 다른가","at":"작동 원리"},{"q":"답을 받아 뜯어내지 않고 바로 읽을 수 있는 이유는","at":"그림"}],"myths":[{"wrong":"모양이 맞으면 내용도 맞다","right":"아니다. 모양만 보장한다. 빈칸을 못 두게 해 놓으면 모르는 값도 그럴듯하게 채워 넣는다."},{"wrong":"모양을 정하면 절대 안 깨진다","right":"길이 한도에 걸려 중간에 끊기면 반쪽짜리가 나온다. 거절할 때도 이 모양을 안 따를 수 있다."},{"wrong":"무조건 모양을 정해 두는 게 낫다","right":"사람이 읽을 글까지 칸에 가두면 답이 딱딱해진다. 기계가 읽을 것에만 건다."}],"cases":[{"label":"문서에서 값 뽑기","note":"계약서에서 금액·날짜·상대 이름을 정해진 칸으로 받는다."},{"label":"분류 붙이기","note":"문의 글을 정해 둔 항목 중 하나로만 답하게 한다. 없는 항목을 지어낼 수 없다."},{"label":"화면 그리기","note":"칸마다 다른 모양으로 그려야 할 때, 칸이 늘 있다는 보장이 필요하다."}],"dia":{"shape":"흐름","title":"답이 언제나 같은 모양으로 나오게 하려면 무엇을 하나","rows":[{"who":"앱","what":"받고 싶은 칸 이름과 자료형을 적어 보낸다"},{"who":"모델","what":"그 모양이 낱말 고르기를 가두는 틀이 된다"},{"who":"뽑기","what":"틀을 벗어나는 낱말은 후보에서 아예 빠진다"},{"who":"앱","what":"뜯어내지 않고 바로 읽을 수 있는 답을 받는다","back":true}],"sum":"잘 부탁하는 것이 아니라, 틀 밖으로 나갈 수 없게 만드는 것이다"}},"ai--system-prompt":{"definition":"만드는 사람의 지시와 쓰는 사람의 말은 섞이면 안 된다. 앞엣것은 대화 내내 지켜져야 하고 뒤엣것은 그때그때 바뀐다. 그래서 지시문은 대화 목록이 아니라 그 바깥의 자리에 따로 넣고, 둘이 부딪히면 지시문 쪽을 먼저 친다.","name":"System :: 판을 짜는 쪽\nPrompt :: 시키는 말\n= 붙여 읽으면 \"판을 짜는 쪽이 시키는 말\". 대화에 끼는 말이 아니라 대화를 감싸는 말이다","analogy":"연극의 배역 지시. 배우가 무대에서 무슨 말을 듣든, 어떤 인물로 있어야 하는지는 막이 오르기 전에 이미 정해져 있다.","example":"고객센터 챗봇이 아무리 딴 얘기를 걸어도 자기는 이 회사 상담원이라고만 하는 그 완고함이 여기서 나온다.","tryit":"쓰는 AI 앱마다 같은 질문을 던져 보라. 말투와 거절하는 선이 앱마다 다르다면, 그 차이를 만든 것이 이 자리다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"보내는 쪽에서는 대화 목록과 나란한 별도의 칸에 넣는다. 대화 안에 \"시스템\" 이라는 역할을 하나 끼워 넣는 것이 아니라 요청 본문의 다른 자리다. 제공자마다 이름은 다르지만 성질은 같다.\n\n여기 적은 글자도 매 요청마다 함께 실려 간다. 길게 적으면 그만큼 매번 요금이 붙고, 대화가 아무리 길어져도 이 부분은 잘리지 않는다. 그래서 분량이 아니라 우선순위를 적는 자리다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **말투 고정** — 같은 모델로 만든 두 앱이 전혀 다른 성격으로 말하는 이유가 이것이다.\n- **하지 말 것 정하기** — 진단이나 투자 판단은 하지 않는다고 미리 못박아 둔다.\n- **출력 모양 지정** — 항상 세 줄 요약으로 답하라고 걸어 두면 매번 다시 시키지 않아도 된다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **여기 적은 것은 사람이 못 본다** — 못 보게 막아 둔 것이지 비밀이 지켜지는 자리가 아니다. 캐묻는 말에 흘리는 일이 흔하다.\n- **여기 적으면 반드시 지킨다** — 우선순위가 높을 뿐 명령이 아니다. 규칙끼리 어긋나면 모델이 어느 쪽이든 고른다.\n- **길게 적을수록 잘 듣는다** — 매 요청에 실려 요금이 붙고, 규칙이 스무 개가 되면 저희끼리 부딪히기 시작한다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **비밀을 여기에 담지 않는다.** 열쇠값이나 내부 규정 원문을 적으면 캐묻는 말 한 줄에 새어 나갈 수 있다.\n- **사람이 친 말을 여기에 이어 붙이지 않는다.** 붙이는 순간 그 말이 만드는 사람의 지시와 같은 무게가 된다."}],"figure":"```도해\n층: 같은 모델인데 앱마다 다르게 답하는 이유는 무엇인가\n시스템 프롬프트 :: 만드는 사람이 건다. 대화 내내 그대로다\n대화 기록 :: 지금까지 오간 말. 쌓이고 오래되면 잘린다\n이번 질문 :: 쓰는 사람이 방금 친 말. 매번 바뀐다\n= 셋이 한 묶음으로 들어가고, 말이 부딪히면 위쪽이 이긴다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 지시를 그냥 첫 메시지로 보내면 무엇이 달라지나\n대화에 섞으면 || 따로 세우면\n지시의 수명 :: 밀려 나간다 || 매번 함께 간다\n사람이 뒤집기 :: 같은 무게다 || 위가 이긴다\n어디를 고치나 :: 대화를 뒤진다 || 한 곳만 고친다\n= 만드는 사람의 말과 쓰는 사람의 말은 무게가 달라야 한다\n```\n\n지시를 그냥 첫 메시지로 적어 보내면 두 가지가 무너진다. 대화가 길어지면 앞쪽이 잘려 나가면서 지시도 같이 사라지고, \"아까 그 말은 무시해\" 라고 하면 같은 무게의 말끼리 다투게 된다.\n\n따로 세운 자리는 대화 목록 밖에 있어서 잘리지 않고 매 요청마다 함께 실린다. 그리고 만드는 사람의 지시가 쓰는 사람의 말보다 앞선다는 것이 규격으로 정해져 있다. 앞선다는 것이지 못 뚫는다는 뜻은 아니다. 그 틈을 노리는 것이 [[Prompt Injection]] 이다."},"recap":"**\"막이 오르기 전에 정해 두는 그 배역\"** 이라고 읽으면 된다. 대화 목록 밖에 따로 서서 매번 함께 실리고, 쓰는 사람의 말보다 앞선다. 앞선다는 것이지 못 뚫는다는 뜻은 아니다.","kid":"연극 할 때 무대에 오르기 전에 \"너는 오늘 임금님이야, 화내면 안 돼\" 하고 미리 정해 주지? 보는 사람이 뭐라고 소리쳐도 그건 안 바뀌잖아. 얘도 말 걸기 전에 이미 누구인지 정해져 있어서, 네가 딴사람 되라고 해도 잘 안 바뀌어.","check":[{"q":"대화를 백 번 주고받아도 말투가 안 흐트러지는 이유는","at":"그림"},{"q":"규칙을 스무 개 적었더니 오히려 엉뚱해졌다. 왜","at":"흔한 오해"},{"q":"여기 적은 글이 매번 요금을 늘리는 이유는","at":"작동 원리"}],"myths":[{"wrong":"여기 적은 것은 사람이 못 본다","right":"못 보게 막아 둔 것이지 비밀이 지켜지는 자리가 아니다. 캐묻는 말에 흘리는 일이 흔하다."},{"wrong":"여기 적으면 반드시 지킨다","right":"우선순위가 높을 뿐 명령이 아니다. 규칙끼리 어긋나면 모델이 어느 쪽이든 고른다."},{"wrong":"길게 적을수록 잘 듣는다","right":"매 요청에 실려 요금이 붙고, 규칙이 스무 개가 되면 저희끼리 부딪히기 시작한다."}],"cases":[{"label":"말투 고정","note":"같은 모델로 만든 두 앱이 전혀 다른 성격으로 말하는 이유가 이것이다."},{"label":"하지 말 것 정하기","note":"진단이나 투자 판단은 하지 않는다고 미리 못박아 둔다."},{"label":"출력 모양 지정","note":"항상 세 줄 요약으로 답하라고 걸어 두면 매번 다시 시키지 않아도 된다."}],"dia":{"shape":"층","title":"같은 모델인데 앱마다 다르게 답하는 이유는 무엇인가","rows":[{"who":"시스템 프롬프트","what":"만드는 사람이 건다. 대화 내내 그대로다"},{"who":"대화 기록","what":"지금까지 오간 말. 쌓이고 오래되면 잘린다"},{"who":"이번 질문","what":"쓰는 사람이 방금 친 말. 매번 바뀐다"}],"sum":"셋이 한 묶음으로 들어가고, 말이 부딪히면 위쪽이 이긴다"}},"ai--temperature":{"definition":"모델은 다음에 올 낱말 후보마다 그럴듯한 정도를 매긴다. 그 점수를 그대로 쓰면 늘 1 등만 나오고, 점수 차를 눌러 평평하게 만들면 2 등 3 등도 뽑힐 여지가 생긴다. 이 값이 그 평평함을 정한다.","name":"= 열을 올리면 입자가 제멋대로 튀는 물리의 그 온도에서 왔다. 올릴수록 덜 그럴듯한 것이 튀어나온다","analogy":"면 수를 고를 수 있는 주사위. 한 면짜리로 만들면 던질 때마다 같은 것이 나오고, 면을 늘릴수록 무엇이 나올지 모르게 된다.","example":"같은 질문을 두 번 넣었는데 답이 다르게 나와 당황한 적이 있다면 이 값이 0 이 아니었던 것이다.","tryit":"쓰는 AI 앱에 똑같은 문장을 세 번 넣어 보라. 답이 매번 조금씩 다르면 이 값이 0 보다 크게 잡혀 있는 것이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"후보마다 붙은 점수를 이 값으로 나눈 다음 다시 확률로 편다. 나누는 수가 작으면 점수 차가 커져 1 등에 더 쏠리고, 크면 차이가 줄어 평평해진다. 후보를 빼거나 더하지는 않는다. 사이를 벌리고 좁힐 뿐이다.\n\n후보를 실제로 줄이는 손잡이는 따로 있다. 상위 몇 개만 남기거나 누적 확률 얼마까지만 남기는 방식이다. 온도와 같이 만지면 서로 간섭해서 무엇 때문에 달라졌는지 알기 어려워지므로, 한 번에 하나만 건드리는 편이 낫다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **분류와 값 뽑기** — 문서에서 금액을 뽑는 일에는 낮게 둔다. 창의는 여기서 오답이다.\n- **이름과 문구 짓기** — 후보를 여럿 받고 싶을 때 올린다. 같은 요청을 다섯 번 넣으면 다섯 갈래가 나온다.\n- **같은 답이 필요할 때** — 재 보고 비교하는 자리에서는 가장 낮게 내려 흔들림을 줄인다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **0 으로 두면 항상 같은 답이 나온다** — 가장 가까워질 뿐이다. 계산 순서와 기계 차이만으로도 답이 갈린다.\n- **올리면 더 창의적이 된다** — 덜 그럴듯한 후보를 고를 뿐이다. 지나치게 올리면 창의가 아니라 말이 안 되는 문장이 나온다.\n- **어디서나 이 값을 만질 수 있다** — 아예 못 만지게 막아 둔 곳도 있다. 그때는 값이 아니라 지시문으로 흔들림을 줄인다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **정답이 하나인 일에 올리지 않는다.** 금액·날짜처럼 틀리면 끝인 자리에서 흔들면 조용히 틀린 값이 섞인다.\n- **흔들림을 없애는 장치로 믿지 않는다.** 낮춰도 완전히 같아지지는 않으므로, 같아야 하는 값은 모델 밖에서 확인한다."}],"figure":"```도해\n흐름: 다음 낱말 하나가 뽑히기까지 무엇을 거치나\n모델 :: 후보마다 그럴듯한 정도를 점수로 매긴다\n온도 :: 그 점수 차를 벌리거나 눌러 평평하게 만든다\n뽑기 :: 눌린 만큼 덜 그럴듯한 것도 뽑힐 수 있다\n@ 다시 점수로 :: 뽑힌 말을 뒤에 붙이고 한 낱말 더 간다\n= 온도는 점수를 바꾸지 않는다. 점수 사이의 거리를 바꾼다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 이 값을 만질 수 없으면 무엇이 아쉬운가\n값이 고정이면 || 값을 고르면\n글짓기 :: 표현이 늘 같다 || 새 표현이 나온다\n값 뽑기 :: 흔들려도 못 막는다 || 눌러서 재게 한다\n일마다 다름 :: 한 설정을 견딘다 || 일마다 맞춘다\n= 창작과 정확은 서로 반대쪽이라 한 자리에 묶어 둘 수 없다\n```\n\n모델은 문장을 통째로 떠올리지 않는다. 낱말 하나를 고르고, 그것까지 포함해 다음 낱말을 고르는 일을 끝까지 되풀이한다. 매 걸음에서 늘 1 등만 집으면 답이 한 갈래로 굳고, 아무 제한 없이 흔들면 요약을 시켰는데 소설이 나온다.\n\n이 값은 그 사이를 손잡이 하나로 잇는다. 낮추면 점수 차가 더 벌어져 확실한 쪽으로 몰리고, 올리면 점수가 평평해져 덜 그럴듯한 후보도 뽑힐 자리가 생긴다. 요약과 분류는 낮은 쪽, 이름 짓기와 초안 쓰기는 높은 쪽이다."},"recap":"**\"몇 등까지 뽑히게 할지 정하는 그 손잡이\"** 라고 읽으면 된다. 낮추면 확실한 쪽으로 몰리고 올리면 덜 그럴듯한 것도 나온다. 후보를 바꾸는 게 아니라 후보 사이의 거리를 바꾼다.","kid":"면이 여섯인 주사위 말고, 면 수를 네가 정할 수 있는 주사위가 있다고 해 봐. 한 면짜리로 만들면 던질 때마다 똑같은 게 나오고, 면을 자꾸 늘리면 무엇이 나올지 모르게 되지? 이건 그 면 수를 정하는 손잡이야.","check":[{"q":"같은 질문을 두 번 넣었는데 답이 달랐다. 어느 값을 의심하나","at":"그림"},{"q":"0 으로 내렸는데도 답이 완전히 같지 않다. 왜","at":"흔한 오해"},{"q":"상위 몇 개만 남기는 손잡이와 같이 만지면 안 되는 이유는","at":"작동 원리"}],"myths":[{"wrong":"0 으로 두면 항상 같은 답이 나온다","right":"가장 가까워질 뿐이다. 계산 순서와 기계 차이만으로도 답이 갈린다."},{"wrong":"올리면 더 창의적이 된다","right":"덜 그럴듯한 후보를 고를 뿐이다. 지나치게 올리면 창의가 아니라 말이 안 되는 문장이 나온다."},{"wrong":"어디서나 이 값을 만질 수 있다","right":"아예 못 만지게 막아 둔 곳도 있다. 그때는 값이 아니라 지시문으로 흔들림을 줄인다."}],"cases":[{"label":"분류와 값 뽑기","note":"문서에서 금액을 뽑는 일에는 낮게 둔다. 창의는 여기서 오답이다."},{"label":"이름과 문구 짓기","note":"후보를 여럿 받고 싶을 때 올린다. 같은 요청을 다섯 번 넣으면 다섯 갈래가 나온다."},{"label":"같은 답이 필요할 때","note":"재 보고 비교하는 자리에서는 가장 낮게 내려 흔들림을 줄인다."}],"dia":{"shape":"흐름","title":"다음 낱말 하나가 뽑히기까지 무엇을 거치나","rows":[{"who":"모델","what":"후보마다 그럴듯한 정도를 점수로 매긴다"},{"who":"온도","what":"그 점수 차를 벌리거나 눌러 평평하게 만든다"},{"who":"뽑기","what":"눌린 만큼 덜 그럴듯한 것도 뽑힐 수 있다"}],"sum":"온도는 점수를 바꾸지 않는다. 점수 사이의 거리를 바꾼다","loop":{"who":"다시 점수로","what":"뽑힌 말을 뒤에 붙이고 한 낱말 더 간다"}}},"ai--text-to-sql":{"definition":"DB에 있는 것을 보려면 SQL을 써야 하는데, 그걸 쓸 줄 아는 사람은 조직에서 소수다. 질문을 그대로 받아 쿼리로 옮겨주면 그 사이에 있던 사람이 빠진다.","name":"Text :: 사람이 쓰는 말\nSQL :: 표에 묻는 말\n= 붙여 읽으면 \"사람 말을 표에 묻는 말로\". 가운데 to 가 옮겨 적는 방향을 가리킨다","analogy":"말이 안 통하는 손님 대신 주문을 옮겨주는 통역. 말은 통하지만 주방에 무엇이 있는지는 통역이 알고 있어야 한다.","example":"사내 대시보드에 지난달 매출을 말로 물었더니 곧바로 표가 그려져 나오는 그 화면이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"모델은 DB를 들여다보지 못한다. 질문과 함께 넘겨준 것만 보고 문장을 만든다. 정확한 SQL 이 나오려면 이만큼을 같이 넘겨야 한다.\n\n- **스키마** — 표 이름과 칸 이름, 자료형\n- **관계** — 어느 칸이 어느 표와 이어지는지\n- **용어** — \"매출\"이 어느 칸을 뜻하는지 적어둔 것\n- **예시 질문** — 이런 질문에는 이런 쿼리라는 견본\n\n모델은 모르는 것을 지어내므로 미리 알려준 만큼만 맞는다. 표 이름이나 칸 이름을 안 알려주면 그럴듯한 이름을 지어내고, 그 쿼리는 실행 단계에서 깨진다.\n\n만들어진 쿼리를 바로 실행하지 않는 것도 중요하다. 읽기 전용 계정으로 돌리고, `DELETE`나 `DROP`, `UPDATE` 같은 것이 섞여 있으면 실행 전에 막는다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **사내 데이터 조회** — 자주 나오는 질문을 담당자에게 부탁하지 않고 직접 물어본다.\n- **읽기 전용 통로** — 조회 권한만 있는 계정으로 실행해서 어떤 쿼리가 나와도 데이터가 바뀌지 않게 한다.\n- **쿼리 같이 보여주기** — 결과만 주지 않고 만들어진 SQL을 함께 띄워 무엇을 센 숫자인지 확인하게 한다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **말로 물으면 알아서 찾아준다** — 모델이 아는 것은 넘겨준 스키마뿐이다. 표와 칸 이름, \"매출\"이 어느 칸인지를 안 알려주면 있을 법한 이름을 지어내 틀린 쿼리를 만든다.\n- **결과가 나왔으면 맞는 것이다** — 문법이 맞는 SQL과 의도에 맞는 SQL은 다르다. 조건이 하나 빠져도 쿼리는 잘 돌고 숫자만 틀리게 나온다.\n- **읽기만 하는 기능이라 위험하지 않다** — 만들어지는 문장이 항상 읽기라는 보장이 없다. 읽기 전용 계정으로 돌리고 실행 전에 걸러야 그 말이 성립한다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **스키마를 통째로 넘기지 않는다.** 표가 많으면 넘길 것을 골라야 하고, 민감한 칸은 애초에 안 보이게 한다.\n- **결과를 그대로 보고서에 옮기지 않는다.** 어떤 쿼리로 나온 숫자인지 확인하지 않으면 틀린 수를 근거로 결정하게 된다."}],"figure":"```도해\n흐름: \"지난달 매출 얼마야\" 가 어떻게 답이 되나\n질문 :: 사람이 평소 쓰는 말로 묻는다\n스키마 :: 어떤 표에 어떤 칸이 있는지 같이 넘긴다\nLLM :: 그 정보를 보고 SQL 문장을 만든다\n검사 :: 읽기만 하는 쿼리인지 확인하고 통과시킨다\nDB :: 실행해서 행을 돌려준다\n< 답 :: 표나 문장으로 바꿔 보여준다\n= 사람은 SQL 을 안 쓰지만 DB 가 받는 것은 여전히 SQL 이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: SQL 을 모르는 사람이 숫자를 보려면 어떻게 되나\n사람에게 부탁 || 말로 물어서\n걸리는 시간 :: 며칠씩 기다림 || 바로 나온다\n질문 바꾸기 :: 다시 부탁한다 || 다시 물으면 끝\n개발자 :: 조회 요청에 묶임 || 다른 일을 한다\n= 숫자를 궁금해하는 사람과 SQL 을 쓰는 사람을 떼어놓는 것이다\n```\n\n\"지난달 신규 가입자 몇 명이야\" 같은 질문은 매주 나온다. 물어볼 곳이 사람뿐이면 요청이 쌓여 며칠이 걸리고, 답을 받고 나서 조건 하나를 바꾸고 싶으면 처음부터 다시 부탁해야 한다.\n\nText-to-SQL은 그 왕복을 없앤다. 궁금한 사람이 직접 묻고 바로 다시 물을 수 있으므로, 조건을 바꿔가며 확인하는 일이 사람 손을 거치지 않는다."},"recap":"**\"사람 말을 표가 알아듣는 말로 옮기는 그 통역\"** 이라고 읽으면 된다. 모델은 알려준 만큼만 알기 때문에 스키마와 용어를 얼마나 잘 넘겨주느냐가 정확도를 정하고, 만들어진 쿼리는 실행 전에 한 번 걸러야 한다.","kid":"외국 손님이 주문할 때 옆에서 말을 옮겨 주는 사람이 있지? 네가 \"지난달에 얼마 벌었어?\" 하고 물으면 이것도 그렇게 옮겨 줘. 대신 옮겨 주는 사람이 주방에 뭐가 있는지 모르면, 있지도 않은 메뉴를 아주 그럴듯하게 말해 버려.","check":[{"q":"표 이름과 칸 이름을 안 넘겨주면 어떤 쿼리가 만들어지나","at":"작동 원리"},{"q":"쿼리가 오류 없이 돌았는데도 숫자가 틀릴 수 있는 이유는","at":"흔한 오해"},{"q":"조회만 하는 기능인데도 읽기 전용 계정으로 돌리는 이유는","at":"실제 사례"}],"myths":[{"wrong":"말로 물으면 알아서 찾아준다","right":"모델이 아는 것은 넘겨준 스키마뿐이다. 표와 칸 이름, \"매출\"이 어느 칸인지를 안 알려주면 있을 법한 이름을 지어내 틀린 쿼리를 만든다."},{"wrong":"결과가 나왔으면 맞는 것이다","right":"문법이 맞는 SQL과 의도에 맞는 SQL은 다르다. 조건이 하나 빠져도 쿼리는 잘 돌고 숫자만 틀리게 나온다."},{"wrong":"읽기만 하는 기능이라 위험하지 않다","right":"만들어지는 문장이 항상 읽기라는 보장이 없다. 읽기 전용 계정으로 돌리고 실행 전에 걸러야 그 말이 성립한다."}],"cases":[{"label":"사내 데이터 조회","note":"자주 나오는 질문을 담당자에게 부탁하지 않고 직접 물어본다."},{"label":"읽기 전용 통로","note":"조회 권한만 있는 계정으로 실행해서 어떤 쿼리가 나와도 데이터가 바뀌지 않게 한다."},{"label":"쿼리 같이 보여주기","note":"결과만 주지 않고 만들어진 SQL을 함께 띄워 무엇을 센 숫자인지 확인하게 한다."}],"dia":{"shape":"흐름","title":"\"지난달 매출 얼마야\" 가 어떻게 답이 되나","rows":[{"who":"질문","what":"사람이 평소 쓰는 말로 묻는다"},{"who":"스키마","what":"어떤 표에 어떤 칸이 있는지 같이 넘긴다"},{"who":"LLM","what":"그 정보를 보고 SQL 문장을 만든다"},{"who":"검사","what":"읽기만 하는 쿼리인지 확인하고 통과시킨다"},{"who":"DB","what":"실행해서 행을 돌려준다"},{"who":"답","what":"표나 문장으로 바꿔 보여준다","back":true}],"sum":"사람은 SQL 을 안 쓰지만 DB 가 받는 것은 여전히 SQL 이다"}},"ai--token":{"definition":"글자 단위도 아니고 단어 단위도 아니다. 자주 쓰이는 덩어리를 하나로 묶은 중간 크기라서, 영어는 대략 단어 하나가 토큰 하나에 가깝고 한글은 글자 하나가 여러 토큰이 되기도 한다.","analogy":"택배 요금의 부피 단위. 물건 개수도 무게도 아닌 별도 기준으로 값이 매겨진다. 같은 물건이라도 어떻게 포장했느냐에 따라 단위 수가 달라진다.","example":"문자를 몇 글자 더 썼다고 장문으로 넘어가 요금이 달라지던 일을 겪어 봤다면, 세는 단위가 따로 있다는 말을 이미 안다.","tryit":"검색창에 \"OpenAI tokenizer\" 를 쳐서 나오는 페이지에 같은 뜻의 한글 문장과 영어 문장을 차례로 붙여넣어 보라. 밑에 뜨는 조각 수가 한글 쪽만 몇 배 크다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"한국어는 영어보다 토큰을 훨씬 많이 쓴다. 학습 데이터에 영어가 압도적으로 많아서 영어 덩어리가 더 잘 묶여 있기 때문이다.\n\n```도해\n층: 같은 뜻을 쓰는 데 토큰이 얼마나 드나\n영어 문장 :: 단어 하나가 대체로 토큰 하나\n한글 문장 :: 글자 하나가 토큰 하나에서 셋\n코드 :: 들여쓰기와 기호가 각각 토큰\n= 같은 내용도 한국어로 쓰면 비용이 몇 배가 된다\n```\n\n문맥 창도 토큰으로 센다. 창이 8,000토큰이면 대화 기록과 질문과 답을 다 합쳐 8,000을 넘을 수 없다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **요금 계산** — API 값은 입력 토큰과 출력 토큰을 따로 센다. 출력이 대체로 더 비싸다.\n- **문맥 창 관리** — 대화가 길어지면 앞부분을 요약해 넣어 토큰을 줄인다.\n- **프롬프트 다듬기** — 같은 지시를 짧게 쓰면 매 요청마다 그만큼 아낀다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **토큰이 단어와 같다** — 다르다. `unbelievable`은 세 토큰으로 쪼개지고, 한글 `안녕하세요`도 여러 토큰이다.\n- **글자 수로 비용을 계산할 수 있다** — 언어마다 비율이 달라서 한국어를 영어 기준으로 계산하면 크게 어긋난다.\n- **입력만 돈이 든다** — 모델이 만들어낸 출력도 토큰으로 센다. 긴 답변을 요구하면 그만큼 비싸진다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **긴 대화 기록을 통째로 넣지 않는다.** 매 요청마다 전체가 다시 계산되어 비용이 대화 길이의 제곱처럼 늘어난다.\n- **한국어 비용을 따로 잰다.** 영어 기준 견적으로 계획하면 실제 청구가 몇 배로 나온다."}],"figure":"```도해\n흐름: 입력한 글이 어떻게 요금이 되나\n사용자 :: \"안녕하세요\" 를 입력한다\n토크나이저 :: 자주 쓰이는 덩어리로 쪼갠다\n토크나이저 :: 조각마다 번호를 붙인다\n모델 :: 번호 목록을 받아 다음 번호를 예측한다\n요금 :: 넣은 토큰 수 + 나온 토큰 수로 계산된다\n= 글자 수가 아니라 토큰 수가 비용이자 한계다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 쪼개는 단위를 무엇으로 하나\n글자 단위 || 토큰 단위\n목록 크기 :: 작다 || 적당하다\n문맥 길이 :: 금방 찬다 || 여유가 있다\n처음 보는 말 :: 처리된다 || 조각으로 처리된다\n= 글자는 너무 잘고 단어는 너무 많아서 그 사이를 고른 것이다\n```\n\n단어 단위로 쪼개면 사전에 없는 말을 만났을 때 처리할 수 없다. 신조어, 오타, 고유명사가 전부 미지의 단어가 된다.\n\n글자 단위로 쪼개면 그 문제는 없지만 목록이 너무 길어진다. 문장 하나가 수십 조각이 되어 문맥 창을 금방 채운다.\n\n토큰은 그 사이다. 자주 나오는 덩어리는 하나로 묶고, 드문 말은 조각으로 나눠서 둘 다 처리한다."},"recap":"**\"글자 수가 아니라 따로 세는 그 값 단위\"** 라고 읽으면 된다. 글자도 단어도 아닌 중간 크기이고, 한국어는 같은 내용에 영어보다 훨씬 많은 토큰을 쓴다.","kid":"택배는 물건 개수가 아니라 상자 크기로 값을 매기지? 글도 글자 수가 아니라 잘라 놓은 조각 수로 세. 자주 쓰는 말은 한 조각으로 묶이고 드문 말은 여러 조각으로 쪼개져서, 길이가 똑같은 글도 어떤 건 값이 두 배로 나와.","check":[{"q":"같은 내용을 한국어로 쓸 때 비용이 더 나오는 이유는","at":"작동 원리"},{"q":"대화가 길어질수록 요청 하나의 비용이 늘어나는 이유는","at":"주의사항"},{"q":"짧게 물었는데 답이 길게 오면 요금이 왜 더 나오나","at":"흔한 오해"}],"myths":[{"wrong":"토큰이 단어와 같다","right":"다르다. `unbelievable`은 세 토큰으로 쪼개지고, 한글 `안녕하세요`도 여러 토큰이다."},{"wrong":"글자 수로 비용을 계산할 수 있다","right":"언어마다 비율이 달라서 한국어를 영어 기준으로 계산하면 크게 어긋난다."},{"wrong":"입력만 돈이 든다","right":"모델이 만들어낸 출력도 토큰으로 센다. 긴 답변을 요구하면 그만큼 비싸진다."}],"cases":[{"label":"요금 계산","note":"API 값은 입력 토큰과 출력 토큰을 따로 센다. 출력이 대체로 더 비싸다."},{"label":"문맥 창 관리","note":"대화가 길어지면 앞부분을 요약해 넣어 토큰을 줄인다."},{"label":"프롬프트 다듬기","note":"같은 지시를 짧게 쓰면 매 요청마다 그만큼 아낀다."}],"dia":{"shape":"흐름","title":"입력한 글이 어떻게 요금이 되나","rows":[{"who":"사용자","what":"\"안녕하세요\" 를 입력한다"},{"who":"토크나이저","what":"자주 쓰이는 덩어리로 쪼갠다"},{"who":"토크나이저","what":"조각마다 번호를 붙인다"},{"who":"모델","what":"번호 목록을 받아 다음 번호를 예측한다"},{"who":"요금","what":"넣은 토큰 수 + 나온 토큰 수로 계산된다"}],"sum":"글자 수가 아니라 토큰 수가 비용이자 한계다"}},"ai--tool-calling":{"definition":"모델은 글을 지을 뿐 바깥에서 아무것도 못 한다. 그래서 쓸 수 있는 도구의 이름과 입력 모양을 미리 알려주면, 모델은 필요할 때 \"이 도구를 이 값으로 불러 달라\"는 요청을 돌려준다. 실행은 앱이 한다.","name":"Tool :: 바깥 일을 하는 것\nCalling :: 부르기\n= 붙여 읽으면 \"도구를 부르기\". 부르기만 하고 실행은 남이 한다는 것이 이름에는 안 적혀 있다","analogy":"식당 주문서. 손님이 적어 낸 종이가 요리를 하지는 않는다. 주방이 한다.","example":"AI 에게 오늘 날씨를 물으면 잠깐 멈췄다가 답이 나온다. 그 멈춘 사이에 바깥을 한 번 다녀온 것이다.","tryit":"AI 앱에 오늘 날짜를 물어보라. 맞히면 바깥을 다녀온 것이고, 엉뚱한 날을 대면 배운 것만으로 답한 것이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"한 번의 대화가 아니라 두 번의 왕복이다. 앱은 먼저 도구 목록을 붙여 묻고, 모델은 답 대신 \"도구를 부르겠다\"는 표시와 함께 도구 이름·입력값을 돌려준다. 앱이 그것을 실행한 뒤, 실행 결과를 대화에 덧붙여 다시 한 번 묻는다. 두 번째 요청에서야 사람이 읽을 답이 나온다.\n\n제공자가 대신 실행해 주는 도구도 따로 있다. 검색 같은 것은 앱이 손댈 것 없이 결과만 돌아온다. 그때도 실행하는 쪽은 모델이 아니라 그 제공자의 기계다.\n\n도구를 알려주는 일에도 값이 든다. 도구 이름과 설명과 입력 모양이 전부 매 요청마다 함께 실려 가므로, 안 쓰는 도구를 잔뜩 매달아 두면 부르지도 않은 것에 요금이 붙는다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **사내 재고 조회** — \"이 모델 재고 있나요\"에 창고 시스템을 불러 숫자를 보고 답한다.\n- **일정 잡기** — 빈 시간을 달력에서 읽어 오고, 확정도 달력에 써 넣는다.\n- **코드 고치기** — 파일을 읽는 도구와 쓰는 도구를 쥐여 주면 저장소를 직접 손본다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **모델이 도구를 직접 실행한다** — 아니다. 모델이 돌려주는 것은 \"이걸 불러 달라\"는 요청이고, 실행하는 것은 앱이다.\n- **도구를 많이 달수록 똑똑해진다** — 도구 설명이 전부 매 요청에 실려 간다. 비슷한 도구가 여럿이면 고르다 틀리기도 한다.\n- **도구를 달면 시키는 대로만 한다** — 언제 부를지는 모델이 정한다. 반드시 부르게 하려면 따로 못박아야 한다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **실행 직전이 마지막 관문이다.** 모델이 부르라고 한 것을 앱이 그대로 실행하면, 문서에 숨어 든 지시도 그대로 실행된다.\n- **되돌릴 수 없는 일은 사람에게 묻는다.** 읽는 도구와 지우는 도구를 같은 무게로 쥐여 주지 않는다."}],"figure":"```도해\n흐름: 모델이 도구를 쓴다는 것은 실제로 무슨 일인가\n앱 :: 쓸 수 있는 도구의 이름과 입력 모양을 미리 알려준다\n모델 :: 필요하면 \"이 도구를 이 값으로\" 라고 돌려준다\n앱 :: 그 도구를 진짜로 실행한다\n< 모델 :: 실행 결과를 받아 사람이 읽을 답을 짓는다\n= 모델은 부탁을 적어 줄 뿐, 손을 쓰는 것은 언제나 앱이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 모델에게 바깥일을 시키려면 어떻게 하나\n도구 없이 || 도구 호출로\n오늘 환율 :: 모른다 || 불러서 본다\n일 시키기 :: 말만 한다 || 실제로 한다\n모르는 값 :: 그럴듯이 지어낸다 || 받은 값을 쓴다\n= 모델을 바깥과 잇는 통로가 이것 하나다\n```\n\n모델은 학습이 끝난 시점에 멈춰 있다. 그 뒤에 생긴 일도, 이 회사 안에만 있는 값도 모른다. 모르는 것을 물으면 모른다고 하는 대신 그럴듯한 값을 지어내는 쪽이 더 흔하다.\n\n도구 호출은 그 벽에 문을 낸다. 다만 문을 여는 손은 앱 쪽에 있다. 모델이 돌려주는 것은 요청일 뿐이고, 그 요청을 그대로 실행할지 막을지는 앱이 정한다. 이 자리가 [[Prompt Injection]] 을 막는 마지막 관문이기도 하다."},"recap":"**\"부탁은 모델이, 실행은 앱이 하는 그 주문서\"** 라고 읽으면 된다. 모델은 도구 이름과 입력값을 돌려줄 뿐이고, 실제로 손을 쓰는 것은 언제나 앱 쪽이다. 그래서 무엇을 실행할지 막는 자리도 앱에 있다.","kid":"식당에서 종이에 \"김치찌개 하나\" 라고 적어 주면 그 종이가 요리를 하지는 않지? 주방이 그걸 보고 끓여서 내오잖아. 얘도 무얼 해 달라고 적어 내밀 뿐이고, 실제로 움직이는 건 다른 쪽이야.","check":[{"q":"도구를 스무 개 달았더니 요금이 늘었다. 왜","at":"작동 원리"},{"q":"문서에 \"파일을 지워라\" 가 숨어 있었다. 어디서 막나","at":"주의사항"},{"q":"AI 가 오늘 날씨를 맞혔다면 그 값은 어디서 왔나","at":"그림"}],"myths":[{"wrong":"모델이 도구를 직접 실행한다","right":"아니다. 모델이 돌려주는 것은 \"이걸 불러 달라\"는 요청이고, 실행하는 것은 앱이다."},{"wrong":"도구를 많이 달수록 똑똑해진다","right":"도구 설명이 전부 매 요청에 실려 간다. 비슷한 도구가 여럿이면 고르다 틀리기도 한다."},{"wrong":"도구를 달면 시키는 대로만 한다","right":"언제 부를지는 모델이 정한다. 반드시 부르게 하려면 따로 못박아야 한다."}],"cases":[{"label":"사내 재고 조회","note":"\"이 모델 재고 있나요\"에 창고 시스템을 불러 숫자를 보고 답한다."},{"label":"일정 잡기","note":"빈 시간을 달력에서 읽어 오고, 확정도 달력에 써 넣는다."},{"label":"코드 고치기","note":"파일을 읽는 도구와 쓰는 도구를 쥐여 주면 저장소를 직접 손본다."}],"dia":{"shape":"흐름","title":"모델이 도구를 쓴다는 것은 실제로 무슨 일인가","rows":[{"who":"앱","what":"쓸 수 있는 도구의 이름과 입력 모양을 미리 알려준다"},{"who":"모델","what":"필요하면 \"이 도구를 이 값으로\" 라고 돌려준다"},{"who":"앱","what":"그 도구를 진짜로 실행한다"},{"who":"모델","what":"실행 결과를 받아 사람이 읽을 답을 짓는다","back":true}],"sum":"모델은 부탁을 적어 줄 뿐, 손을 쓰는 것은 언제나 앱이다"}},"ai--transformer":{"definition":"앞에서부터 한 낱말씩 읽던 RNN 을 대신했다. GPT 와 BERT 를 비롯한 요즘 언어 모델이 전부 이 구조 위에 서 있다.","name":"Transform :: 딴 것으로 바꾸다\n= 넣은 글을 다른 글로 바꿔 내놓는 데서 온 이름이다. 어떻게 바꾸는지가 아니라 무엇을 하는지가 이름이 됐다","analogy":"책 한 쪽을 통째로 펼쳐 놓고 보는 것. 3번째 줄과 20번째 줄이 이어진다는 걸 한눈에 알아챈다.","example":"번역기에 한 문장을 넣으면 어순이 통째로 뒤집힌 문장이 나온다. 앞에서부터 한 낱말씩 바꿔서는 나올 수 없는 결과다.","tryit":"번역기에 \"나는 어제 시장에서 산 사과를 먹었다\" 를 넣어 보라. 어순이 통째로 뒤집힌 문장이 나온다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"한 겹은 네 부품으로 되어 있다.\n\n| 부품 | 하는 일 |\n|---|---|\n| **위치 인코딩** | 몇 번째 조각인지를 값에 실어 준다 |\n| **셀프 어텐션** | 조각끼리 서로 얼마나 볼지 정한다 |\n| **멀티 헤드** | 같은 일을 여러 갈래로 나눠 따로 본다 |\n| **피드포워드** | 섞인 값을 한 번 더 변환한다 |\n\n이 한 겹을 여러 번 쌓아 올린 것이 모델의 깊이다.\n\n어텐션은 조각마다 다른 조각을 얼마나 볼지 점수로 매기고, 그 점수를 가중치 삼아 값을 섞는다. \"나는 학교에 갔다\"에서 \"갔다\"는 \"학교에\"를 많이 보고 \"나는\"은 조금만 보는 식이다.\n\n멀티 헤드는 그 보기를 여러 갈래로 나눈다. 한 갈래는 문법 쪽 관계를, 다른 갈래는 의미 쪽 관계를 보게 갈라 두면 한 갈래만 쓸 때보다 잡히는 게 많다.\n\n순서를 안 보고 관계만 재면 \"나는 학교에 갔다\"와 \"학교에 나는 갔다\"가 같아진다. 그래서 몇 번째 조각인지를 값에 실어 주는데, 이것을 위치 인코딩이라고 한다."},{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: GPT vs BERT vs T5","body":"| | GPT | BERT | T5 |\n|---|---|---|---|\n| 쓰는 부분 | 디코더만 | 인코더만 | 둘 다 |\n| 하는 일 | 다음 낱말 예측 | 가려진 낱말 맞히기 | 입력을 다른 글로 |\n| 맞는 자리 | 글 생성 | 분류, 질의응답 | 번역, 요약 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **글 생성** — \"안녕하세요, 저는\" 다음에 올 조각을 하나씩 이어 붙여 문장을 만든다.\n- **빈칸 맞히기** — \"나는 [MASK]에 갔다\"에서 가려진 자리를 앞뒤를 다 보고 채운다.\n- **번역과 요약** — 입력을 통째로 읽고 다른 글로 바꿔 내놓는다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **Transformer 는 문장을 순서대로 읽는다** — 전부 펼쳐 놓고 동시에 본다. 순서는 위치 인코딩으로 따로 실어 주는 것이라 그걸 빼면 낱말 순서를 아예 구별하지 못한다.\n- **Attention 이 곧 이해다** — 어느 조각을 얼마나 볼지 정한 가중치일 뿐이다. 값을 섞는 비율이지 뜻을 읽어낸 결과가 아니다.\n- **입력이 길어져도 계산은 비슷하다** — 모든 조각 쌍을 재므로 조각 수가 두 배면 계산은 네 배가 된다. 긴 입력이 부담스러운 이유가 여기 있다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **입력이 길수록 메모리가 제곱으로 는다.** 긴 문서를 그대로 넣기 전에 자르거나 다른 어텐션 방식을 찾아본다.\n- **작은 데이터로는 잘 되지 않는다.** 학습에 아주 많은 양이 필요해서 대개 이미 학습된 모델을 가져다 쓴다."}],"figure":"```도해\n흐름: 문장 하나가 Transformer 를 지나며 무엇을 겪나\n토큰 :: 문장을 조각내 각각 숫자 배열로 바꾼다\n위치 표시 :: 몇 번째 조각인지를 그 배열에 더한다\n어텐션 :: 모든 조각이 서로를 얼마나 볼지 잰다\n섞기 :: 많이 본 쪽 값을 더 얹어 새 배열을 만든다\n@ 다시 어텐션으로 :: 같은 일을 여러 겹 쌓아 결과를 낸다\n= 순서대로 읽지 않고 전부 펼쳐 놓은 채 관계만 잰다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 문장을 앞에서부터 한 낱말씩 읽으면 어떻게 되나\n한 낱말씩 || 한꺼번에\n처리 순서 :: 앞이 끝나야 뒤 || 동시에 본다\nGPU :: 나눠 쓸 수 없다 || 병렬로 돌린다\n먼 관계 :: 갈수록 흐려진다 || 거리와 무관\n= 순서를 버리고 관계를 직접 재는 쪽으로 바꾼 것이다\n```\n\nRNN 은 첫 낱말을 처리해야 두 번째를 처리할 수 있다. 순서를 지켜야 하니 GPU 를 여러 장 붙여도 나눠 돌릴 수 없어서, 백만 문장을 학습하는 데 며칠에서 몇 주가 걸렸다. 멀리 떨어진 관계도 약했다. \"어제 시장에서 산 사과를 오늘 먹었다\"에서 \"사과\"와 \"먹었다\"는 여러 낱말 건너에 있어 앞의 정보가 뒤로 오는 동안 흐려진다.\n\nTransformer 는 문장 전체를 펼쳐 놓고 모든 조각 쌍의 관계를 한 번에 잰다. 순서에 묶이지 않으니 나눠 돌릴 수 있어 같은 학습이 몇 시간에서 하루 규모로 줄었다. 거리와 상관없이 \"사과\"와 \"먹었다\"가 곧바로 이어진다."},"recap":"**\"통째로 펼쳐 놓고 서로를 보게 한 그 구조\"** 라고 읽으면 된다. 순서에 묶이지 않아 나눠 돌릴 수 있고 멀리 떨어진 낱말 사이의 관계도 흐려지지 않는다. 대신 모든 쌍을 재느라 입력이 길어질수록 계산이 제곱으로 늘어난다.","kid":"책을 손가락으로 한 줄씩 짚어 가며 읽으면 앞에서 본 걸 뒤에 가서 까먹지? 한 쪽을 통째로 펼쳐 놓고 보면 셋째 줄이랑 스무째 줄이 이어진다는 게 한눈에 보이잖아. 그렇게 다 펼쳐 놓고 어떤 말이 어떤 말이랑 붙는지를 재는 거야.","check":[{"q":"\"나는 학교에 갔다\"와 \"학교에 나는 갔다\"를 구별하려면 무엇이 필요한가","at":"작동 원리"},{"q":"RNN 은 GPU 를 여러 장 붙여도 학습이 빨라지지 않는데 그 이유는","at":"해결하는 문제"},{"q":"입력 조각 수를 두 배로 늘리면 계산량은 몇 배가 되나","at":"흔한 오해"}],"myths":[{"wrong":"Transformer 는 문장을 순서대로 읽는다","right":"전부 펼쳐 놓고 동시에 본다. 순서는 위치 인코딩으로 따로 실어 주는 것이라 그걸 빼면 낱말 순서를 아예 구별하지 못한다."},{"wrong":"Attention 이 곧 이해다","right":"어느 조각을 얼마나 볼지 정한 가중치일 뿐이다. 값을 섞는 비율이지 뜻을 읽어낸 결과가 아니다."},{"wrong":"입력이 길어져도 계산은 비슷하다","right":"모든 조각 쌍을 재므로 조각 수가 두 배면 계산은 네 배가 된다. 긴 입력이 부담스러운 이유가 여기 있다."}],"cases":[{"label":"글 생성","note":"\"안녕하세요, 저는\" 다음에 올 조각을 하나씩 이어 붙여 문장을 만든다."},{"label":"빈칸 맞히기","note":"\"나는 [MASK]에 갔다\"에서 가려진 자리를 앞뒤를 다 보고 채운다."},{"label":"번역과 요약","note":"입력을 통째로 읽고 다른 글로 바꿔 내놓는다."}],"dia":{"shape":"흐름","title":"문장 하나가 Transformer 를 지나며 무엇을 겪나","rows":[{"who":"토큰","what":"문장을 조각내 각각 숫자 배열로 바꾼다"},{"who":"위치 표시","what":"몇 번째 조각인지를 그 배열에 더한다"},{"who":"어텐션","what":"모든 조각이 서로를 얼마나 볼지 잰다"},{"who":"섞기","what":"많이 본 쪽 값을 더 얹어 새 배열을 만든다"}],"sum":"순서대로 읽지 않고 전부 펼쳐 놓은 채 관계만 잰다","loop":{"who":"다시 어텐션으로","what":"같은 일을 여러 겹 쌓아 결과를 낸다"}}},"ai--vector-db":{"definition":"임베딩으로 만든 숫자 목록을 수백만 개 넣어두고, 질문 벡터가 들어오면 그와 가장 가까운 것들을 골라준다. 일반 데이터베이스가 값이 같은 것을 찾는다면 이쪽은 값이 비슷한 것을 찾는다.","name":"Vector :: 방향을 가진 화살표\nDB :: 쌓아 두고 찾는 곳\n= 붙여 읽으면 \"화살표를 쌓아 두고 찾는 곳\". 같은 값이 아니라 가까운 화살표를 찾는다","analogy":"도서관의 주제별 배가. 제목이 정확히 기억나지 않아도 관련 서가로 가면 비슷한 책들이 모여 있다. 청구기호가 정확히 일치해야 찾을 수 있는 방식과 다르다.","example":"쇼핑 앱에서 물건 사진을 찍어 올리면 비슷하게 생긴 상품들이 줄줄이 뜨는 그 검색이다.","tryit":"쇼핑 앱 검색창의 사진기 단추로 눈앞의 물건을 찍어 보라. 이름을 한 글자도 안 쳤는데 닮은 상품이 뜬다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"```도해\n흐름: 넣어둔 문서가 골라져 나오기까지 무엇을 거치나\n임베딩 :: 문서를 벡터로 만든다\n색인 :: 이웃 관계를 미리 계산해 지도를 만든다\n검색 :: 질문이 오면 지도를 타고 후보를 좁힌다\n필터 :: 부서나 권한 같은 조건으로 거른다\n= 색인을 만드는 시간이 들지만 그 뒤로는 검색이 싸진다\n```\n\n메타데이터 필터가 실무에서 중요하다. 벡터로 가까운 것을 찾되 \"이 사용자가 볼 수 있는 문서\"로 한정하지 않으면 권한 없는 내용이 검색된다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **RAG 저장소** — 사내 문서를 조각내 넣어두고 질문과 가까운 조각을 꺼낸다.\n- **이미지 검색** — 사진을 벡터로 넣어두면 비슷한 사진을 찾을 수 있다.\n- **중복 문의 묶기** — 표현이 다른 같은 문의를 벡터 거리로 묶어 한 번에 처리한다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **벡터 DB가 항상 정확한 답을 준다** — 근사 검색이라 가장 가까운 것을 놓칠 수 있다. 정확도와 속도를 설정으로 조절한다.\n- **일반 데이터베이스를 대체한다** — 대체하지 않는다. 주문 내역처럼 정확히 일치하는 조회는 여전히 관계형이 맞다.\n- **넣기만 하면 검색이 좋아진다** — 검색 품질은 임베딩 모델과 문서를 어떻게 잘랐는지가 정한다. 저장소는 빠르게 찾아줄 뿐이다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **권한 필터를 벡터 검색에 같이 건다.** 나중에 거르면 이미 본 문서가 나간 뒤다.\n- **모델을 바꾸면 전부 다시 넣어야 한다.** 좌표계가 달라져서 옛 벡터와 새 벡터를 비교할 수 없다."}],"figure":"```도해\n흐름: 백만 개 중에서 가까운 셋을 어떻게 찾나\n질문 :: 벡터 하나가 들어온다\n색인 :: 미리 만들어둔 이웃 지도를 탄다\n색인 :: 가까운 후보 구역으로 건너뛴다\n색인 :: 그 안에서만 실제 거리를 잰다\n< 결과 :: 가장 가까운 셋을 돌려준다\n= 백만 개를 다 재지 않는 대신 정확도를 조금 내주는 거래다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 백만 개 벡터에서 가까운 것을 어떻게 찾나\n일반 DB |=| 벡터 DB\n검색 방식 :: 전부 하나씩 계산 || 색인으로 건너뛴다\n소요 시간 :: 수 초 || 수십 밀리초\n정확도 :: 완벽 || 거의 정확\n= 전부 재는 대신 대부분 맞는 답을 훨씬 빨리 주는 쪽을 고른 것이다\n```\n\n벡터 검색은 원래 무거운 작업이다. 백만 개가 있으면 백만 번 거리를 계산해야 한다. 관계형 데이터베이스에 벡터를 넣고 매번 전부 계산하면 검색 하나에 수 초가 걸린다.\n\n벡터 DB는 이웃 관계를 미리 지도로 만들어둔다. 검색할 때 그 지도를 따라 후보 구역까지 건너뛰고 그 안에서만 실제로 계산한다. 완벽한 답을 포기하는 대신 속도를 얻는 방식이라 근사 최근접 이웃 검색이라고 부른다."},"compose":{"label":"무엇으로 되어 있나","head":"🧱 구성","body":"```도해\n층: 벡터 DB 안에는 무엇이 쌓여 있나\n색인 :: 이웃 지도. 어디부터 뒤질지 정한다\n벡터 :: 뜻을 숫자로 바꿔 놓은 목록\n원본 조각 :: 검색에 걸렸을 때 실제로 꺼내 주는 글\n= 색인은 벡터 위에 얹혀 있고, 벡터는 원본 조각을 가리키는 표일 뿐이다\n```"},"recap":"**\"같은 것 말고 가까운 것을 찾아 주는 그 창고\"** 라고 읽으면 된다. 완벽한 답 대신 속도를 택한 구조이고, 검색 품질 자체는 임베딩과 문서 자르기가 정한다.","kid":"도서관에 책이 아무렇게나 꽂혀 있지 않고 비슷한 얘기끼리 한 칸에 모여 있지? 제목이 정확히 기억 안 나도 그 칸으로 가면 찾던 게 그 근처에 있어. 그래서 백만 권을 다 뒤지지 않고 그 칸 안만 훑어보고 금방 꺼내 줘.","check":[{"q":"백만 개를 다 계산하지 않는데 어떻게 가까운 것을 찾나","at":"해결하는 문제"},{"q":"검색 결과가 나쁠 때 저장소를 바꾸는 게 답이 아닌 이유는","at":"흔한 오해"},{"q":"권한 필터를 검색 뒤에 적용하면 무엇이 문제인가","at":"주의사항"}],"myths":[{"wrong":"벡터 DB가 항상 정확한 답을 준다","right":"근사 검색이라 가장 가까운 것을 놓칠 수 있다. 정확도와 속도를 설정으로 조절한다."},{"wrong":"일반 데이터베이스를 대체한다","right":"대체하지 않는다. 주문 내역처럼 정확히 일치하는 조회는 여전히 관계형이 맞다."},{"wrong":"넣기만 하면 검색이 좋아진다","right":"검색 품질은 임베딩 모델과 문서를 어떻게 잘랐는지가 정한다. 저장소는 빠르게 찾아줄 뿐이다."}],"cases":[{"label":"RAG 저장소","note":"사내 문서를 조각내 넣어두고 질문과 가까운 조각을 꺼낸다."},{"label":"이미지 검색","note":"사진을 벡터로 넣어두면 비슷한 사진을 찾을 수 있다."},{"label":"중복 문의 묶기","note":"표현이 다른 같은 문의를 벡터 거리로 묶어 한 번에 처리한다."}],"dia":{"shape":"흐름","title":"백만 개 중에서 가까운 셋을 어떻게 찾나","rows":[{"who":"질문","what":"벡터 하나가 들어온다"},{"who":"색인","what":"미리 만들어둔 이웃 지도를 탄다"},{"who":"색인","what":"가까운 후보 구역으로 건너뛴다"},{"who":"색인","what":"그 안에서만 실제 거리를 잰다"},{"who":"결과","what":"가장 가까운 셋을 돌려준다","back":true}],"sum":"백만 개를 다 재지 않는 대신 정확도를 조금 내주는 거래다"}},"ai--term-c69518b3":{"definition":"모델 안에는 맞춰야 할 수가 수없이 많다. 전부 시험해 볼 수는 없으므로, 지금 자리에서 어느 쪽으로 가야 틀림이 줄어드는지만 보고 그쪽으로 한 걸음 옮긴다. 이것을 끝없이 되풀이하는 것이 학습이다.","name":"Gradient :: 기울기\nDescent :: 내려가기\n= 붙여 읽으면 \"기울기를 따라 내려가기\". 어디가 바닥인지는 모르고 발밑만 본다","analogy":"안개 낀 산에서 내려오는 법. 산 전체는 안 보여도 발밑이 어느 쪽으로 기울었는지는 알 수 있어서, 그쪽으로 한 걸음씩 딛는다.","example":"학습 화면에서 숫자 하나가 뚝뚝 떨어지다가 어느 순간부터 거의 안 줄어드는 것을 본 적이 있다면, 그것이 이 걸음의 기록이다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"한 걸음의 크기를 정하는 값이 따로 있다. 너무 작으면 바닥까지 가는 데 한없이 걸리고, 너무 크면 골짜기를 건너뛰어 오히려 위로 튀어 오른다. 이 값 하나를 잘못 잡으면 학습이 아예 안 된다.\n\n걸음마다 자료를 전부 보지도 않는다. 한 번에 수십 개씩만 뽑아 그 묶음으로 기울기를 어림한다. 어림이라 걸음이 조금 비틀거리지만, 같은 시간에 딛는 걸음 수가 훨씬 많아진다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **숫자가 안 떨어질 때** — 보폭을 줄이는 것이 대개 첫 손질이다. 튀어 오르고 있었을 가능성이 크다.\n- **가면서 보폭을 줄이는 방식** — 처음에는 성큼 걷다가 바닥에 가까워질수록 잘게 딛도록 걸음 크기를 서서히 줄인다.\n- **값이 커지지 않게 붙잡기** — 값이 너무 커지면 벌점을 같이 재도록 해 두면 [[과적합]] 이 줄어든다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **가장 좋은 답을 찾아 준다** — 아니다. 가까운 골짜기 하나를 찾을 뿐이다. 시작 자리가 다르면 다른 골짜기에 앉는다.\n- **보폭은 크게 잡을수록 빠르다** — 어느 선을 넘으면 골짜기를 건너뛰어 값이 튀어 오른다. 빨라지는 게 아니라 아예 안 된다.\n- **틀림이 0 이 되면 끝난 것이다** — 배운 자료에서 0 이 된 것은 다 외웠다는 뜻일 수 있다. [[과적합]] 을 먼저 의심한다."}],"figure":"```도해\n흐름: 모델 안의 수많은 값이 어떻게 맞춰지나\n맞혀 보기 :: 지금 값으로 답을 내 본다\n재기 :: 답과 정답의 차이를 숫자 하나로 만든다\n기울기 :: 그 숫자를 줄이는 쪽이 어느 쪽인지 값마다 구한다\n옮기기 :: 줄이는 쪽으로 정해진 보폭만큼 민다\n@ 다시 맞히기로 :: 더 안 줄어들 때까지 되풀이한다\n= 정답을 계산해 내는 게 아니라, 틀림을 조금씩 깎아 다가가는 것이다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 맞는 값을 찾으려고 전부 시험해 보면 어떻게 되나\n다 해 보기 || 기울기 따라가기\n경우의 수 :: 끝이 없다 || 한 방향만 본다\n한 걸음 값 :: 전부 다시 잰다 || 한 번에 구한다\n값이 많아지면 :: 손도 못 댄다 || 그대로 된다\n= 어디가 바닥인지 몰라도, 지금 어느 쪽이 내리막인지는 알 수 있다\n```\n\n맞춰야 할 값이 백만 개라면 값마다 몇 가지씩만 시험해 봐도 경우의 수가 헤아릴 수 없이 커진다. 전부 해 보는 길은 처음부터 없다.\n\n대신 지금 서 있는 자리에서 각 값을 조금 늘리면 틀림이 늘어나는지 줄어드는지를 구한다. 그 방향을 모두 모으면 \"지금 자리에서 어느 쪽이 내리막인가\" 가 나온다. 그쪽으로 한 걸음 딛고, 새 자리에서 다시 구한다. 산 전체를 볼 필요 없이 발밑만 보면 되는 것이 이 방법의 값이다."},"recap":"**\"안개 속에서 발밑만 보고 내려가는 그 걸음\"** 이라고 읽으면 된다. 어디가 바닥인지 몰라도 지금 어느 쪽이 내리막인지는 알 수 있어서, 그 걸음을 끝없이 되풀이하는 것이 학습이다. 보폭 하나가 되고 안 되고를 가른다.","kid":"안개가 짙어서 한 발 앞도 안 보이는 산에 있다고 해 봐. 어디가 아래인지는 안 보여도 발끝으로 더듬으면 어느 쪽이 내리막인지는 알 수 있지? 그쪽으로 한 걸음씩 계속 딛는 것, 얘가 배우는 방법이 딱 이거야.","check":[{"q":"학습 중에 숫자가 줄기는커녕 튀어 오른다. 무엇을 먼저 줄이나","at":"작동 원리"},{"q":"같은 자료로 두 번 학습했는데 결과가 다르다. 왜","at":"흔한 오해"},{"q":"값을 전부 시험해 보지 않는 이유는","at":"해결하는 문제"}],"myths":[{"wrong":"가장 좋은 답을 찾아 준다","right":"아니다. 가까운 골짜기 하나를 찾을 뿐이다. 시작 자리가 다르면 다른 골짜기에 앉는다."},{"wrong":"보폭은 크게 잡을수록 빠르다","right":"어느 선을 넘으면 골짜기를 건너뛰어 값이 튀어 오른다. 빨라지는 게 아니라 아예 안 된다."},{"wrong":"틀림이 0 이 되면 끝난 것이다","right":"배운 자료에서 0 이 된 것은 다 외웠다는 뜻일 수 있다. [[과적합]] 을 먼저 의심한다."}],"cases":[{"label":"숫자가 안 떨어질 때","note":"보폭을 줄이는 것이 대개 첫 손질이다. 튀어 오르고 있었을 가능성이 크다."},{"label":"가면서 보폭을 줄이는 방식","note":"처음에는 성큼 걷다가 바닥에 가까워질수록 잘게 딛도록 걸음 크기를 서서히 줄인다."},{"label":"값이 커지지 않게 붙잡기","note":"값이 너무 커지면 벌점을 같이 재도록 해 두면 [[과적합]] 이 줄어든다."}],"dia":{"shape":"흐름","title":"모델 안의 수많은 값이 어떻게 맞춰지나","rows":[{"who":"맞혀 보기","what":"지금 값으로 답을 내 본다"},{"who":"재기","what":"답과 정답의 차이를 숫자 하나로 만든다"},{"who":"기울기","what":"그 숫자를 줄이는 쪽이 어느 쪽인지 값마다 구한다"},{"who":"옮기기","what":"줄이는 쪽으로 정해진 보폭만큼 민다"}],"sum":"정답을 계산해 내는 게 아니라, 틀림을 조금씩 깎아 다가가는 것이다","loop":{"who":"다시 맞히기로","what":"더 안 줄어들 때까지 되풀이한다"}}},"ai--term-ffd91e00":{"definition":"배운 자료에서는 점수가 계속 오르는데 처음 보는 자료에서는 오히려 떨어지기 시작한다. 자료에 담긴 규칙이 아니라 그 자료에만 있던 잡음까지 같이 외워 버린 것이다.","name":"Over :: 지나치게\nFitting :: 맞춰 넣기\n= 붙여 읽으면 \"지나치게 맞춰 넣기\". 잘 맞춘 것이 아니라 너무 맞춘 것이 문제다","analogy":"기출문제만 외운 수험생. 본 문제는 다 맞히는데 숫자 하나만 바뀌어도 손을 못 댄다.","example":"연습 점수가 99% 인데 실제로 써 보니 반도 못 맞히는 모델을 만나면 대개 이것이다.","sections":[{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 덜 맞춤 · 알맞음 · 지나친 맞춤","body":"| | 과소적합 | 알맞음 | 과적합 |\n|---|---|---|---|\n| 배운 자료 | 못 맞힌다 | 잘 맞힌다 | 거의 다 맞힌다 |\n| 처음 보는 자료 | 못 맞힌다 | 잘 맞힌다 | 못 맞힌다 |\n| 왜 | 너무 단순하다 | 알맞다 | 너무 복잡하다 |\n| 할 일 | 더 복잡하게 | 그대로 둔다 | 더 단순하게 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **자료가 적은데 모델이 큰 경우** — 예가 천 개인데 맞출 값이 백만 개면 외우는 쪽이 더 쉽다.\n- **너무 오래 돌린 경우** — 같은 자료를 몇백 번 되풀이해 보여 주면 어느 순간부터 외우기 시작한다.\n- **미리 알 수 없는 것을 흘린 경우** — 맞혀야 할 값과 사실상 같은 것이 자료에 섞여 있으면 연습에서만 완벽해진다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **연습 점수가 높으면 좋은 모델이다** — 배운 자료로 잰 점수는 실력이 아니라 기억력이다. 안 본 자료로 재야 실력이다.\n- **자료를 더 넣으면 무조건 해결된다** — 도움이 되지만, 넣는 자료가 기존 것과 비슷하면 외울 것만 늘어난다.\n- **모델이 클수록 좋다** — 자료에 비해 크면 외우는 쪽이 쉬워진다. 자료 양에 맞는 크기가 따로 있다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **재는 자료를 배움에 쓰지 않는다.** 한 번이라도 섞이면 그 자료로 잰 점수는 더 이상 남의 눈이 아니다.\n- **여러 번 고르는 사이에도 스며든다.** 재기용 자료를 보면서 설정을 스무 번 바꾸면 그 자료에 맞춘 셈이 된다. 그래서 마지막에 한 번만 여는 몫을 따로 둔다."}],"figure":"```도해\n대조: 배운 자료와 처음 보는 자료에서 점수가 갈리는 이유는 무엇인가\n배운 자료 |=| 처음 보는 자료\n점수 :: 계속 오른다 || 어느 순간 떨어진다\n외운 잡음 :: 도움이 된다 || 방해가 된다\n더 복잡하게 :: 더 좋아 보인다 || 더 나빠진다\n= 두 점수가 갈라지기 시작하는 그 지점이 그만둘 때다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 배운 자료의 점수만 보고 있으면 무엇을 놓치나\n그 점수만 보면 || 따로 떼어 재면\n좋아졌나 :: 늘 좋아 보인다 || 진짜인지 갈린다\n멈출 때 :: 알 수가 없다 || 갈라질 때 멈춘다\n실제로 쓰면 :: 거기서 무너진다 || 미리 안다\n= 배운 자료로 잰 점수는 실력이 아니라 기억력이다\n```\n\n모델을 복잡하게 만들수록 배운 자료는 더 잘 맞힌다. 끝까지 밀면 배운 자료를 통째로 외워 100% 가 된다. 그 숫자만 보고 있으면 언제 멈춰야 하는지 알 길이 없다.\n\n그래서 자료를 처음부터 나눠 둔다. 배우는 데 쓸 몫과, 배움에 한 번도 안 쓰고 재기만 할 몫이다. 두 점수가 같이 오르는 동안은 배우는 중이고, 한쪽만 오르기 시작하면 외우는 중이다. 갈라지는 그 지점이 멈출 자리다."},"recap":"**\"기출만 외운 그 수험생\"** 이라고 읽으면 된다. 자료의 규칙이 아니라 잡음까지 외운 상태이고, 배운 자료로 잰 점수로는 알아챌 수가 없다. 안 본 자료로 재는 것이 유일한 방법이다.","kid":"시험공부 할 때 기출문제 답만 통째로 외운 애가 있다고 해 봐. 그 문제 그대로 나오면 다 맞는데, 숫자만 살짝 바꿔 놓으면 하나도 못 풀지? 배운 게 푸는 법이 아니라 답 자체였던 거야.","check":[{"q":"연습 점수가 99% 인데 왜 못 믿나","at":"해결하는 문제"},{"q":"같은 자료를 오래 돌리면 어느 순간 무엇이 시작되나","at":"실제 사례"},{"q":"재기용 자료를 보면서 설정을 자꾸 바꾸면 무엇이 무너지나","at":"주의사항"}],"myths":[{"wrong":"연습 점수가 높으면 좋은 모델이다","right":"배운 자료로 잰 점수는 실력이 아니라 기억력이다. 안 본 자료로 재야 실력이다."},{"wrong":"자료를 더 넣으면 무조건 해결된다","right":"도움이 되지만, 넣는 자료가 기존 것과 비슷하면 외울 것만 늘어난다."},{"wrong":"모델이 클수록 좋다","right":"자료에 비해 크면 외우는 쪽이 쉬워진다. 자료 양에 맞는 크기가 따로 있다."}],"cases":[{"label":"자료가 적은데 모델이 큰 경우","note":"예가 천 개인데 맞출 값이 백만 개면 외우는 쪽이 더 쉽다."},{"label":"너무 오래 돌린 경우","note":"같은 자료를 몇백 번 되풀이해 보여 주면 어느 순간부터 외우기 시작한다."},{"label":"미리 알 수 없는 것을 흘린 경우","note":"맞혀야 할 값과 사실상 같은 것이 자료에 섞여 있으면 연습에서만 완벽해진다."}],"dia":{"shape":"대조","title":"배운 자료와 처음 보는 자료에서 점수가 갈리는 이유는 무엇인가","rows":[{"who":"","what":"배운 자료 || 처음 보는 자료","left":"배운 자료","right":"처음 보는 자료","even":true},{"who":"점수","what":"계속 오른다 || 어느 순간 떨어진다","left":"계속 오른다","right":"어느 순간 떨어진다"},{"who":"외운 잡음","what":"도움이 된다 || 방해가 된다","left":"도움이 된다","right":"방해가 된다"},{"who":"더 복잡하게","what":"더 좋아 보인다 || 더 나빠진다","left":"더 좋아 보인다","right":"더 나빠진다"}],"sum":"두 점수가 갈라지기 시작하는 그 지점이 그만둘 때다"}},"ai--term-7edc1a6b":{"definition":"규칙을 사람이 적어 주는 대신, 층마다 놓인 수많은 곱셈과 덧셈의 계수를 자료로 맞춰 간다. 고양이를 알아보는 규칙을 아무도 적지 않았는데 알아보게 되는 것이 이 구조의 성질이다.","name":"Neural :: 신경의\nNetwork :: 이어진 그물\n= 붙여 읽으면 \"신경처럼 이어진 그물\". 뇌를 본떴다는 이름이지 뇌와 같다는 뜻은 아니다","analogy":"체를 여러 겹 겹쳐 놓은 것. 처음 체는 굵은 것만 거르고, 뒤로 갈수록 잘게 걸러서 마지막에는 찾던 것만 남는다.","example":"사진첩 앱이 사람 얼굴별로 알아서 묶어 주는 그 기능이 이 구조로 만들어져 있다.","sections":[{"slot":"how","label":"어떻게 작동하나","head":"⚙️ 작동 원리","body":"마디 하나가 하는 일은 단순하다. 들어온 숫자마다 정해진 무게를 곱해 전부 더하고, 그 합을 한 번 구부린다. 구부리는 일이 빠지면 층을 백 겹 쌓아도 한 겹과 똑같아진다. 곱셈과 덧셈만 겹쳐 봐야 여전히 곱셈과 덧셈이기 때문이다.\n\n배우는 일은 그 무게를 고치는 일이다. 답이 얼마나 틀렸는지를 숫자로 재고, 그 숫자가 줄어드는 쪽으로 무게를 조금씩 민다. [[경사 하강법]] 이 그 미는 방법이다."},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **사진 속 얼굴 찾기** — 어떤 배치가 얼굴인지 적지 않고 얼굴 사진을 잔뜩 보여 준다.\n- **손글씨 읽기** — 사람마다 다른 글씨체를 규칙으로 적을 수 없어 예로 가르친다.\n- **말을 글로 옮기기** — 소리의 물결에서 글자를 찾는 일도 같은 구조를 쓴다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **뇌를 흉내 낸 것이니 사람처럼 생각한다** — 이름만 빌려 왔다. 실제로 하는 일은 곱셈과 덧셈을 층층이 겹치는 것이다.\n- **층을 깊게 쌓을수록 좋아진다** — 깊을수록 배우기가 어려워지고 [[과적합]] 도 쉬워진다. 일에 맞는 깊이가 따로 있다.\n- **마디 하나가 뜻 하나를 맡는다** — 그렇게 깔끔하지 않다. 한 가지 뜻이 여러 마디에 흩어져 있어서 한 마디만 떼어 보면 아무 말도 안 나온다."}],"figure":"```도해\n층: 사진 한 장이 \"고양이\" 라는 답이 되기까지 무엇을 거치나\n입력층 :: 점 하나하나의 밝기를 숫자 그대로 받는다\n앞쪽 층 :: 선과 모서리 같은 잔 특징이 잡힌다\n뒤쪽 층 :: 귀와 수염처럼 큰 덩어리가 잡힌다\n출력층 :: 후보마다 점수를 내놓는다\n= 층을 지날수록 다루는 단위가 커진다. 그래서 순서를 바꾸면 안 된다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 고양이를 알아보는 규칙을 말로 적어 보면 어떻게 되나\n규칙을 적어서 || 예로 가르쳐서\n알아보기 :: 적어 낼 수가 없다 || 사진을 잔뜩 준다\n예외 :: 규칙이 늘어난다 || 예를 더 준다\n새 대상 :: 처음부터 다시 || 같은 방식 그대로\n= 말로 못 적는 것을 예로 가르치는 자리가 이 구조다\n```\n\n무엇이 고양이인지 규칙으로 적어 보면 곧 막힌다. 귀가 뾰족하다고 적으면 접힌 귀가 걸리고, 털이 있다고 적으면 인형이 걸린다. 사람은 알아보면서도 그 기준을 말로 다 적지 못한다.\n\n신경망은 기준을 적게 하지 않고 예를 보여 준다. 층마다 놓인 계수를 처음에는 아무렇게나 두고, 맞힌 정도에 따라 조금씩 고쳐 나간다. 규칙은 사람의 말이 아니라 그 계수 안에 흩어져 남는다. 알아보게 되었는데도 왜 그런지 설명하기 어려운 이유가 여기 있다."},"recap":"**\"겹쳐 놓은 그 체\"** 라고 읽으면 된다. 층을 지날수록 다루는 단위가 커지고, 규칙은 사람의 말이 아니라 층마다의 무게 안에 남는다. 그래서 알아보면서도 설명하지 못한다.","kid":"모래를 체에 내릴 때 굵은 체를 먼저 쓰고 그다음에 고운 체를 쓰지? 한 번에 다 거르려고 하면 잘 안 되는데, 여러 번 나눠 거르면 찾던 것만 딱 남잖아. 이것도 숫자를 여러 겹으로 나눠 거르는 거야.","check":[{"q":"층을 백 겹 쌓았는데 한 겹과 다를 게 없다. 무엇이 빠졌나","at":"작동 원리"},{"q":"왜 그렇게 답했는지 설명하기 어려운 이유는","at":"해결하는 문제"},{"q":"앞쪽 층과 뒤쪽 층이 잡는 것이 어떻게 다른가","at":"그림"}],"myths":[{"wrong":"뇌를 흉내 낸 것이니 사람처럼 생각한다","right":"이름만 빌려 왔다. 실제로 하는 일은 곱셈과 덧셈을 층층이 겹치는 것이다."},{"wrong":"층을 깊게 쌓을수록 좋아진다","right":"깊을수록 배우기가 어려워지고 [[과적합]] 도 쉬워진다. 일에 맞는 깊이가 따로 있다."},{"wrong":"마디 하나가 뜻 하나를 맡는다","right":"그렇게 깔끔하지 않다. 한 가지 뜻이 여러 마디에 흩어져 있어서 한 마디만 떼어 보면 아무 말도 안 나온다."}],"cases":[{"label":"사진 속 얼굴 찾기","note":"어떤 배치가 얼굴인지 적지 않고 얼굴 사진을 잔뜩 보여 준다."},{"label":"손글씨 읽기","note":"사람마다 다른 글씨체를 규칙으로 적을 수 없어 예로 가르친다."},{"label":"말을 글로 옮기기","note":"소리의 물결에서 글자를 찾는 일도 같은 구조를 쓴다."}],"dia":{"shape":"층","title":"사진 한 장이 \"고양이\" 라는 답이 되기까지 무엇을 거치나","rows":[{"who":"입력층","what":"점 하나하나의 밝기를 숫자 그대로 받는다"},{"who":"앞쪽 층","what":"선과 모서리 같은 잔 특징이 잡힌다"},{"who":"뒤쪽 층","what":"귀와 수염처럼 큰 덩어리가 잡힌다"},{"who":"출력층","what":"후보마다 점수를 내놓는다"}],"sum":"층을 지날수록 다루는 단위가 커진다. 그래서 순서를 바꾸면 안 된다"}},"ai--term-ddd274d7":{"definition":"자료마다 맞는 답을 사람이 미리 달아 둔다. 사진에는 \"고양이\", 메일에는 \"광고\" 같은 식이다. 모델은 그 짝을 잔뜩 보면서 자료에서 답으로 가는 길을 스스로 맞춰 간다. 맞혀야 할 답이 둘 중 하나인지, 여럿 중 하나인지, 숫자 하나인지에 따라 갈래가 나뉜다.","name":"Supervised :: 감독이 붙은\nLearning :: 배우기\n= 붙여 읽으면 \"감독이 붙은 배우기\". 감독이란 곁에 달아 둔 정답을 말한다","analogy":"답지가 딸린 문제집. 풀고 나서 바로 맞춰 볼 수 있으니 어디서 틀렸는지 알고 고칠 수 있다.","example":"메일함이 광고 메일을 알아서 걸러 주는 것은, 사람들이 신고 단추를 누른 기록이 곧 정답표였기 때문이다.","tryit":"쓰는 앱에서 \"이 추천이 마음에 안 들어요\" 같은 단추를 찾아보라. 그런 단추가 곧 정답을 모으는 자리다.","sections":[{"slot":"compare","label":"무엇과 비교되나","head":"📊 비교: 무엇을 맞히느냐로 갈린다","body":"| | 둘 중 하나 | 여럿 중 하나 | 숫자 하나 |\n|---|---|---|---|\n| 묻는 말 | 광고인가 아닌가 | 책·영화·옷 중 무엇인가 | 내일 기온은 몇 도인가 |\n| 답의 모양 | 예 또는 아니오 | 정해진 항목 하나 | 이어진 수 |\n| 틀림을 재는 법 | 맞힌 비율 | 맞힌 비율 | 얼마나 빗나갔나 |"},{"slot":"example","label":"실제 사례","head":"💡 실제 사례","body":"- **광고 메일 걸러내기** — 사람이 신고한 메일이 그대로 정답표가 된다.\n- **연체 예측** — 지난 대출 기록에 갚았는지 아닌지가 이미 붙어 있어 정답표를 새로 만들 필요가 없다.\n- **불량 골라내기** — 공장에서 찍은 사진에 검사원이 붙인 판정이 정답표다."},{"slot":"myth","label":"흔히 잘못 아는 것","head":"🚫 흔한 오해","body":"- **정답표는 한 번 만들면 끝이다** — 세상이 바뀌면 답도 바뀐다. 옛 정답표로 배운 모델은 새 상황에서 조용히 틀린다.\n- **많이 모을수록 좋다** — 잘못 달린 답이 섞이면 그만큼 잘못 배운다. 답의 수보다 답의 정확함이 앞선다.\n- **답만 붙이면 무엇이든 배운다** — 답의 단서가 자료 안에 없으면 못 배운다. 이름만 보고 성적을 맞히라는 식이면 답표가 있어도 소용없다."},{"slot":"caution","label":"주의할 점","head":"🚨 주의사항","body":"- **답표에 든 치우침을 그대로 배운다.** 지난 결정이 한쪽으로 기울어 있었다면 모델이 그 기울기를 이어받는다.\n- **답이 답을 흘리지 않게 한다.** 맞힐 때는 알 수 없는 정보가 자료에 섞여 들어가면 연습에서만 잘 맞힌다."}],"figure":"```도해\n흐름: 정답이 붙은 예가 어떻게 배움이 되나\n모으기 :: 자료마다 사람이 답을 달아 둔다\n맞히기 :: 답을 가리고 모델이 먼저 답해 본다\n재기 :: 제 답과 달아 둔 답의 차이를 숫자로 센다\n@ 다시 맞히기로 :: 그 숫자가 줄도록 고치고 한 바퀴 더 돈다\n= 정답표가 없으면 이 고리가 아예 안 돈다\n```","why":{"label":"왜 필요한가","head":"⚠️ 해결하는 문제","body":"```도해\n대조: 답을 안 달고 예만 잔뜩 주면 어떻게 되나\n답표 없이 || 답표와 함께\n맞았는지 :: 알 수가 없다 || 바로 센다\n고칠 방향 :: 어느 쪽인지 모른다 || 줄어드는 쪽으로\n끝났는지 :: 판단이 안 선다 || 틀린 수로 본다\n= 답표는 배움의 재료가 아니라 배움을 재는 자다\n```\n\n예만 잔뜩 주면 모델은 서로 닮은 것끼리 묶는 정도밖에 못 한다. 묶어 놓고도 그 묶음이 맞는지 틀린지는 아무도 모른다. 잴 자가 없기 때문이다.\n\n정답을 달아 두면 그 순간 자가 생긴다. 제 답과 달린 답의 차이를 숫자로 셀 수 있고, 그 숫자가 줄도록 고칠 수 있고, 더 안 줄면 멈출 수 있다. 이 방식이 비싸다고들 하는 이유도 여기서 나온다. 답을 다는 일은 대개 사람이 손으로 해야 한다."},"recap":"**\"답지를 옆에 놓고 푸는 그 문제집\"** 이라고 읽으면 된다. 답이 붙어 있어야 틀린 정도를 셀 수 있고, 세야 고칠 수 있다. 그래서 이 방식의 값은 대부분 답을 다는 데 들어간다.","kid":"문제집 뒤에 답지가 붙어 있으면 풀고 나서 바로 맞춰 볼 수 있지? 답지가 없으면 백 문제를 풀어도 잘하고 있는지조차 모르잖아. 얘도 답지를 옆에 놓고, 틀린 만큼 고쳐 가면서 배워.","check":[{"q":"자료를 백만 개 모았는데 나아지지 않는다. 무엇을 먼저 의심하나","at":"흔한 오해"},{"q":"연습에서는 잘 맞혔는데 실제로 틀린다. 어떤 실수를 했을 수 있나","at":"주의사항"},{"q":"\"내일 기온\" 과 \"광고인가\" 는 재는 법이 어떻게 다른가","at":"비교"}],"myths":[{"wrong":"정답표는 한 번 만들면 끝이다","right":"세상이 바뀌면 답도 바뀐다. 옛 정답표로 배운 모델은 새 상황에서 조용히 틀린다."},{"wrong":"많이 모을수록 좋다","right":"잘못 달린 답이 섞이면 그만큼 잘못 배운다. 답의 수보다 답의 정확함이 앞선다."},{"wrong":"답만 붙이면 무엇이든 배운다","right":"답의 단서가 자료 안에 없으면 못 배운다. 이름만 보고 성적을 맞히라는 식이면 답표가 있어도 소용없다."}],"cases":[{"label":"광고 메일 걸러내기","note":"사람이 신고한 메일이 그대로 정답표가 된다."},{"label":"연체 예측","note":"지난 대출 기록에 갚았는지 아닌지가 이미 붙어 있어 정답표를 새로 만들 필요가 없다."},{"label":"불량 골라내기","note":"공장에서 찍은 사진에 검사원이 붙인 판정이 정답표다."}],"dia":{"shape":"흐름","title":"정답이 붙은 예가 어떻게 배움이 되나","rows":[{"who":"모으기","what":"자료마다 사람이 답을 달아 둔다"},{"who":"맞히기","what":"답을 가리고 모델이 먼저 답해 본다"},{"who":"재기","what":"제 답과 달아 둔 답의 차이를 숫자로 센다"}],"sum":"정답표가 없으면 이 고리가 아예 안 돈다","loop":{"who":"다시 맞히기로","what":"그 숫자가 줄도록 고치고 한 바퀴 더 돈다"}}}};
